/* Sistema de Gestión de Música 4.2.25 · correcciones offline, admin total secundario y sincronización multi-dispositivo. */
let V3_PROGRAM_CATALOG = window.__PROGRAM_CATALOG__ || null;
let v3ProgramDefinitions = {};
let v3ActiveProgramId = 'music_ministry';
let v3ModalProgramId = 'music_ministry';
