function v3CanAttemptNetwork() {
  // Android WebView puede mantener navigator.onLine=false durante transiciones
  // Wi-Fi/datos aunque HTTPS ya responda. En acceso remoto, la petición real manda.
  // El Administrador local tambien debe intentar el proxy 127.0.0.1 aun cuando
  // Windows informe que no hay Internet: el servidor SGL vive en el mismo equipo.
  if (REMOTE_WEB || navigator.onLine) return true;
  try { return v3UseLocalAdminProxy(); } catch { return false; }
}

const V3_ORIGINAL = {
  blankDatabase,
  migrateDatabase,
  loadEmbeddedCatalogs,
  renderBootstrap,
  renderShell,
  navItems,
  renderNav,
  go,
  renderDashboard,
  renderBible,
  openUser,
  saveUser,
  importUsers,
  showAssignedTaskReminder,
  renderSettings,
  renderTopSync,
  syncNow,
  reportBaseName,
  renderAspirants,
  openAspirant
};

function v3BuildProgramDefinitions(){v3ProgramDefinitions=V3_PROGRAM_CATALOG?.programs?.music_ministry?{music_ministry:V3_PROGRAM_CATALOG.programs.music_ministry}:{};}

loadEmbeddedCatalogs = async function loadEmbeddedCatalogsV3() {
  await V3_ORIGINAL.loadEmbeddedCatalogs();
  if (!V3_PROGRAM_CATALOG) {
    if (window.__PROGRAM_CATALOG__) V3_PROGRAM_CATALOG = window.__PROGRAM_CATALOG__;
    else if (window.__PROGRAM_DATA_GZIP__) V3_PROGRAM_CATALOG = await inflateEmbeddedJson(window.__PROGRAM_DATA_GZIP__);
    else V3_PROGRAM_CATALOG = {programs:{}};
  }
  v3BuildProgramDefinitions();
};

function v3Program(id=v3ActiveProgramId) {
  return v3ProgramDefinitions[id] || v3ProgramDefinitions.music_ministry;
}

function v3ProgramAreas(programId=v3ActiveProgramId) {
  return v3Program(programId)?.areas || [];
}

function v3ProgramRequirements(programId=v3ActiveProgramId) {
  return v3ProgramAreas(programId).flatMap(area => (area.requirements || []).map(requirement => ({
    ...requirement,
    // Temperancia is a fixed specialty, not a choice from an empty catalog.
    ...(programId==='class_grouped'&&requirement.id==='V-05'?{selection:null}:{}),
    programId,
    areaCode:area.code,
    areaTitle:area.title,
    areaShort:area.short || AREA_SHORT[area.code] || area.code
  })));
}

function v3RequirementById(requirementId, programId=v3ActiveProgramId) {
  return v3ProgramRequirements(programId).find(item => item.id === requirementId) || null;
}

function v3FindProgramForRequirement(requirementId) {
  for (const programId of Object.keys(v3ProgramDefinitions)) {
    if (v3RequirementById(requirementId, programId)) return programId;
  }
  return 'class_grouped';
}

function v3DefaultModules() {
  return Object.keys(v3ProgramDefinitions).map(programId => ({
    id:programId,
    active:programId === 'music_ministry',
    assignedUserIds:[],
    createdAt:isoNow(),
    updatedAt:null
  }));
}

blankDatabase = function blankDatabaseV3() {
  const next = V3_ORIGINAL.blankDatabase();
  next.schemaVersion = 8;
  next.modules = v3DefaultModules();
  next.programProgress = {};
  next.bibleYear = {};
  next.syncNotifications = [];
  next.syncRequestsCache = [];
  next.sync ||= {};
  next.sync.pendingProposal = null;
  return next;
};

/* SGL 5.1 - migracion no destructiva de codigos oficiales de Guia Mayor Master. */
function sgl50100MigrateGuideMasterRequirementIds(){
  database.migrations ||= {};
  if(database.migrations.guideMasterOfficial50100)return;
  const map={'GMM-CA-1':'GMM-LA-1','GMM-CA-2':'GMM-LA-2','GMM-CA-3':'GMM-CA-1'};
  const remapRecord=(record)=>{
    if(!record||typeof record!=='object'||Array.isArray(record))return;
    const old={};for(const id of Object.keys(map))if(Object.prototype.hasOwnProperty.call(record,id))old[id]=record[id];
    for(const id of Object.keys(map))delete record[id];
    for(const [oldId,newId] of Object.entries(map))if(Object.prototype.hasOwnProperty.call(old,oldId))record[newId]=old[oldId];
  };
  for(const programs of Object.values(database.programProgress||{})){
    const progress=programs?.guide_master;if(!progress)continue;
    remapRecord(progress.status);remapRecord(progress.submissions);remapRecord(progress.readings);
  }
  for(const collectionName of ['tasks','materials','indicationRules']){
    for(const item of database[collectionName]||[]){
      if((item.programId||'class_grouped')==='guide_master'&&map[item.requirementId])item.requirementId=map[item.requirementId];
    }
  }
  if(database.configs&&typeof database.configs==='object'){
    const grouped=new Map();
    for(const [key,value] of Object.entries(database.configs)){
      const match=key.match(/^(guide_master:[^:]+:)(GMM-CA-[123])$/);if(!match)continue;
      const prefix=match[1];if(!grouped.has(prefix))grouped.set(prefix,{});grouped.get(prefix)[match[2]]=value;
    }
    for(const [prefix,old] of grouped){
      for(const id of Object.keys(map))delete database.configs[prefix+id];
      for(const [oldId,newId] of Object.entries(map))if(Object.prototype.hasOwnProperty.call(old,oldId))database.configs[prefix+newId]=old[oldId];
    }
  }
  database.migrations.guideMasterOfficial50100={at:isoNow(),mapping:map};
}

const SGL528_CANONICAL_REPAIR_KEY='sgl_528_canonical_repair_20260918';
function sgl528CanonicalRepairDone(){
  try{return localStorage.getItem(SGL528_CANONICAL_REPAIR_KEY)==='done';}catch{return false;}
}
function sgl528MarkCanonicalRepairDone(){
  try{localStorage.setItem(SGL528_CANONICAL_REPAIR_KEY,'done');}catch{}
}

migrateDatabase = function migrateDatabaseV3() {
  sglRepairIncident593(database);
  const priorClientVersion=String(database?.version||'');
  V3_ORIGINAL.migrateDatabase();
  database.modules = Array.isArray(database.modules) ? database.modules : v3DefaultModules();
  for (const programId of Object.keys(v3ProgramDefinitions)) {
    let module = database.modules.find(item => item.id === programId);
    if (!module) {
      module = {id:programId,active:programId === 'music_ministry',assignedUserIds:[],createdAt:isoNow(),updatedAt:null};
      database.modules.push(module);
    }
    module.assignedUserIds = Array.isArray(module.assignedUserIds) ? [...new Set(module.assignedUserIds)] : [];
    if (programId === 'class_grouped' && module.active === undefined) module.active = true;
  }
  database.modules = database.modules.filter(item => v3ProgramDefinitions[item.id]);
  database.programProgress ||= {};
  database.bibleYear ||= {};
  database.syncNotifications = Array.isArray(database.syncNotifications) ? database.syncNotifications : [];
  database.syncRequestsCache = Array.isArray(database.syncRequestsCache) ? database.syncRequestsCache : [];
  database.sync ||= {state:'local',lastSyncedAt:null,message:'Guardado en este dispositivo',needsUpload:false};
  database.sync.pendingProposal ||= null;
  database.sync.needsUpload = database.sync.needsUpload === true;
  // 5.28 always performs one authoritative pull after upgrading from 5.27 or older.
  // This also makes the installed version visible while repairing any stale local
  // approval state before the client trusts its previous high-water mark.
  if((priorClientVersion&&priorClientVersion!=='5.47')||!sgl528CanonicalRepairDone())database.sync.forceCanonicalPull528=true;
  sgl50100MigrateGuideMasterRequirementIds();
  database.sync.hasLocalDraft = (()=>{try{return !!localStorage.getItem('musica_emergency_draft');}catch{return false;}})();
  for (const task of database.tasks || []) task.programId ||= 'class_grouped';
  for (const material of database.materials || []) material.programId ||= 'class_grouped';
  for (const rule of database.indicationRules || []) rule.programId ||= 'class_grouped';
  for (const aspirant of database.users.filter(item => ['aspirant','pastor_aspirant'].includes(item.role))) {
    const assignedSomewhere = database.modules.some(module => module.assignedUserIds.includes(aspirant.id));
    for (const programId of v3AssignedProgramIds(aspirant)) v3EnsureProgramProgress(aspirant.id, programId);
  }
  database.schemaVersion = 8;
  database.version = APP_VERSION;
};

function v3ModuleRecord(programId) {
  return database.modules.find(item => item.id === programId) || null;
}

function v3AssignedProgramIds(user) {
  if (!user) return [];
  if (user.role === 'admin') return database.modules.filter(item => item.active !== false).map(item => item.id);
  if (user.role === 'regional') return database.modules.filter(item => item.active !== false && REGIONAL_PROGRAM_IDS.includes(item.id)).map(item => item.id);
  if (user.role === 'tutor') {
    const ids = new Set();
    for (const aspirant of accessibleAspirants(user)) {
      for (const module of database.modules) if (module.active !== false && module.assignedUserIds.includes(aspirant.id) && sgl545HasTutor(aspirant,user.id,module.id)) ids.add(module.id);
    }
    return [...ids];
  }
  return database.modules.filter(item => item.active !== false && item.assignedUserIds.includes(user.id)).map(item => item.id);
}

function v3UserHasProgram(user, programId) {
  if (!user) return false;
  if (user.role === 'admin') return !!v3ModuleRecord(programId)?.active;
  if (user.role === 'regional') return REGIONAL_PROGRAM_IDS.includes(programId) && !!v3ModuleRecord(programId)?.active;
  if (user.role === 'tutor') return v3AssignedProgramIds(user).includes(programId);
  const module = v3ModuleRecord(programId);
  return !!module && module.active !== false && module.assignedUserIds.includes(user.id);
}

function v3ProgramsForUser(user=currentUser()) {
  return v3AssignedProgramIds(user).map(v3Program).filter(Boolean);
}

function v3EnsureProgramProgress(userId, programId=v3ActiveProgramId) {
  if (programId === 'class_grouped') return ensureProgress(userId);
  database.programProgress[userId] ||= {};
  database.programProgress[userId][programId] ||= {status:{},submissions:{},readings:{},updatedAt:isoNow()};
  const progress = database.programProgress[userId][programId];
  progress.status ||= {};
  progress.submissions ||= {};
  progress.readings ||= {};
  for (const requirement of v3ProgramRequirements(programId)) progress.status[requirement.id] ||= 'pending';
  return progress;
}

function v3SubmissionFor(userId, requirementId, programId=v3ActiveProgramId) {
  const progress = v3EnsureProgramProgress(userId, programId);
  progress.submissions[requirementId] ||= {text:'',richText:'',completionDate:'',selections:[],attachmentIds:[],feedback:'',updatedAt:isoNow(),approval:null,orientation:'auto'};
  const submission = progress.submissions[requirementId];
  submission.richText ||= '';
  submission.selections = Array.isArray(submission.selections) ? submission.selections : [];
  submission.attachmentIds = Array.isArray(submission.attachmentIds) ? submission.attachmentIds : [];
  return submission;
}

function v3ConfigFor(userId, requirement, programId=v3ActiveProgramId) {
  const scopedKey = `${programId}:${userId}:${requirement.id}`;
  const legacyKey = `${userId}:${requirement.id}`;
  const user = userById(userId);
  const rules = (database.indicationRules || []).filter(rule => (rule.programId || 'class_grouped') === programId && rule.active !== false && rule.requirementId === requirement.id && (
    rule.scope === 'all' ||
    (rule.scope === 'club' && rule.scopeId === user?.clubId) ||
    (rule.scope === 'role' && rule.scopeId === user?.role) ||
    (rule.scope === 'user' && rule.scopeId === userId)
  )).sort((a,b) => ({all:1,role:2,club:3,user:4}[a.scope] - ({all:1,role:2,club:3,user:4}[b.scope])));
  return Object.assign({
    suggestedDate:'',
    mode:requirement.activity_mode || 'Individual',
    evidence:requirement.evidence_type_suggestion || 'Informe',
    photos:requirement.requires_photos_suggestion ? 'required' : 'optional',
    minWords:'',maxWords:'',
    instructions:requirement.tutor_instructions_default || requirement.observation || '',
    evaluation:requirement.evaluation_suggestion || ''
  }, ...rules.map(rule => rule.config || {}), database.configs[scopedKey] || (programId === 'class_grouped' ? database.configs[legacyKey] : {}) || {});
}

function v3CountStatus(userId, status, programId=v3ActiveProgramId) {
  const values = Object.values(v3EnsureProgramProgress(userId, programId).status || {});
  return values.filter(value => value === status).length;
}

function v3ProgressPercent(userId, programId=v3ActiveProgramId) {
  const total = v3ProgramRequirements(programId).length;
  return total ? Math.round(v3CountStatus(userId, 'approved', programId) * 100 / total) : 0;
}

function v3ProgramSelector(selected=v3ActiveProgramId, onchange='v3SelectProgram(this.value)') {
  const user = currentUser();
  const programs = user?.role === 'admin' ? database.modules.filter(item => item.active !== false && (!window.SGL562 || SGL562.allowed(item.id))).map(item => v3Program(item.id)) : v3ProgramsForUser(user);
  if (programs.length <= 1) return '';
  return `<label class="field-group program-selector">Módulo<select class="field" onchange="${onchange}">${programs.map(program => `<option value="${program.id}" ${program.id === selected ? 'selected' : ''}>${esc(program.menu_label || program.name)}</option>`).join('')}</select></label>`;
}

function v3SelectProgram(programId, rerender=true) {
  if (!v3ProgramDefinitions[programId]) return;
  if (!v3UserHasProgram(currentUser(), programId) && currentUser()?.role !== 'admin') return toast('Ese módulo no está asignado a tu cuenta.');
  v3ActiveProgramId = programId;
  if (rerender) render();
}

function v3ModuleBadge(programId) {
  const program = v3Program(programId);
  const logo = program.logo || appLogo();
  return `<span class="program-badge"><img src="${esc(logo)}" alt=""><span>${esc(program.name)}</span></span>`;
}

function v3SyncPendingCount() {
  return v3ServerProposals.filter(item => ['pending','postponed'].includes(item.status)).length || Number(database.syncRequestsCache?.filter?.(item => ['pending','postponed'].includes(item.status)).length || 0);
}

navItems = function navItemsV3(user) {
  if (user.role === 'admin') return [
    ['dashboard','▦','Inicio'], ['tutors','♙','Tutores'], ['aspirants','◎','Aspirantes'], ['modules_admin','◆','Módulos'], ['sync_requests','⇄','Solicitudes antiguas'],
    ['tasks','◷','Tareas'], ['reviews','✓','Revisiones'], ['indications','✎','Indicaciones'], ['materials','▣','Materiales'], ['classes','◇','Clases'],
    ['clubs','◇','Clubes'], ['drive','△','Google Drive'], ['profile','○','Mi perfil'], ['settings','⚙','Configuración'], ['users','☷','Usuarios']
  ];
  if (user.role === 'regional') return [
    ['dashboard','▦','Inicio'], ['tutors','♙','Tutores'], ['aspirants','◎','Aspirantes'], ['requirements','☷','Expediente'], ['reports','□','Informes'],
    ['profile','○','Mi perfil'], ['settings','⚙','Configuración']
  ];
  if (user.role === 'tutor') return [
    ['dashboard','▦','Resumen'], ['aspirants','♙','Mis Aspirantes'], ['tasks','◷','Tareas'], ['materials','▣','Materiales'], ['reviews','✓','Revisiones'],
    ['requirements','☷','Expediente'], ['drive','△','Google Drive'], ['profile','○','Mi perfil'], ['settings','⚙','Configuración']
  ];
  const moduleItems = v3ProgramsForUser(user).map(program => [`module_${program.id}`,'◆',program.menu_label || program.name]);
  return [
    ['dashboard','▦','Inicio'], ...moduleItems,
    ...(ClassPolicy.canAccessClasses(user,database.classes) ? [['classes','◇','Mis clases']] : []),
    ['drive','△','Google Drive'], ['profile','○','Mi perfil'], ['settings','⚙','Configuración']
  ];
};

renderNav = function renderNavV3() {
  const user = currentUser();
  const reviewCount = pendingReviews(user).length;
  const syncCount = user?.role === 'admin' ? v3SyncPendingCount() : 0;
  const root = document.getElementById('nav');
  if (!root || !user) return;
  root.innerHTML = navItems(user).map(([page,icon,label]) => {
    const count = page === 'reviews' ? reviewCount : page === 'sync_requests' ? syncCount : 0;
    return `<button data-page="${page}" class="${currentPage === page ? 'active' : ''}${page === 'users' ? ' nav-bottom' : ''}" onclick="go('${page}')"><b>${icon}</b><span>${esc(label)}</span>${count ? `<i class="count">${count}</i>` : ''}</button>`;
  }).join('');
};

go = function goV3(page) {
  const user = currentUser();
  if (!user) return renderLogin();
  if (String(page).startsWith('module_')) {
    const programId = String(page).slice(7);
    if (!v3UserHasProgram(user, programId) && user.role !== 'admin') return go('dashboard');
    currentPage = page;
    v3ActiveProgramId = programId;
    closeModal();
    renderNav();
    return renderProgramHub(programId);
  }
  if (page === 'modules_admin') {
    if (user.role !== 'admin') return go('dashboard');
    currentPage = page; closeModal(); renderNav(); return renderModulesAdmin();
  }
  if (page === 'sync_requests') {
    if (user.role !== 'admin') return go('dashboard');
    currentPage = page; closeModal(); renderNav(); return renderSyncRequests();
  }
  if (['requirements','reports','tasks','materials','bible','indications'].includes(page)) {
    const allowed = v3AssignedProgramIds(user);
    if (!allowed.includes(v3ActiveProgramId)) v3ActiveProgramId = allowed[0] || 'class_grouped';
    if (['aspirant','pastor_aspirant'].includes(user.role) && !v3UserHasProgram(user, v3ActiveProgramId)) return go('dashboard');
  }
  return V3_ORIGINAL.go(page);
};

renderShell = function renderShellV3() {
  const user = currentUser();
  if (user) {
    const allowed = v3AssignedProgramIds(user);
    if (!allowed.includes(v3ActiveProgramId)) v3ActiveProgramId = allowed[0] || 'class_grouped';
  }
  V3_ORIGINAL.renderShell();
  clearInterval(v3SyncPollTimer);
  clearInterval(v3PresencePollTimer);
  if (user && database.settings.serverUrl) {
    const pollReliableState = () => {
      const current = currentUser();
      if (!current || !database.settings.serverUrl) return;
      if (current.role === 'admin') {
        // El Administrador también descarga cambios automáticos de Aspirantes/Tutores.
        // Antes solo consultaba solicitudes antiguas y su bandeja de Revisiones quedaba obsoleta.
        Promise.allSettled([v3PullServerUpdates(false), v3FetchSyncRequests(false)]);
      } else {
        v3PollClientSync(false);
      }
    };
    setTimeout(pollReliableState, 350);
    v3SyncPollTimer = setInterval(pollReliableState, 4000);
  }
  if(['admin','tutor'].includes(user?.role)&&!REMOTE_WEB){
    v3PresencePrimed=false;
    setTimeout(()=>v3FetchPresence(false),700);
    v3PresencePollTimer=setInterval(()=>v3FetchPresence(true),10000);
  }
};

function renderProgramHub(programId=v3ActiveProgramId) {
  const user = currentUser();
  const aspirant = ['aspirant','pastor_aspirant'].includes(user.role) ? user : targetAspirant();
  const program = v3Program(programId);
  if (!program || (['aspirant','pastor_aspirant'].includes(user.role) && !v3UserHasProgram(user, programId))) return go('dashboard');
  setTop(program.menu_label || program.name, 'Módulo de formación');
  const progress = aspirant ? v3EnsureProgramProgress(aspirant.id, programId) : null;
  const total = v3ProgramRequirements(programId).length;
  const approved = aspirant ? v3CountStatus(aspirant.id,'approved',programId) : 0;
  const review = aspirant ? v3CountStatus(aspirant.id,'in_review',programId) : 0;
  const percent = aspirant ? v3ProgressPercent(aspirant.id,programId) : 0;
  const tiles = [
    ['requirements','☷','Mis requisitos','Revisa, desarrolla y envía cada requisito.']
  ];
  if (program.bible_mode) tiles.push(['bible','▤',programId === 'class_grouped' ? 'Lectura bíblica' : programId === 'music_ministry' ? 'Lectura bíblica' : 'Año Bíblico','Registra el avance bíblico correspondiente a este módulo.']);
  tiles.push(
    ['reports','□','Mis informes','Abre, imprime y exporta los informes guardados.'],
    ['tasks','◷','Mis tareas','Consulta fechas e indicaciones asignadas.'],
    ['materials','▣','Materiales','Accede a documentos, videos y recursos del módulo.']
  );
  if(programId==='music_ministry')tiles.unshift(['music_registration','♬','Registro de Ministerio','Registra el tipo, datos institucionales y director del Ministerio.']);
  const recentTasks = (database.tasks || []).filter(task => sgl506TaskIsRealForActor(task,userById(aspirant?.id)||currentUser(),programId) && task.assigneeId === aspirant?.id && taskState(task) !== 'presented').slice(0,4);
  setContent(`<section class="program-hero" style="--program-accent:${esc(program.accent || '#1F739E')}"><img src="${esc(program.logo || appLogo())}" alt=""><div><h1>${esc(program.name)}</h1><p>${esc(program.description || '')}</p></div>${aspirant ? `<div class="program-progress-ring"><strong>${percent}%</strong><span>${approved}/${total} revisados</span></div>` : ''}</section>
  ${!['aspirant','pastor_aspirant'].includes(user.role) ? `<div class="page-head compact"><div>${contextSelector()}</div>${v3ProgramSelector(programId)}</div>` : ''}
  <div class="module-tile-grid">${tiles.map(([page,icon,title,description]) => `<button class="module-tile" onclick="v3ActiveProgramId='${programId}';go('${page}')"><b>${icon}</b><span><strong>${title}</strong><small>${description}</small></span><i>›</i></button>`).join('')}</div>
  <div class="two" style="margin-top:16px"><div class="card"><div class="card-head"><div><h3>Resumen de avance</h3><p class="subtitle" style="margin:0">Expediente de ${esc(aspirant?.fullName || 'Aspirante')}</p></div><span class="status ${review ? 'in_review' : 'approved'}">${review} en revisión</span></div><div class="bar large"><i style="width:${percent}%"></i></div><div class="program-stat-row"><span><b>${approved}</b> revisados</span><span><b>${review}</b> en revisión</span><span><b>${Math.max(0,total-approved-review)}</b> restantes</span></div></div><div class="card"><div class="card-head"><h3>Próximas tareas</h3></div>${recentTasks.map(task => {const req=v3RequirementById(task.requirementId,programId);return `<button class="reading-item clickable" onclick="openRequirement('${task.requirementId}')"><div><h4>${esc(req?.official_text || task.requirementId)}</h4><p>Presentación: ${formatDate(task.dueDate)}</p></div><span class="status ${taskState(task)==='overdue'?'rejected':'assigned'}">${TASK_LABELS[taskState(task)]}</span></button>`;}).join('') || '<div class="empty">No hay tareas pendientes en este módulo.</div>'}</div></div>`);
}

function renderModulesAdmin() {
  setTop('Módulos de formación','Administración');
  const aspirants = database.users.filter(item => ['aspirant','pastor_aspirant'].includes(item.role) && (item.accountState || 'active') !== 'archived' && (!window.SGL562 || SGL562.inView(item)));
  const cards = Object.values(v3ProgramDefinitions).filter(program=>!window.SGL562||SGL562.allowed(program.id)).map(program => {
    const module = v3ModuleRecord(program.id);
    const active = module?.active !== false;
    const assigned = module?.assignedUserIds?.length || 0;
    return `<article class="card module-admin-card ${active ? '' : 'inactive'}" style="--program-accent:${esc(program.accent || '#1F739E')}"><div class="module-admin-head"><img src="${esc(program.logo || appLogo())}" alt=""><div><span class="status ${active ? 'approved' : 'rejected'}">${active ? 'Creado y disponible' : 'No creado'}</span><h3>${esc(program.menu_label || program.name)}</h3><p>${esc(program.description || '')}</p></div></div><div class="program-stat-row"><span><b>${v3ProgramRequirements(program.id).length}</b> requisitos</span><span><b>${assigned}</b> aspirantes</span><span><b>${program.bible_mode ? 'Sí' : 'No'}</b> año/lectura bíblica</span></div><div class="actions">${active ? `<button class="btn primary" onclick="openModuleAssignments('${program.id}')">Asignar aspirantes</button>${program.id !== 'class_grouped' ? `<button class="btn ghost" onclick="setModuleActive('${program.id}',false)">Desactivar</button>` : ''}<button class="btn ghost" onclick="v3ActiveProgramId='${program.id}';openAspirantModulePreview('${program.id}')">Vista del módulo</button>` : `<button class="btn primary" onclick="setModuleActive('${program.id}',true)">Crear módulo</button>`}</div></article>`;
  }).join('');
  setContent(`<div class="page-head"><div><div class="eyebrow">Control de acceso</div><h1 class="page-title">Módulos oficiales</h1><p class="subtitle">El Administrador crea o desactiva los módulos y decide a qué Aspirantes les aparecen en el menú.</p></div><span class="chip blue">${aspirants.length} Aspirante(s)</span></div><div class="grid3 module-admin-grid">${cards}</div><div class="notice" style="margin-top:16px"><b>Los datos no se eliminan al desactivar.</b> Los avances quedan guardados y vuelven a mostrarse al reactivar el módulo.</div>`);
}

async function setModuleActive(programId, active) {
  if (currentUser()?.role !== 'admin') return;
  const module = v3ModuleRecord(programId);
  if (!module) return;
  module.active = !!active;
  if(active&&programId==='music_ministry')sgl530SeedMusicReportModes();
  module.updatedAt = isoNow();
  if (!active) module.assignedUserIds = [];
  await persist(true,{action:active?'Módulo creado':'Módulo desactivado',entity:programId,detail:v3Program(programId).name});
  renderModulesAdmin();
  toast(active ? 'Módulo disponible para asignar.' : 'Módulo desactivado; sus datos se conservaron.');
}

function v4220ProgramProgressPercent(userId,programId){try{return v3ProgressPercent(userId,programId);}catch{return 0;}}
function v4220GuideMasterBlocked(aspirant){return false;}
function v4220TutorName(aspirant){return userById(sgl545TutorId(aspirant,v3ActiveProgramId||'class_grouped'))?.fullName||'Sin asignar';}
function openModuleAssignments(programId) {
  if (currentUser()?.role !== 'admin') return;
  const module = v3ModuleRecord(programId), program = v3Program(programId);
  const aspirants = database.users.filter(item => ['aspirant','pastor_aspirant'].includes(item.role) && (item.accountState || 'active') !== 'archived' && (!window.SGL562 || SGL562.inView(item)));
  const blockNote=programId==='guide_master'?'<div class="notice warn">Guía Mayor Máster no puede habilitarse si el Líder está completando Clase Agrupada y Guía Mayor al mismo tiempo.</div>':'';
  showModal(`<div class="modal small"><div class="modal-head"><div><h3>Asignar ${esc(program.menu_label || program.name)}</h3><p>Solo los Aspirantes marcados verán este módulo en su menú.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveModuleAssignments(event,'${programId}')"><div class="modal-body">${blockNote}<div class="assignment-list">${aspirants.map(aspirant => {const blocked=programId==='guide_master'&&v4220GuideMasterBlocked(aspirant)&&!module.assignedUserIds.includes(aspirant.id);return `<label class="choice assignment-person ${blocked?'disabled':''}"><input type="checkbox" name="module_user" value="${aspirant.id}" ${module.assignedUserIds.includes(aspirant.id) ? 'checked' : ''} ${blocked?'disabled':''}><span class="avatar small-avatar">${avatarMarkup(aspirant)}</span><span><b>${esc(aspirant.fullName)}</b><small>${esc(clubFor(aspirant)?.name || 'Sin Club')} · Tutor asignado: ${esc(v4220TutorName(aspirant))}${blocked?' · Guía Mayor Máster bloqueado':''}</small></span></label>`;}).join('') || '<div class="empty">No hay Aspirantes.</div>'}</div></div><div class="modal-foot"><button type="button" class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar asignaciones</button></div></form></div>`);
}

async function saveModuleAssignments(event, programId) {
  event.preventDefault();
  if (currentUser()?.role !== 'admin') return;
  const module = v3ModuleRecord(programId);
  const selected=[...document.querySelectorAll('[name=module_user]:checked')].map(input => input.value);
  if(programId==='guide_master'){
    const blocked=selected.filter(userId=>v4220GuideMasterBlocked(userById(userId))&&!module.assignedUserIds.includes(userId));
    if(blocked.length)return toast('Guía Mayor Máster no puede habilitarse para líderes que completan Clase Agrupada y Guía Mayor.');
  }
  module.assignedUserIds = selected;
  module.updatedAt = isoNow();
  for (const userId of module.assignedUserIds) v3EnsureProgramProgress(userId, programId);
  await persist(true,{action:'Asignaciones de módulo actualizadas',entity:programId,detail:`${module.assignedUserIds.length} Aspirante(s)`});
  closeModal(); renderModulesAdmin(); toast('Asignaciones guardadas.');
}

function openAspirantModulePreview(programId) {
  const first = database.users.find(item => ['aspirant','pastor_aspirant'].includes(item.role) && v3ModuleRecord(programId)?.assignedUserIds.includes(item.id));
  if (!first) return toast('Asigna primero al menos un Aspirante.');
  activeAspirantId = first.id;
  v3ActiveProgramId = programId;
  renderProgramHub(programId);
}

renderDashboard = function renderDashboardV3() {
  const user = currentUser();
  const now = new Date(), greeting = now.getHours() < 12 ? 'Buenos días' : now.getHours() < 19 ? 'Buenas tardes' : 'Buenas noches';
  setTop(['aspirant','pastor_aspirant'].includes(user.role) ? 'Inicio' : 'Panel de gestión', ROLE_LABELS[user.rawRole624||user.role]);
  if (['aspirant','pastor_aspirant'].includes(user.role)) {
    const programs = v3ProgramsForUser(user);
    const tasks = (database.tasks || []).filter(task => sgl506TaskIsRealForActor(task,user,v3ActiveProgramId) && taskState(task) !== 'presented');
    const notices = (database.syncNotifications || []).filter(item => !item.read).slice(0,3);
    setContent(`${typeof sgl5066WelcomeHeroMarkup==='function'?sgl5066WelcomeHeroMarkup(greeting,user.fullName.split(/\s+/)[0],'',now):''}
      ${notices.map(item => `<div class="notice ${['accepted','approved','sync'].includes(item.type) ? '' : 'warn'}"><b>${esc(item.title)}</b><br>${esc(item.message)} <button class="btn link small" onclick="markSyncNotificationRead('${item.id}')">Marcar como leído</button></div>`).join('')}
      <div class="page-head sgl5094-assigned-head"><div><div class="eyebrow">Mis accesos</div><h1 class="page-title">Módulos asignados</h1></div><span class="chip blue">${tasks.length} tarea(s) pendiente(s)</span></div>
      <div class="grid3 program-dashboard-grid">${programs.map(program => {const pct=v3ProgressPercent(user.id,program.id),total=v3ProgramRequirements(program.id).length,approved=v3CountStatus(user.id,'approved',program.id);return `<button class="card program-dashboard-card" style="--program-accent:${esc(program.accent || '#1F739E')}" onclick="go('module_${program.id}')"><div class="program-card-logo"><img src="${esc(program.logo || appLogo())}" alt=""></div><div><span class="eyebrow">${esc(program.menu_label || program.name)}</span><h3>${esc(program.name)}</h3><p>${esc(program.description || '')}</p></div><div class="bar"><i style="width:${pct}%"></i></div><div class="program-stat-row"><span><b>${pct}%</b> avance</span><span><b>${approved}/${total}</b> revisados</span></div></button>`;}).join('') || '<div class="card empty">El Administrador todavía no te asignó módulos.</div>'}</div>`);
    return;
  }
  const aspirants = accessibleAspirants(user);
  const reviews = pendingReviews(user);
  const programs = user.role === 'admin' ? database.modules.filter(item => item.active !== false && (!window.SGL562 || SGL562.allowed(item.id))).map(item => v3Program(item.id)) : v3ProgramsForUser(user);
  const syncAlert = ''; // Solicitudes antiguas retirado de la interfaz visible.
  setContent(`${typeof sgl5066WelcomeHeroMarkup==='function'?sgl5066WelcomeHeroMarkup(greeting,user.fullName.split(/\s+/)[0],user.role === 'admin' ? 'Administra módulos, accesos y configuración del sistema.' : 'Revisa el avance de tus Aspirantes asignados.',now):''}${syncAlert}
  <div class="grid4"><div class="card kpi"><span class="icon">◎</span><small>Aspirantes</small><strong>${aspirants.length}</strong><small>con acceso activo</small></div><button class="card kpi kpi-link" onclick="go('reviews')"><span class="icon">✓</span><small>En revisión</small><strong>${reviews.length}</strong><small>entregas pendientes</small></button><div class="card kpi"><span class="icon">◆</span><small>Módulos</small><strong>${programs.length}</strong><small>disponibles</small></div><button class="card kpi kpi-link" onclick="go('tasks')"><span class="icon">◷</span><small>Tareas</small><strong>${(database.tasks||[]).filter(task=>sgl506TaskIsRealForActor(task,user)&&accessibleAspirants(user).some(a=>a.id===task.assigneeId)&&taskState(task)!=='presented').length}</strong><small>por presentar</small></button></div>
  <div class="grid3 program-dashboard-grid" style="margin-top:16px">${programs.map(program => `<button class="card program-dashboard-card compact" style="--program-accent:${esc(program.accent || '#1F739E')}" onclick="v3ActiveProgramId='${program.id}';${user.role === 'admin' ? "go('modules_admin')" : "go('requirements')"}"><div class="program-card-logo"><img src="${esc(program.logo || appLogo())}" alt=""></div><div><h3>${esc(program.name)}</h3><p>${v3ProgramRequirements(program.id).length} requisitos · ${v3ModuleRecord(program.id)?.assignedUserIds.length || 0} Aspirantes</p></div></button>`).join('')}</div>`);
};

async function markSyncNotificationRead(id) {
  const item = database.syncNotifications.find(entry => entry.id === id);
  if (item) item.read = true;
  await persist(false);
  renderDashboard();
}

openUser = function openUserV3(id='') {
  V3_ORIGINAL.openUser(id);
  const actor = currentUser(), editor = id ? userById(id) : null;
  if (actor?.role === 'regional') { const title=document.querySelector('.modal-head h3'); if(title)title.textContent='Crear Tutor Regional'; return; }
  if (actor?.role !== 'admin') return;
  const fieldRow = document.querySelector('.user-editor .field-row');
  if (!fieldRow) return;
  const activeModules = database.modules.filter(module => module.active !== false);
  const wrapper = document.createElement('div');
  wrapper.id = 'user_module_assignments';
  wrapper.className = 'field-group full user-module-assignment';
  wrapper.innerHTML = `<span>Módulos visibles para el Aspirante</span><div class="module-checkbox-grid">${activeModules.map(module => {
    const program = v3Program(module.id), checked = editor ? module.assignedUserIds.includes(editor.id) : module.id === 'class_grouped';
    return `<label class="choice"><input type="checkbox" name="user_module" value="${module.id}" ${checked ? 'checked' : ''}><span><b>${esc(program.menu_label || program.name)}</b><small>${v3ProgramRequirements(module.id).length} requisitos</small></span></label>`;
  }).join('')}</div><small>El usuario solo verá en su menú los módulos seleccionados. El Administrador puede cambiarlos después.</small>`;
  const passwordField = [...fieldRow.querySelectorAll('.field-group')].find(item => item.textContent.includes('contraseña') || item.textContent.includes('Contraseña'));
  if (passwordField) fieldRow.insertBefore(wrapper,passwordField); else fieldRow.appendChild(wrapper);
  toggleUserAssignments();
};

