saveUser = async function saveUserV3(event,id='') {
  event.preventDefault();
  const actor=currentUser(),tutorCreating=actor?.role==='tutor'&&!id,regionalCreatingTutor=actor?.role==='regional'&&!id;
  if (actor?.role !== 'admin'&&!tutorCreating&&!regionalCreatingTutor) return;
  const email=normalize(value('user_email')),username=normalize(value('user_username'));
  const duplicate=database.users.find(entry=>entry.id!==id&&(normalize(entry.email)===email||normalize(entry.username)===username));
  if(duplicate)return setText('user_error','El correo o usuario ya pertenece a otra cuenta.');
  const selectedPrograms=[...document.querySelectorAll('[name=user_module]:checked')].map(x=>x.value);
  if(tutorCreating&&(!selectedPrograms.length||selectedPrograms.some(p=>!sgl548TutorPrograms(actor).includes(p))))return setText('user_error','Selecciona al menos un módulo habilitado para tu tutoría.');
  const password=value('user_password'),item=id?userById(id):{id:newId('usr'),createdAt:isoNow(),photo:'',drive:null};
  item.theme ||= 'classic_blue';
  item.fullName=value('user_name').trim();item.email=email;item.username=username;item.birthDate=value('user_birth');item.phone=value('user_phone').trim();
  item.role=regionalCreatingTutor?'tutor':(tutorCreating?'aspirant':value('user_role'));
  if(regionalCreatingTutor){item.regionalCreatedBy=actor.id;item.regionalProgramIds=[...REGIONAL_PROGRAM_IDS];}item.clubId=value('user_club')||null;item.accountState=value('user_state')||'active';item.active=item.accountState==='active';
  if(actor.role==='admin'&&document.getElementById('sgl547_permissions'))item.requirementViewPrograms=[...document.querySelectorAll('[name=sgl547_view_program]:checked')].map(input=>input.value);
  item.tutorId=(['aspirant','pastor_aspirant'].includes(item.role)||selectedPrograms.length)?(tutorCreating?actor.id:value('user_tutor')||null):null;
  if(item.role==='tutor'&&document.getElementById('sgl548_tutor_programs'))item.tutorProgramIds=[...document.querySelectorAll('[name=sgl548_tutor_program]:checked')].map(x=>x.value);
  if(tutorCreating)item.tutorByProgram=Object.fromEntries(selectedPrograms.map(p=>[p,actor.id]));
  if(actor.role==='admin'&&document.getElementById('sgl545_tutors')){item.tutorByProgram={};if(['aspirant','pastor_aspirant'].includes(item.role)||document.querySelector('[name=user_module]:checked'))for(const field of document.querySelectorAll('[data-sgl545-program]'))item.tutorByProgram[field.dataset.sgl545Program]=field.value||null;item.tutorId=null;}if(actor.role==='admin'&&document.getElementById('sgl555_management_programs'))item.managementProgramIds=[...document.querySelectorAll('[name=sgl555_management_program]:checked')].map(x=>x.value);if(actor.role==='admin'&&document.getElementById('sgl555_regional_leaders'))item.regionalAssignedUserIds=[...document.querySelectorAll('[name=sgl555_regional_leader]:checked')].map(x=>x.value);item.reportFont ||= database.settings.reportFont||'Arial';
  item.church=value('user_church').trim();item.clubPosition=value('user_club_position').trim();item.churchPosition=value('user_church_position').trim();item.missionaryDistrict=value('user_district').trim();item.region=value('user_region').trim();item.mission=value('user_mission').trim();item.union=value('user_union').trim();
  const photo=document.getElementById('user_photo')?.files?.[0];if(photo)item.photo=await makeSquareProfilePhoto(photo);if(password)item.password=await passwordRecord(password);if(!id)database.users.push(item);
  if(actor.role==='admin'){
    const chosenModules=database.modules.filter(module=>!!document.querySelector(`[name=user_module][value="${module.id}"]`)?.checked).map(module=>module.id);

    for (const module of database.modules) {
      module.assignedUserIds = module.assignedUserIds.filter(userId => userId !== item.id);
      const chosen = chosenModules.includes(module.id);
      if (chosen && module.active !== false) {
        module.assignedUserIds.push(item.id);
        v3EnsureProgramProgress(item.id,module.id);
      }
    }
  } else if(tutorCreating) {
    for(const programId of selectedPrograms){const module=v3ModuleRecord(programId);if(module&&!module.assignedUserIds.includes(item.id)){module.assignedUserIds.push(item.id);v3EnsureProgramProgress(item.id,programId);}}
  }
  rememberAutocompleteName(item.fullName);
  await persist(true,{action:id?'Usuario actualizado':'Usuario creado',entity:item.id,detail:`${item.fullName} · ${ROLE_LABELS[item.role]}`});
  closeModal();
  if(['admin','regional'].includes(actor.role))currentPage==='tutors'?renderTutors():renderUsers();else renderAspirants();
  toast('Usuario y accesos guardados.');
};

importUsers = async function importUsersV3(file) {
  const before = new Set(database.users.map(item => item.id));
  await V3_ORIGINAL.importUsers(file);
  const classModule = v3ModuleRecord('class_grouped');
  let changed = false;
  for (const item of database.users) if (!before.has(item.id) && ['aspirant','pastor_aspirant'].includes(item.role) && !classModule.assignedUserIds.includes(item.id)) {
    classModule.assignedUserIds.push(item.id);v3EnsureProgramProgress(item.id,'class_grouped');changed=true;
  }
  if(changed){await persist(true,{action:'Módulo inicial asignado',entity:'class_grouped',detail:'Aspirantes importados'});renderUsers();}
};

