async function saveMaterial(event,id='') {
  event.preventDefault();const user=currentUser();if(!['admin','tutor'].includes(user?.role))return;
  const item=(database.materials||[]).find(material=>material.id===id)||{id:newId('mat'),createdAt:isoNow(),createdBy:user.id,active:true,fileId:null};if(id&&user.role!=='admin'&&item.createdBy!==user.id)return;
  const file=document.getElementById('material_file')?.files?.[0],url=value('material_url').trim();if(url&&!/^https?:\/\//i.test(url))return setText('material_error','El enlace debe comenzar con http:// o https://.');if(!file&&!url&&!item.fileId&&!item.dataUrl)return setText('material_error','Carga un archivo o escribe un enlace.');
  if(file){if(file.size>30*1024*1024)return setText('material_error','El archivo supera 30 MB. Usa un enlace para materiales más grandes.');const fileId=item.fileId||newId('file'),dataUrl=await fileToDataUrl(file);await filePut({id:fileId,ownerId:user.id,programId:value('material_program')||v3ActiveProgramId,kind:'support_material',name:file.name,type:file.type||'application/octet-stream',size:file.size,dataUrl,createdAt:isoNow()});item.fileId=fileId;item.fileName=file.name;item.fileType=file.type||'application/octet-stream';delete item.dataUrl;item.url='';}else if(url){item.url=url;delete item.dataUrl;}
  item.programId=value('material_program')||v3ActiveProgramId;item.title=value('material_title').trim();item.category=value('material_category');item.requirementId=value('material_requirement')||null;item.description=value('material_description').trim();item.updatedAt=isoNow();item.publisherRole=user.role;if(user.role==='admin'){item.visibleToUsers=true;delete item.audienceTutorId;}else if(user.role==='tutor'){item.audienceTutorId=user.id;item.visibleToUsers=false;}if(id)item.active=document.getElementById('material_active')?.checked!==false;else database.materials.push(item);
  await persist(true,{action:id?'Material actualizado':'Material publicado',entity:item.id,detail:`${v3Program(item.programId).name} · ${item.title}`});v3ActiveProgramId=item.programId;closeModal();renderMaterials();toast('Material guardado.');
}

