function openIndicationRule(id='') {
  const rule=database.indicationRules.find(item=>item.id===id),programId=rule?.programId||v3ActiveProgramId,scope=rule?.scope||'all';v3ActiveProgramId=programId;
  showModal(`<div class="modal small"><div class="modal-head"><div><h3>Indicación general</h3><p>Las reglas más específicas tienen prioridad.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveIndicationRule(event,'${id}')"><div class="modal-body"><label class="field-group">Módulo<select id="rule_program" class="field" onchange="v3RefreshRuleRequirements('${esc(rule?.requirementId||'')}')">${database.modules.filter(item=>item.active!==false).map(module=>`<option value="${module.id}" ${module.id===programId?'selected':''}>${esc(v3Program(module.id).menu_label||v3Program(module.id).name)}</option>`).join('')}</select></label><label class="field-group">Requisito<select id="rule_req" class="field"></select></label><label class="field-group">Alcance<select id="rule_scope" class="field" onchange="renderRuleTargets()"><option value="all" ${scope==='all'?'selected':''}>Todos</option><option value="club" ${scope==='club'?'selected':''}>Por Club</option><option value="role" ${scope==='role'?'selected':''}>Por rol</option><option value="user" ${scope==='user'?'selected':''}>Por persona</option></select></label><label id="rule_target_wrap" class="field-group hidden">Destino<select id="rule_target" class="field"></select></label><label class="field-group">Modalidad<input id="rule_mode" class="field" value="${esc(rule?.config?.mode||'')}"></label><label class="field-group">Indicaciones<textarea id="rule_instructions" class="field">${esc(rule?.config?.instructions||'')}</textarea></label><label class="field-group">Evaluación<textarea id="rule_evaluation" class="field">${esc(rule?.config?.evaluation||'')}</textarea></label></div><div class="modal-foot"><button type="button" class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar</button></div></form></div>`);v3RefreshRuleRequirements(rule?.requirementId||'');renderRuleTargets(rule?.scopeId||'');
}

function v3RefreshRuleRequirements(selected='') {const programId=value('rule_program')||v3ActiveProgramId,root=document.getElementById('rule_req');if(root)root.innerHTML=v3ProgramRequirements(programId).map(req=>`<option value="${req.id}" ${req.id===selected?'selected':''}>${esc(req.id)} · ${esc(short(req.official_text,70))}</option>`).join('');}

async function saveIndicationRule(event,id='') {event.preventDefault();const rule=database.indicationRules.find(item=>item.id===id)||{id:newId('rule'),createdAt:isoNow(),createdBy:currentUser()?.id||null,active:true};rule.createdBy ||= currentUser()?.id||null;rule.programId=value('rule_program')||v3ActiveProgramId;rule.requirementId=value('rule_req');rule.scope=value('rule_scope');rule.scopeId=rule.scope==='all'?'':value('rule_target');rule.config={mode:value('rule_mode'),instructions:value('rule_instructions'),evaluation:value('rule_evaluation')};if(!id)database.indicationRules.push(rule);await persist(true,{action:'Indicaciones actualizadas',entity:rule.requirementId,detail:`${v3Program(rule.programId).name} · ${ruleScopeLabel(rule)}`});v3ActiveProgramId=rule.programId;closeModal();renderIndications();toast('Indicaciones guardadas.');}

function v3CertificateOnly(requirement,config) {
  // SGL 5.0.77: certificate_only se conserva como metadato del catálogo, pero
  // nunca convierte el certificado/constancia en un adjunto obligatorio.
  // Todos los requisitos pueden seguir el flujo normal de informe.
  return false;
}

function v3RequirementMaterials(requirementId,programId=v3ActiveProgramId,user=currentUser()) {
  return v3AccessibleMaterials(user).filter(item=>item.active!==false&&(item.programId||'class_grouped')===programId&&item.requirementId===requirementId);
}

function v3SelectionLabel(requirement){
  const selection=requirement?.selection;if(!selection)return '';
  const options=selection.options||requirement?.subitems||[];
  if(selection.type==='all')return `Todos los ${options.length} incisos`;
  const min=Number(selection.min||1),max=Number(selection.max||min);
  return `Elegir ${min}${max!==min?`–${max}`:''}`;
}
function v3SelectionNotice(requirement){
  const selection=requirement?.selection;if(!selection)return '';
  const options=selection.options||requirement?.subitems||[];
  if(selection.type==='all')return `<div class="notice"><b>Incisos obligatorios:</b> este requisito comprende los ${options.length} incisos indicados. Todos deben quedar incluidos.</div>`;
  const min=Number(selection.min||1),max=Number(selection.max||min);
  return `<div class="notice"><b>Selección requerida:</b> elige ${min}${max!==min?` a ${max}`:''} opción(es).</div>`;
}

function v3EffectiveSelections(requirement,submission){
  const selection=requirement?.selection,options=selection?.options||requirement?.subitems||[];
  if(selection?.type==='all')return [...options];
  return [...(submission?.selections||[])];
}

renderRequirements = function renderRequirementsV3() {
  const aspirant=targetAspirant(),program=v3Program(v3ActiveProgramId),requirements=v3ProgramRequirements(v3ActiveProgramId);
  setTop('Requisitos',program.menu_label||program.name);
  if(!aspirant)return setContent('<div class="card empty">Selecciona o asigna un Aspirante.</div>');
  if(['aspirant','pastor_aspirant'].includes(currentUser().role)&&!v3UserHasProgram(aspirant,v3ActiveProgramId))return go('dashboard');
  const tutorLine=['class_grouped','guide_major'].includes(v3ActiveProgramId)?`<p class="subtitle">Tutor asignado: <b>${esc(v4220TutorName(aspirant))}</b>. Cada guardado se conserva en este equipo y se sincroniza automáticamente; Enviar a revisión lo coloca en Revisiones.</p>`:'<p class="subtitle">Cada guardado se conserva en este equipo y se sincroniza automáticamente; Enviar a revisión lo coloca en Revisiones.</p>';
  setContent(`<div class="page-head"><div><div class="eyebrow">${esc(program.menu_label||program.name)} · ${esc(aspirant.fullName)}</div><h1 class="page-title">${requirements.length} requisitos</h1>${tutorLine}</div><div class="actions">${!['aspirant','pastor_aspirant'].includes(currentUser().role)?contextSelector():''}${v3ProgramSelector(v3ActiveProgramId)}${['aspirant','pastor_aspirant'].includes(currentUser().role)?``:''}</div></div><div class="toolbar"><input id="req_search" class="field" placeholder="Buscar requisito…" oninput="filterRequirements()"><select id="req_area" class="field" onchange="filterRequirements()"><option value="">Todas las secciones</option>${v3ProgramAreas(v3ActiveProgramId).map(area=>`<option value="${esc(area.code)}">${esc(area.title)}</option>`).join('')}</select><select id="req_status" class="field" onchange="requirementStatusFilter=this.value;filterRequirements()"><option value="">Todos los estados</option>${Object.entries(STATUS_LABELS).filter(([key])=>key!=='rejected').map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div><div id="requirements_list" class="list"></div>`);
  const statusRoot=document.getElementById('req_status');if(requirementStatusFilter&&statusRoot)statusRoot.value=requirementStatusFilter==='developing'?'':requirementStatusFilter;filterRequirements();
};

filterRequirements = function filterRequirementsV3() {
  const aspirant=targetAspirant(),root=document.getElementById('requirements_list');if(!aspirant||!root)return;
  const search=normalize(value('req_search')),area=value('req_area'),status=value('req_status'),progress=v3EnsureProgramProgress(aspirant.id,v3ActiveProgramId),filter=status||requirementStatusFilter;
  const statusMatches=value=>!(sgl546HideApproved()&&value==='approved')&&(filter==='developing'?['assigned','in_progress','needs_changes'].includes(value):!filter||value===filter);
  const items=v3ProgramRequirements(v3ActiveProgramId).filter(req=>(!area||req.areaCode===area)&&statusMatches(progress.status[req.id])&&(!search||normalize(`${req.id} ${req.official_text} ${req.areaTitle} ${req.observation||''}`).includes(search)));
  root.innerHTML=items.map(req=>{
    const materials=v3RequirementMaterials(req.id,v3ActiveProgramId),config=v3ConfigFor(aspirant.id,req,v3ActiveProgramId),reqStatus=progress.status[req.id],canSend=v3CanFillRequirement(currentUser(),aspirant,v3ActiveProgramId,reqStatus);
    return `<div class="list-item clickable" onclick="openRequirement('${req.id}')">${requirementAreaBadge(req)}<div><h4>${esc(req.official_text)}</h4><div class="chips"><span class="chip">${esc(req.areaTitle)}</span><span class="chip blue">${esc(req.id)}</span>${req.kind==='bible_reading'||req.id===v3Program(v3ActiveProgramId).bible_requirement_id?'<span class="chip gold">Lectura / Año bíblico</span>':''}<span class="chip blue">${esc(config.mode||'Individual')}</span>${materials.length?`<span class="chip green">${materials.length} material${materials.length===1?'':'es'}</span>`:''}${sgl425ExternalDraftBadge(progress.submissions?.[req.id],reqStatus)}${req.selection?`<span class="chip gold">${esc(v3SelectionLabel(req))}</span>`:''}</div></div><div class="req-actions"><span class="status ${reqStatus}">${STATUS_LABELS[reqStatus]}</span>${materials.length?`<button class="btn ghost small" onclick="event.stopPropagation();openRequirementMaterials('${req.id}')">Ver material</button>`:''}${canSend?`<button class="btn primary small sgl5049-send-review" onclick="event.stopPropagation();sgl5049SendRequirementFromList('${req.id}')">Enviar a revisión</button>`:''}</div></div>`;
  }).join('')||'<div class="card empty">No hay resultados.</div>';
};

const sgl5049SubmitBusy=new Set();
async function sgl5049SendRequirementFromList(requirementId){
  const user=currentUser(),aspirant=targetAspirant(),programId=v3ActiveProgramId,reqId=String(requirementId||'');
  if(!user||!aspirant||!reqId)return;
  const progress=v3EnsureProgramProgress(aspirant.id,programId),status=progress.status[reqId]||'pending';
  if(!v3CanFillRequirement(user,aspirant,programId,status))return toast('Este requisito ya no está disponible para enviar.');
  if(sgl5049SubmitBusy.has(reqId))return toast('El envío ya se está preparando.');
  const requirement=v3RequirementById(reqId,programId),config=v3ConfigFor(aspirant.id,requirement,programId),submission=v3SubmissionFor(aspirant.id,reqId,programId);
  const selections=v3EffectiveSelections(requirement,submission),minimum=Number(requirement.selection?.min||0),maximum=Number(requirement.selection?.max||0);
  if(minimum&&selections.length<minimum)return toast(`Selecciona al menos ${minimum} opción(es) y pulsa Guardar avance antes de enviar.`);
  if(maximum&&selections.length>maximum)return toast(`Selecciona como máximo ${maximum} opción(es) y pulsa Guardar avance antes de enviar.`);
  const probe=document.createElement('div');probe.innerHTML=String(submission.richText||'');const savedText=String(submission.text||probe.textContent||'').replace(/\s+/g,' ').trim();
  if(!savedText)return toast('Primero abre el requisito, completa el informe y pulsa Guardar avance.');
  if(!submission.completionDate)return toast('Primero completa la fecha y pulsa Guardar avance.');
  if(typeof v4QueuedForRequirement==='function'&&v4QueuedForRequirement(reqId,programId,'review'))return toast('Este requisito ya tiene un envío a revisión registrado.');
  const previousSubmissionUpdatedAt=submission.updatedAt,previousDraftOnly=submission.draftOnly,previousProgressUpdatedAt=progress.updatedAt,changedTasks=[];
  sgl5049SubmitBusy.add(reqId);
  try{
    // persist() usa este contexto para construir la operación de sincronización.
    modalOwnerId=aspirant.id;modalRequirementId=reqId;v3ModalProgramId=programId;
    submission.updatedAt=isoNow();submission.draftOnly=false;progress.status[reqId]='in_review';progress.updatedAt=isoNow();
    for(const task of (database.tasks||[]).filter(item=>item.assigneeId===aspirant.id&&(item.programId||'class_grouped')===programId&&item.requirementId===reqId&&!item.presentedAt)){changedTasks.push([task,task.presentedAt,task.updatedAt]);task.presentedAt=isoNow();task.updatedAt=isoNow();}
    await persist(true,{action:'Requisito enviado',entity:reqId,detail:`${v3Program(programId).name} · ${aspirant.fullName||''}`});
    filterRequirements();toast(sgl538ReviewMessage());
    if(database.settings?.serverUrl&&typeof v3CanAttemptNetwork==='function'&&v3CanAttemptNetwork())syncNow().catch(()=>{});
  }catch(error){
    console.error('SGL 5.0.52 envío desde Requisitos',error);
    progress.status[reqId]=status;progress.updatedAt=previousProgressUpdatedAt;submission.updatedAt=previousSubmissionUpdatedAt;submission.draftOnly=previousDraftOnly;
    for(const [task,presentedAt,updatedAt] of changedTasks){task.presentedAt=presentedAt;task.updatedAt=updatedAt;}
    toast(`No se pudo enviar a revisión: ${error?.message||'error'}`);
  }finally{sgl5049SubmitBusy.delete(reqId);}
}
window.sgl5049SendRequirementFromList=sgl5049SendRequirementFromList;


const v3LogoCache = new Map();
async function v3LoadProgramLogo(programId=v3ActiveProgramId) {
  if(programId==='class_grouped')return loadMandatoryLogo();
  if(v3LogoCache.has(programId))return v3LogoCache.get(programId);
  const source=v3Program(programId).logo||appLogo();
  if(/^data:image\//.test(source)){v3LogoCache.set(programId,source);return source;}
  try{const response=await fetch(source);if(!response.ok)throw new Error(String(response.status));const data=await fileToDataUrl(await response.blob());v3LogoCache.set(programId,data);return data;}catch{v3LogoCache.set(programId,appLogo());return appLogo();}
}

function v3CanFillRequirement(user,aspirant,programId,status='pending') {
  return !!user && !!aspirant && ['aspirant','pastor_aspirant'].includes(user.role) && user.id===aspirant.id && v3UserHasProgram(user,programId) && !['in_review','approved'].includes(status);
}
function v3CanReviewRequirement(user,aspirant,status='pending') {
  if(!user||!aspirant||status!=='in_review')return false;
  if(user.role==='admin')return true;
  return user.role==='tutor' && sgl545HasTutor(aspirant,user.id,v3ActiveProgramId);
}
function v3CanEditCurrentRequirementDraft(){
  const user=currentUser(),aspirant=userById(modalOwnerId),progress=v3EnsureProgramProgress(modalOwnerId,v3ModalProgramId),status=progress.status[modalRequirementId]||'pending';
  return v3CanFillRequirement(user,aspirant,v3ModalProgramId,status);
}

async function openRequirement(requirementId) {
  const programId=v3FindProgramForRequirement(requirementId)||v3ActiveProgramId;v3ActiveProgramId=programId;v3ModalProgramId=programId;
  const aspirant=targetAspirant(),requirement=v3RequirementById(requirementId,programId);if(!aspirant||!requirement)return;
  if(programId==='class_grouped'&&requirement.kind==='bible_reading')return openBibleRequirement(requirementId);
  modalOwnerId=aspirant.id;modalRequirementId=requirementId;
  const submission=v3SubmissionFor(aspirant.id,requirementId,programId),config=v3ConfigFor(aspirant.id,requirement,programId),progress=v3EnsureProgramProgress(aspirant.id,programId),status=progress.status[requirementId],displayedDate=submission.completionDate||localDate();
  const readonly=!v3CanFillRequirement(currentUser(),aspirant,programId,status),certificateOnly=v3CertificateOnly(requirement,config),options=requirement.selection?.options||requirement.subitems||[],club=clubFor(aspirant),support=v3RequirementMaterials(requirementId,programId),editorHtml=reportHtmlFromSubmission(submission),officialLogo=await v3LoadProgramLogo(programId),program=v3Program(programId);
  const allRequired=requirement.selection?.type==='all';
  const optionHtml=options.length?`<div class="selection-options">${v3SelectionNotice(requirement)}${options.map(option=>`<label class="choice option-detail"><input type="checkbox" name="req_choice" value="${esc(option)}" ${(allRequired||submission.selections.includes(option))?'checked':''} ${(readonly||allRequired)?'disabled':''}><span><b>${esc(option)}</b>${requirement.option_details?.[option]?`<small>${esc(requirement.option_details[option])}</small>`:''}</span></label>`).join('')}</div>`:'';
  showModal(`<div class="modal"><div class="modal-head"><div><h3>${esc(requirement.areaTitle)}</h3><p>${esc(requirement.id)} · ${STATUS_LABELS[status]} · ${esc(program.name)}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="modal-grid"><section><div class="document-header"><img src="${officialLogo}" alt="Logo oficial"><div class="doc-center">${typeof reportMissionName==='function'&&reportMissionName({aspirant})?`<div class="sgl5053-report-mission">${esc(reportMissionName({aspirant}))}</div>`:''}<strong>${esc(program.report_title||'INFORME')}</strong><div>${esc(aspirant.fullName)}${club?.logo?'':` · ${esc(club?.name||(programId==='music_ministry'?'Sistema de Gestión de Música':'Ministerio de Conquistadores'))}`}</div></div>${club?.logo?`<img src="${club.logo}" alt="Logo del Club">`:'<span></span>'}</div><div class="requirement-official-block"><span>${esc(requirement.id)}</span><h4>${esc(requirement.official_text)}</h4>${requirement.observation?`<p><b>Observación oficial:</b> ${esc(requirement.observation)}</p>`:''}</div>${optionHtml}<label class="field-group requirement-general requirement-fill-date-field">Fecha de realización del requisito<input id="req_date" class="field" type="date" value="${esc(displayedDate)}" ${readonly?'disabled':''}></label>${certificateOnly?'<div class="notice">Este requisito puede incluir certificado o constancia como evidencia opcional. Puedes completar y presentar el requisito mediante el informe normal; si tienes una foto o imagen de la constancia, puedes adjuntarla.</div>':`<div class="section-label">Informe</div>${readonly?'':`<div class="rich-toolbar"><button type="button" class="btn ghost small" title="Negrita" onclick="formatReportText('bold')"><b>N</b></button><button type="button" class="btn ghost small" title="Subrayado" onclick="formatReportText('underline')"><u>S</u></button><button type="button" class="btn ghost small" title="Cursiva" onclick="formatReportText('italic')"><i>C</i></button><button type="button" class="btn ghost small" onclick="formatReportText('removeFormat')">Limpiar formato</button><span class="rich-toolbar-sep"></span><button type="button" class="btn ghost small" onclick="formatReportAlignment('left')">≡←</button><button type="button" class="btn ghost small" onclick="formatReportAlignment('center')">≡↔</button><button type="button" class="btn ghost small" onclick="formatReportAlignment('right')">→≡</button><button type="button" class="btn ghost small" onclick="formatReportAlignment('justify')">☰</button><span class="spell-hint">Ortografía en español activada</span></div>`}<div id="req_text" class="sgl5038-writing-page report-area rich-editor ${readonly?'readonly':''}" lang="es" spellcheck="true" contenteditable="${readonly?'false':'true'}" data-placeholder="Escribe aquí el desarrollo del requisito…">${editorHtml}</div>`}${certificateOnly?`<div id="req_text" class="sgl5038-writing-page report-area rich-editor ${readonly?'readonly':''} certificate-note" lang="es" spellcheck="true" contenteditable="${readonly?'false':'true'}" data-placeholder="Nota opcional sobre el certificado…">${editorHtml}</div>`:''}<div id="req_files" class="file-grid report-files"></div>${readonly?'':`<label class="upload-zone" style="display:block;margin-top:12px"><strong>${certificateOnly?'Agregar foto del certificado o constancia':'Agregar foto o imagen'}</strong><span>Se conserva alta resolución; el informe autoajusta las imágenes sin mostrar sus nombres.</span><input type="file" multiple hidden accept="image/*" onchange="attachFiles(this.files)"></label>`}</section><aside>${support.length?`<button class="btn green block" onclick="openRequirementMaterials('${requirementId}')">Ver material de apoyo (${support.length})</button>`:''}<div class="guide-card" style="margin-top:${support.length?'10':'0'}px"><strong>Indicaciones</strong><p>${esc(config.instructions||requirement.observation||'Desarrolla el requisito con claridad.')}</p></div><div class="guide-card"><strong>Modalidad</strong><p>${esc(config.mode||'Individual')}</p></div><div class="guide-card"><strong>Evaluación</strong><p>${esc(config.evaluation||'Revisión del informe y las evidencias solicitadas.')}</p></div><label class="field-group">Orientación del documento<select id="req_orientation" class="field" ${readonly?'disabled':''}><option value="auto" ${submission.orientation!=='portrait'&&submission.orientation!=='landscape'?'selected':''}>Automático</option><option value="portrait" ${submission.orientation==='portrait'?'selected':''}>Vertical</option><option value="landscape" ${submission.orientation==='landscape'?'selected':''}>Horizontal</option></select></label><label class="field-group">Letra del informe<select id="req_font" class="field" ${readonly?'disabled':''}><option ${aspirant.reportFont!=='Times New Roman'?'selected':''}>Arial</option><option ${aspirant.reportFont==='Times New Roman'?'selected':''}>Times New Roman</option></select></label><button class="btn ghost block" onclick="previewRequirementPdf('${requirementId}')">Visualizar PDF</button><button class="btn primary block" style="margin-top:8px" onclick="exportPdf('${requirementId}')">Exportar PDF</button><button class="btn ghost block" style="margin-top:8px" onclick="printRequirement('${requirementId}')">Imprimir</button>${submission.feedback?`<div class="notice warn" style="margin-top:10px"><b>Observación del revisor</b><br>${esc(submission.feedback)}</div>`:''}${!['aspirant','pastor_aspirant'].includes(currentUser().role)?`<button class="btn ghost block" style="margin-top:8px" onclick="openRequirementConfig('${requirementId}')">Configurar indicaciones</button>`:''}</aside></div></div><div class="modal-foot"><button class="btn ghost" onclick="closeModal()">Cerrar</button>${!readonly?`<button class="btn ghost" onclick="saveRequirement(false)">Guardar avance</button>`:''}${v3CanReviewRequirement(currentUser(),aspirant,status)?`<button class="btn warn" onclick="reviewRequirement('needs_changes')">Solicitar corrección</button><button class="btn green" onclick="reviewRequirement('approved')">Marcar revisado</button>`:''}</div></div>`);
  await renderRequirementFiles();if(!readonly)enableRequirementAutosave();
}

async function attachFiles(fileList) {
  if(!v3CanEditCurrentRequirementDraft())return toast('Solo el Aspirante puede adjuntar evidencias a su propio requisito mientras esté en desarrollo.');
  const aspirant=userById(modalOwnerId),submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId);
  for(const file of [...fileList]){if(!String(file.type||'').startsWith('image/')){toast('En Informes/Requisitos solo se aceptan fotos o imágenes.');continue;}const dataUrl=await imageToDataUrl(file,1200*1024,1800),attachment={id:newId('file'),ownerId:aspirant.id,programId:v3ModalProgramId,requirementId:modalRequirementId,name:file.name,type:file.type||'image/jpeg',size:dataUrlBytes(dataUrl),kind:'photo',dataUrl,reportPlacement:'auto',reportScale:70,createdAt:isoNow()};await filePut(attachment);submission.attachmentIds.push(attachment.id);}
  submission.updatedAt=isoNow();await persistDraftLocal();saveEmergencyDraft();await renderRequirementFiles();toast('Evidencia guardada como borrador local. Se sincronizará al pulsar Guardar avance o Enviar a revisión.');
}

renderRequirementFiles = async function renderRequirementFilesV3() {
  const root=document.getElementById('req_files');if(!root)return;
  const submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId),allowed=[];for(const id of submission.attachmentIds||[]){let file=null;try{file=await fileGet(String(id));}catch{}if(file&&(file.kind==='photo'||String(file.type||'').startsWith('image/')))allowed.push(file);}
  root.innerHTML=allowed.map(file=>`<div class="file-card"><img src="${file.dataUrl}" alt="${esc(file.name)}" onclick="openAttachment('${file.id}')"><button onclick="event.stopPropagation();removeAttachment('${file.id}')">×</button><div>${esc(short(file.name,28))}</div><select class="field compact" onchange="updateAttachmentLayout('${file.id}','reportPlacement',this.value)"><option value="auto" ${file.reportPlacement==='auto'?'selected':''}>Autoajustar</option><option value="page1" ${file.reportPlacement==='page1'?'selected':''}>Página 1</option><option value="page2" ${file.reportPlacement==='page2'?'selected':''}>Página 2</option></select><label class="mini-range">Tamaño ${file.reportScale||70}%<input type="range" min="1" max="100" step="1" value="${file.reportScale||70}" onchange="updateAttachmentLayout('${file.id}','reportScale',this.value)"></label></div>`).join('');
};

updateAttachmentLayout = async function updateAttachmentLayoutV3(id,key,next){if(!v3CanEditCurrentRequirementDraft())return toast('Este requisito está en modo de solo lectura.');let file=null;try{file=await fileGet(String(id));}catch{}if(!file)return;file[key]=key==='reportScale'?Number(next):next;await filePut(file);await persistDraftLocal();await renderRequirementFiles();};
removeAttachment = async function removeAttachmentV3(id) {if(!v3CanEditCurrentRequirementDraft())return toast('Este requisito está en modo de solo lectura.');const submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId);submission.attachmentIds=submission.attachmentIds.filter(item=>item!==id);await fileDelete(id);await persistDraftLocal();saveEmergencyDraft();await renderRequirementFiles();};

async function saveRequirement(send=false) {
  if(!v3CanEditCurrentRequirementDraft())return toast('Solo el Aspirante puede llenar y guardar su propio requisito.');
  const programId=v3ModalProgramId,submission=v3SubmissionFor(modalOwnerId,modalRequirementId,programId),progress=v3EnsureProgramProgress(modalOwnerId,programId),requirement=v3RequirementById(modalRequirementId,programId),config=v3ConfigFor(modalOwnerId,requirement,programId),editor=readRichEditor();
  const selections=[...document.querySelectorAll('[name=req_choice]:checked')].map(input=>input.value),minimum=Number(requirement.selection?.min||0),maximum=Number(requirement.selection?.max||0);
  if(send&&minimum&&selections.length<minimum)return toast(`Selecciona al menos ${minimum} opción(es).`);if(send&&maximum&&selections.length>maximum)return toast(`Selecciona como máximo ${maximum} opción(es).`);
  if(!editor.text)return toast('Escribe el informe antes de guardar. Las fotografías y selecciones complementan el texto, pero no lo reemplazan.');
  submission.text=editor.text;submission.richText=editor.html;submission.completionDate=value('req_date');submission.orientation=value('req_orientation')||submission.orientation||'auto';submission.selections=selections;submission.updatedAt=isoNow();
  const aspirant=userById(modalOwnerId);if(aspirant&&value('req_font'))aspirant.reportFont=value('req_font');if(send&&!submission.completionDate)return toast('Completa la fecha antes de enviar.');if(send&&!submission.text)return toast('Completa el informe antes de enviar.');
  progress.status[modalRequirementId]=send?'in_review':'in_progress';progress.updatedAt=isoNow();if(send)for(const task of database.tasks.filter(item=>item.assigneeId===modalOwnerId&&(item.programId||'class_grouped')===programId&&item.requirementId===modalRequirementId&&!item.presentedAt)){task.presentedAt=isoNow();task.updatedAt=isoNow();}
  database.sync={...(database.sync||{}),hasLocalDraft:false};
  try{localStorage.removeItem('musica_emergency_draft');}catch{}
  await persist(true,{action:send?'Requisito enviado':'Avance guardado',entity:modalRequirementId,detail:`${v3Program(programId).name} · ${userById(modalOwnerId)?.fullName||''}`});closeModal();render();toast(send?'Guardado en este equipo · envío a revisión pendiente de confirmación.':'Avance guardado en este equipo.');
}

captureRequirementDraft = function captureRequirementDraftV3() {if(!modalOwnerId||!modalRequirementId||!document.getElementById('req_date')||!v3CanEditCurrentRequirementDraft())return null;const editor=readRichEditor();return{type:'requirement',programId:v3ModalProgramId,ownerId:modalOwnerId,requirementId:modalRequirementId,text:editor.text,richText:editor.html,completionDate:value('req_date')||localDate(),orientation:value('req_orientation')||'auto',selections:[...document.querySelectorAll('[name=req_choice]:checked')].map(input=>input.value),savedAt:isoNow()};};
saveEmergencyDraft = function saveEmergencyDraftV3(){const draft=captureRequirementDraft();if(draft)try{localStorage.setItem('musica_emergency_draft',JSON.stringify(draft));}catch{}};
enableRequirementAutosave = function enableRequirementAutosaveV3(){const root=document.querySelector('.modal-bg');if(!root)return;const save=()=>{saveEmergencyDraft();};root.addEventListener('input',save);root.addEventListener('change',save);let emergency=null;try{emergency=JSON.parse(localStorage.getItem('musica_emergency_draft')||'null');}catch{}const submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId);if(emergency?.programId===v3ModalProgramId&&emergency?.ownerId===modalOwnerId&&emergency?.requirementId===modalRequirementId&&emergency.savedAt>submission.updatedAt){const text=document.getElementById('req_text');if(text)text.innerHTML=emergency.richText||plainTextToRichHtml(emergency.text||'');const date=document.getElementById('req_date');if(date)date.value=emergency.completionDate||localDate();toast('Se recuperó el borrador local. Pulsa Guardar avance cuando quieras registrarlo.');}};
flushRequirementDraft = async function flushRequirementDraftV3(){saveEmergencyDraft();};

openRequirementConfig = function openRequirementConfigV3(requirementId) {const requirement=v3RequirementById(requirementId,v3ModalProgramId),config=v3ConfigFor(modalOwnerId,requirement,v3ModalProgramId);showModal(`<div class="modal small"><div class="modal-head"><div><h3>Configurar ${esc(requirementId)}</h3><p>${esc(v3Program(v3ModalProgramId).name)} · Indicaciones visibles para este Aspirante.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveRequirementConfig(event,'${requirementId}')"><div class="modal-body"><label class="field-group">Modalidad<input id="cfg_mode" class="field" value="${esc(config.mode)}"></label><label class="field-group">Indicaciones<textarea id="cfg_instructions" class="field">${esc(config.instructions)}</textarea></label><label class="field-group">Criterio de evaluación<textarea id="cfg_evaluation" class="field">${esc(config.evaluation)}</textarea></label></div><div class="modal-foot"><button type="button" class="btn ghost" onclick="openRequirement('${requirementId}')">Volver</button><button class="btn primary">Guardar</button></div></form></div>`);};
saveRequirementConfig = async function saveRequirementConfigV3(event,requirementId){event.preventDefault();const requirement=v3RequirementById(requirementId,v3ModalProgramId);database.configs[`${v3ModalProgramId}:${modalOwnerId}:${requirementId}`]={...v3ConfigFor(modalOwnerId,requirement,v3ModalProgramId),mode:value('cfg_mode'),instructions:value('cfg_instructions'),evaluation:value('cfg_evaluation')};await persist(true,{action:'Requisito configurado',entity:requirementId,detail:`${v3Program(v3ModalProgramId).name} · ${userById(modalOwnerId)?.fullName||''}`});await openRequirement(requirementId);toast('Configuración guardada.');};

pendingReviews = function pendingReviewsV3(user=currentUser()) {
  if(!user)return[];const output=[];
  for(const aspirant of accessibleAspirants(user))for(const programId of v3AssignedProgramIds(aspirant)){
    if(user.role==='tutor'&&!v3AssignedProgramIds(user).includes(programId))continue;
    const progress=v3EnsureProgramProgress(aspirant.id,programId);
    for(const [requirementId,status] of Object.entries(progress.status))if(status==='in_review'){
      const requirement=v3RequirementById(requirementId,programId);if(requirement)output.push({aspirant,programId,program:v3Program(programId),requirement});
    }
  }
  return output;
};

renderReviews = function renderReviewsV3(){const user=currentUser(),reviews=pendingReviews(user);setTop('Revisiones',ROLE_LABELS[user.rawRole624||user.role]);setContent(`<div class="page-head"><div><div class="eyebrow">Bandeja de trabajo</div><h1 class="page-title">${reviews.length} requisito${reviews.length===1?'':'s'} en revisión</h1><p class="subtitle">Cada entrega indica su módulo, Aspirante y requisito.</p></div></div><div class="list">${reviews.map(item=>`<div class="list-item clickable" onclick="activeAspirantId='${item.aspirant.id}';v3ActiveProgramId='${item.programId}';openRequirement('${item.requirement.id}')">${requirementAreaBadge(item.requirement)}<div><h4>${esc(item.requirement.official_text)}</h4><div class="chips"><span class="chip gold">${esc(item.program.name)}</span><span class="chip">${esc(item.aspirant.fullName)}</span><span class="chip blue">${esc(clubFor(item.aspirant)?.name||'Sin Club')}</span></div></div><span class="status in_review">En revisión</span></div>`).join('')||'<div class="card empty">No hay entregas pendientes.</div>'}</div>`);};

reviewRequirement = function reviewRequirementV3(status){const reviewer=currentUser(),aspirant=userById(modalOwnerId),currentStatus=v3EnsureProgramProgress(modalOwnerId,v3ModalProgramId).status[modalRequirementId];if(!v3CanReviewRequirement(reviewer,aspirant,currentStatus))return toast('No tienes permiso para revisar este requisito.');const submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId),feedback=status==='needs_changes'?prompt('Indica qué debe corregir el Aspirante:',''):'';if(status==='needs_changes'&&!feedback)return;submission.feedback=feedback||'';submission.approval=status==='approved'?{reviewerId:currentUser().id,reviewerName:currentUser().fullName,at:isoNow()}:null;submission.updatedAt=isoNow();v3EnsureProgramProgress(modalOwnerId,v3ModalProgramId).status[modalRequirementId]=status;persist(true,{action:status==='approved'?'Requisito revisado':'Corrección solicitada',entity:modalRequirementId,detail:`${v3Program(v3ModalProgramId).name} · ${userById(modalOwnerId)?.fullName||''}`}).then(()=>{closeModal();go('reviews');toast(status==='approved'?'Requisito revisado.':'Corrección enviada.');});};

/* ──────────────────────────────────────────────────────────────────────────
   Informes por módulo
   ────────────────────────────────────────────────────────────────────────── */
reportBaseName = function reportBaseNameV3(requirement) {
  const code = AREA_SHORT[requirement?.areaCode] || requirement?.areaShort || requirement?.areaCode || 'REQ';
  return `${code} - ${compactRequirementText(requirement)}`;
};

function v3SetReportContext(programId, aspirantId, requirementId='') {
  if (v3ProgramDefinitions[programId]) {
    v3ActiveProgramId = programId;
    v3ModalProgramId = programId;
  }
  if (aspirantId) {
    activeAspirantId = aspirantId;
    modalOwnerId = aspirantId;
  }
  if (requirementId) modalRequirementId = requirementId;
}

async function v3ReportAction(action, programId, aspirantId, requirementId) {
  v3SetReportContext(programId, aspirantId, requirementId);
  if (action === 'open') return openRequirement(requirementId);
  if (action === 'preview') return previewRequirementPdf(requirementId);
  if (action === 'pdf') return exportPdf(requirementId);
  if (action === 'print') return printRequirement(requirementId);
  if (action === 'word') return exportWord(requirementId);
  if (action === 'drive') return sendReportToDrive(requirementId);
}

renderReports = function renderReportsV3() {
  const user = currentUser();
  const aspirant = targetAspirant();
  const programId = v3ActiveProgramId;
  const program = v3Program(programId);
  setTop('Informes y documentos', program.menu_label || program.name);
  if (!aspirant) return setContent('<div class="card empty">No hay Aspirante seleccionado.</div>');
  if (['aspirant','pastor_aspirant'].includes(user.role) && !v3UserHasProgram(user, programId)) return go('dashboard');
  modalOwnerId = aspirant.id;
  v3ModalProgramId = programId;
  const progress = v3EnsureProgramProgress(aspirant.id, programId);
  const items = v3ProgramRequirements(programId).filter(requirement => {
    const submission = progress.submissions[requirement.id];
    return submission && (submission.text || submission.richText || submission.attachmentIds?.length || submission.selections?.length);
  });
  setContent(`<div class="page-head"><div><div class="eyebrow">${esc(program.menu_label || program.name)} · ${esc(aspirant.fullName)}</div><h1 class="page-title">Informes y evidencias</h1><p class="subtitle">${['class_grouped','guide_major'].includes(programId)?`Tutor asignado: ${esc(v4220TutorName(aspirant))}. `:''}Cada documento conserva el título y el emblema del módulo correspondiente.</p></div><div class="actions">${!['aspirant','pastor_aspirant'].includes(user.role) ? contextSelector() : ''}${v3ProgramSelector(programId)}${['aspirant','pastor_aspirant'].includes(user.role) ? `` : ''}</div></div>
  <div class="list">${items.map(requirement => {
    const submission = v3SubmissionFor(aspirant.id, requirement.id, programId);
    const status = progress.status[requirement.id] || 'pending';
    return `<div class="list-item report-module-item">${requirementAreaBadge(requirement)}<div><h4>${esc(reportBaseName(requirement))}</h4><p>${esc(requirement.official_text)}</p><div class="chips"><span class="chip gold">${esc(program.name)}</span><span class="chip">${formatDate(submission.completionDate)}</span><span class="status ${status}">${STATUS_LABELS[status] || status}</span>${v3EffectiveSelections(requirement,submission).map(choice => `<span class="chip blue">${esc(choice)}</span>`).join('')}</div></div><div class="actions"><button class="btn ghost small" onclick="v3ReportAction('open','${programId}','${aspirant.id}','${requirement.id}')">Ver</button><button class="btn primary small" onclick="v3ReportAction('pdf','${programId}','${aspirant.id}','${requirement.id}')">Exportar PDF</button><button class="btn ghost small" onclick="v3ReportAction('print','${programId}','${aspirant.id}','${requirement.id}')">Imprimir</button><button class="btn ghost small" onclick="v3ReportAction('word','${programId}','${aspirant.id}','${requirement.id}')">Exportar a Word</button>${['aspirant','pastor_aspirant'].includes(user.role) ? `<button class="btn green small" onclick="v3ReportAction('drive','${programId}','${aspirant.id}','${requirement.id}')">Enviar a Drive</button>` : ''}</div></div>`;
  }).join('') || `<div class="card empty">Todavía no hay informes ni certificados guardados en ${esc(program.name)}.</div>`}</div>`);
};

printableRequirement = async function printableRequirementV3(requirementId) {
  const aspirant = userById(modalOwnerId) || targetAspirant();
  let programId = v3ModalProgramId;
  if (!v3RequirementById(requirementId, programId)) programId = v3ActiveProgramId;
  if (!v3RequirementById(requirementId, programId)) programId = v3FindProgramForRequirement(requirementId);
  const program = v3Program(programId);
  const requirement = v3RequirementById(requirementId, programId);
  if (!aspirant || !requirement) throw new Error('No se encontró el requisito o el Aspirante.');
  v3SetReportContext(programId, aspirant.id, requirementId);
  const baseSubmission = v3SubmissionFor(aspirant.id, requirementId, programId);
  const submission = liveRequirementSubmission(baseSubmission, aspirant.id, requirementId);
  const club = clubFor(aspirant);
  const attached = [];
  for (const id of [...new Set((submission.attachmentIds || []).map(String))]) { try { const file = await fileGet(id); if (file) attached.push(file); } catch {} }
  const officialLogo = await v3LoadProgramLogo(programId);
  const selectionHtml = v3EffectiveSelections(requirement,submission).map(item => `<p class="chosen">${esc(item)}</p>`).join('');
  const rawTextHtml = reportHtmlFromSubmission(submission);
  const inlinePhotoIds = typeof sgl512InlinePhotoIds==='function' ? sgl512InlinePhotoIds(rawTextHtml) : new Set();
  const textHtml = typeof sgl512InlineReportHtml==='function' ? sgl512InlineReportHtml(rawTextHtml,attached) : rawTextHtml;
  const attachments = attached.filter(file => file.kind === 'photo' && !inlinePhotoIds.has(String(file.id))).map(file => `<figure class="place-${file.reportPlacement || 'auto'}" style="--photo-scale:${file.reportScale || 70}"><img src="${file.dataUrl}" alt="Evidencia fotográfica"></figure>`).join('');
  const identity = club?.logo ? aspirant.fullName : `${aspirant.fullName} · ${club?.name || (programId==='music_ministry'?'Sistema de Gestión de Música':'Ministerio de Conquistadores')}`;
  const reportTitle = program.report_title || `INFORME ${String(program.name || '').toUpperCase()}`;
  const mission = typeof reportMissionName==='function' ? reportMissionName({aspirant}) : String(aspirant.mission||'').trim().toUpperCase();
  return {
    aspirant, requirement, submission, club, attached, officialLogo, identity, mission,
    programId, program, reportTitle,
    html:`<header><img src="${officialLogo}"><div class="report-header-center">${mission?`<div class="report-mission">${esc(mission)}</div>`:''}<h1>${esc(reportTitle)}</h1><p>${esc(identity)}</p></div>${club?.logo ? `<img src="${club.logo}">` : '<span></span>'}</header><main><h2 class="area-title">${esc(requirement.areaTitle)}</h2><h3 class="requirement-title">${esc(requirement.official_text)}</h3><p class="requirement-fill-date">${esc(reportRequirementFillDate({submission}))}</p>${selectionHtml}${textHtml ? `<article>${textHtml}</article>` : ''}<section class="report-photos">${attachments}</section></main>`
  };
};

makeReportPdf = async function makeReportPdfV3(requirementId, provided=null) {
  const data = provided || await printableRequirement(requirementId);
  const selected = value('req_orientation') || data.submission.orientation || 'auto';
  const font = value('req_font') || data.aspirant.reportFont || 'Arial';
  const changed = data.submission.orientation !== selected || data.aspirant.reportFont !== font;
  data.submission.orientation = selected;
  data.aspirant.reportFont = font;
  if (changed) await persist(true,{action:'Formato de informe actualizado',entity:requirementId,detail:selected});
  const attachments = data.attached.map(file => [file.id,file.createdAt,file.reportPlacement,file.reportScale,file.size]);
  const key = JSON.stringify([data.programId,data.reportTitle,data.aspirant.id,requirementId,reportSubmissionCacheKey(data.submission),selected,font,data.club?.logo?.length || 0,data.officialLogo?.length || 0,attachments]);
  if (reportPdfCache.has(key)) return reportPdfCache.get(key);
  const pdf = await makeVectorReportPdf(data,selected,font);
  reportPdfCache.set(key,pdf);
  while (reportPdfCache.size > 8) reportPdfCache.delete(reportPdfCache.keys().next().value);
  return pdf;
};

/* ──────────────────────────────────────────────────────────────────────────
   Año bíblico de Guía Mayor, Guía Mayor Máster y Guía Mayor Máster Avanzado
   ────────────────────────────────────────────────────────────────────────── */
let v3BiblePage = 0;
const V3_BIBLE_PAGE_SIZE = 30;

function v3EnsureBibleYear(userId, programId=v3ActiveProgramId) {
  database.bibleYear[userId] ||= {};
  const program = v3Program(programId);
  database.bibleYear[userId][programId] ||= {
    mode:['guide_master','guide_master_advanced'].includes(programId) ? 'reading' : 'young_bible',
    startDate:`${new Date().getFullYear()}-01-01`,
    entries:{},
    summary:'',
    updatedAt:isoNow()
  };
  const plan = database.bibleYear[userId][programId];
  plan.entries ||= {};
  plan.mode ||= ['guide_master','guide_master_advanced'].includes(programId) ? 'reading' : 'young_bible';
  plan.startDate ||= `${new Date().getFullYear()}-01-01`;
  plan.summary ||= '';
  return plan;
}

function v3BibleModeLabel(mode, programId=v3ActiveProgramId) {
  return mode === 'audio' ? 'Año Bíblico en audio' : 'Año Bíblico';
}

function v3BibleDayDate(plan, day) {
  const base = new Date(`${plan.startDate || localDate()}T12:00:00`);
  if (Number.isNaN(base.getTime())) return '';
  base.setDate(base.getDate() + Number(day) - 1);
  const offset = base.getTimezoneOffset();
  return new Date(base.getTime() - offset * 60000).toISOString().slice(0,10);
}

function v3BibleCompletedCount(plan) {
  return Object.values(plan.entries || {}).filter(entry => entry.completed).length;
}

function v3BiblePageChange(delta) {
  const maxPage = Math.ceil(365 / V3_BIBLE_PAGE_SIZE) - 1;
  v3BiblePage = Math.max(0,Math.min(maxPage,v3BiblePage + delta));
  renderBible();
}

renderBible = function renderBibleV3() {
  if (v3ActiveProgramId === 'class_grouped') return V3_ORIGINAL.renderBible();
  const user = currentUser();
  const aspirant = targetAspirant();
  const programId = v3ActiveProgramId;
  const program = v3Program(programId);
  if (!aspirant) return setContent('<div class="card empty">No hay Aspirante seleccionado.</div>');
  if (['aspirant','pastor_aspirant'].includes(user.role) && !v3UserHasProgram(user,programId)) return go('dashboard');
  const plan = v3EnsureBibleYear(aspirant.id,programId);
  const completed = v3BibleCompletedCount(plan);
  const percent = Math.round(completed * 100 / 365);
  const start = v3BiblePage * V3_BIBLE_PAGE_SIZE + 1;
  const end = Math.min(365,start + V3_BIBLE_PAGE_SIZE - 1);
  const officialRequirement = v3RequirementById(program.bible_requirement_id,programId);
  setTop('Año Bíblico',program.menu_label || program.name);
  setContent(`<div class="page-head"><div><div class="eyebrow">${esc(program.name)} · ${esc(aspirant.fullName)}</div><h1 class="page-title">Registro de 365 días</h1><p class="subtitle">El documento oficial no define pasajes diarios; registra aquí la referencia realmente leída o escuchada.</p></div><div class="actions">${!['aspirant','pastor_aspirant'].includes(user.role) ? contextSelector() : ''}${v3ProgramSelector(programId)}</div></div>
  <section class="bible-year-hero"><div><span class="program-badge"><img src="${esc(program.logo || appLogo())}" alt=""><span>${esc(v3BibleModeLabel(plan.mode,programId))}</span></span><h2>${completed} de 365 días registrados</h2><p>${esc(officialRequirement?.official_text || 'Registro de Año Bíblico')}</p></div><div class="program-progress-ring"><strong>${percent}%</strong><span>${365-completed} días pendientes</span></div></section>
  <div class="two bible-year-settings"><div class="card"><div class="card-head"><div><h3>Configuración del registro</h3><p class="subtitle" style="margin:0">La fecha de cada día se calcula desde el inicio, pero puede editarse al registrar.</p></div></div><div class="field-row"><label class="field-group">Fecha de inicio<input id="bible_year_start" type="date" class="field" value="${esc(plan.startDate)}" ${['aspirant','pastor_aspirant'].includes(user.role) ? '' : 'disabled'}></label>${['guide_master','guide_master_advanced'].includes(programId) ? `<label class="field-group">Hábito devocional<select id="bible_year_mode" class="field" ${['aspirant','pastor_aspirant'].includes(user.role) ? '' : 'disabled'}><option value="reading" ${plan.mode === 'reading' ? 'selected' : ''}>Año Bíblico</option><option value="audio" ${plan.mode === 'audio' ? 'selected' : ''}>Año Bíblico en audio</option></select></label>` : `<label class="field-group">Modalidad<input class="field" value="Año Bíblico" disabled></label>`}</div>${['aspirant','pastor_aspirant'].includes(user.role) ? '<button class="btn primary" onclick="v3SaveBibleYearSettings()">Guardar configuración</button>' : ''}</div><div class="card"><div class="card-head"><div><h3>Requisito oficial relacionado</h3><p class="subtitle" style="margin:0">El registro diario complementa, pero no reemplaza, la evidencia oficial.</p></div></div><p>${esc(officialRequirement?.official_text || '')}</p>${officialRequirement?.observation ? `<div class="notice"><b>Observación oficial:</b><br>${esc(officialRequirement.observation)}</div>` : ''}<div class="actions" style="margin-top:12px"><button class="btn primary" onclick="openRequirement('${esc(program.bible_requirement_id || '')}')">Abrir requisito</button><button class="btn ghost" onclick="v3GenerateBibleYearSummary()">Generar informe del registro</button></div></div></div>
  <section class="card bible-year-card"><div class="card-head"><div><h3>Días ${start} al ${end}</h3><p class="subtitle" style="margin:0">Marca cada día después de completar la lectura o audio.</p></div><div class="actions"><button class="btn ghost small" onclick="v3BiblePageChange(-1)" ${start === 1 ? 'disabled' : ''}>‹ Anteriores</button><span class="chip">Página ${v3BiblePage+1} de ${Math.ceil(365/V3_BIBLE_PAGE_SIZE)}</span><button class="btn ghost small" onclick="v3BiblePageChange(1)" ${end === 365 ? 'disabled' : ''}>Siguientes ›</button></div></div><div class="bible-day-grid">${Array.from({length:end-start+1},(_,index) => {
    const day = start + index;
    const entry = plan.entries[String(day)] || {};
    const date = entry.date || v3BibleDayDate(plan,day);
    return `<button class="bible-day ${entry.completed ? 'completed' : ''}" onclick="openBibleYearDay(${day})"><b>Día ${day}</b><span>${formatDate(date)}</span><small>${entry.reference ? esc(short(entry.reference,32)) : 'Sin referencia'}</small><i>${entry.completed ? '✓ Completado' : 'Registrar'}</i></button>`;
  }).join('')}</div></section>`);
};

async function v3SaveBibleYearSettings() {
  const user = currentUser();
  if (!['aspirant','pastor_aspirant'].includes(user?.role)) return;
  const plan = v3EnsureBibleYear(user.id,v3ActiveProgramId);
  const startDate = value('bible_year_start');
  if (!startDate) return toast('Selecciona la fecha de inicio.');
  plan.startDate = startDate;
  if (['guide_master','guide_master_advanced'].includes(v3ActiveProgramId)) plan.mode = value('bible_year_mode') || 'reading';
  plan.updatedAt = isoNow();
  await persist(true,{action:'Año bíblico configurado',entity:v3ActiveProgramId,detail:`${v3BibleModeLabel(plan.mode,v3ActiveProgramId)} · ${startDate}`});
  renderBible();
  toast('Configuración del Año Bíblico guardada.');
}

function openBibleYearDay(day) {
  const aspirant = targetAspirant();
  if (!aspirant) return;
  const programId = v3ActiveProgramId;
  const plan = v3EnsureBibleYear(aspirant.id,programId);
  const entry = plan.entries[String(day)] || {};
  const readonly = !['aspirant','pastor_aspirant'].includes(currentUser().role) || currentUser().id !== aspirant.id;
  const mode = entry.mode || plan.mode;
  showModal(`<div class="modal small"><div class="modal-head"><div><h3>Día ${day} · ${esc(v3BibleModeLabel(mode,programId))}</h3><p>${esc(v3Program(programId).name)} · ${esc(aspirant.fullName)}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveBibleYearDay(event,${day})"><div class="modal-body"><label class="field-group">Fecha<input id="bible_day_date" type="date" class="field" value="${esc(entry.date || v3BibleDayDate(plan,day))}" ${readonly ? 'disabled' : ''}></label>${['guide_master','guide_master_advanced'].includes(programId) ? `<label class="field-group">Modalidad de este día<select id="bible_day_mode" class="field" ${readonly ? 'disabled' : ''}><option value="reading" ${mode === 'reading' ? 'selected' : ''}>Lectura</option><option value="audio" ${mode === 'audio' ? 'selected' : ''}>Audio</option></select></label>` : ''}<label class="field-group">Referencia leída o escuchada<input id="bible_day_reference" class="field" placeholder="Ej.: Génesis 1-3" value="${esc(entry.reference || '')}" ${readonly ? 'disabled' : ''}></label><label class="field-group">Reflexión o nota breve<textarea id="bible_day_reflection" class="field" placeholder="Qué aprendiste o qué versículo llamó tu atención" ${readonly ? 'disabled' : ''}>${esc(entry.reflection || '')}</textarea></label><label class="choice"><input id="bible_day_completed" type="checkbox" ${entry.completed ? 'checked' : ''} ${readonly ? 'disabled' : ''}> Día completado</label><div class="notice">Este diario es una herramienta de seguimiento. La constancia, certificado o informe solicitado debe presentarse en el requisito oficial del módulo.</div></div><div class="modal-foot"><button type="button" class="btn ghost" onclick="closeModal()">Cerrar</button>${readonly ? '' : '<button class="btn primary">Guardar día</button>'}</div></form></div>`);
}

async function saveBibleYearDay(event,day) {
  event.preventDefault();
  const user = currentUser();
  if (!['aspirant','pastor_aspirant'].includes(user?.role)) return;
  const plan = v3EnsureBibleYear(user.id,v3ActiveProgramId);
  const completed = !!document.getElementById('bible_day_completed')?.checked;
  const reference = value('bible_day_reference').trim();
  if (completed && !reference) return toast('Escribe la referencia leída o escuchada antes de marcar el día.');
  plan.entries[String(day)] = {
    day:Number(day),
    date:value('bible_day_date') || v3BibleDayDate(plan,day),
    mode:['guide_master','guide_master_advanced'].includes(v3ActiveProgramId) ? (value('bible_day_mode') || plan.mode) : 'young_bible',
    reference,
    reflection:value('bible_day_reflection').trim(),
    completed,
    updatedAt:isoNow()
  };
  plan.updatedAt = isoNow();
  await persist(true,{action:'Día de Año Bíblico actualizado',entity:`${v3ActiveProgramId}:${day}`,detail:reference || 'Sin referencia'});
  closeModal();
  renderBible();
  toast(`Día ${day} guardado.`);
}

async function v3GenerateBibleYearSummary() {
  const aspirant = targetAspirant();
  if (!aspirant) return;
  const programId = v3ActiveProgramId;
  const program = v3Program(programId);
  const plan = v3EnsureBibleYear(aspirant.id,programId);
  const completedEntries = Object.values(plan.entries || {}).filter(entry => entry.completed).sort((a,b) => a.day-b.day);
  if (!completedEntries.length) return toast('Registra al menos un día antes de generar el informe.');
  const first = completedEntries[0];
  const last = completedEntries.at(-1);
  const lines = [
    `${program.name} · ${v3BibleModeLabel(plan.mode,programId)}`,
    `Aspirante: ${aspirant.fullName}`,
    `Días completados: ${completedEntries.length} de 365`,
    `Período registrado: ${formatDate(first.date)} al ${formatDate(last.date)}`,
    '',
    ...completedEntries.map(entry => `Día ${entry.day} · ${formatDate(entry.date)} · ${entry.reference}${entry.reflection ? `\n${entry.reflection}` : ''}`)
  ];
  const summary = lines.join('\n');
  plan.summary = summary;
  plan.updatedAt = isoNow();
  const requirementId = program.bible_requirement_id;
  if (['guide_master','guide_master_advanced','music_ministry'].includes(programId) && requirementId) {
    const submission = v3SubmissionFor(aspirant.id,requirementId,programId);
    submission.text = summary;
    submission.richText = plainTextToRichHtml(summary);
    submission.completionDate = last.date || localDate();
    submission.updatedAt = isoNow();
    const progress = v3EnsureProgramProgress(aspirant.id,programId);
    if (progress.status[requirementId] === 'pending') progress.status[requirementId] = 'in_progress';
  }
  await persist(true,{action:'Informe de Año Bíblico generado',entity:`${programId}:${requirementId || 'tracker'}`,detail:`${completedEntries.length}/365 días`});
  if (['guide_master','guide_master_advanced','music_ministry'].includes(programId)) {
    toast('El informe del registro quedó preparado como borrador del requisito oficial.');
    return openRequirement(requirementId);
  }
  toast('Resumen generado. Si cuentas con certificado o constancia, puedes adjuntarlo como evidencia opcional en el requisito oficial.');
}

/* ──────────────────────────────────────────────────────────────────────────
   Conexión inicial, configuración y sincronización automática
   ────────────────────────────────────────────────────────────────────────── */
let v3SyncRequestsLoading = false;

function v3ConnectionValues() {
  return {
    serverUrl:(value('set_server') || value('v3_server_url') || database.settings.serverUrl || '').trim().replace(/\/$/,''),
    serverToken:(value('set_token') || value('v3_server_token') || database.settings.serverToken || '').trim()
  };
}

function v3UseLocalAdminProxy() {
  const user=currentUser();
  return !REMOTE_WEB && user?.role==='admin' && (database.settings.remoteAccessUrl || /^https?:\/\/(127\.0\.0\.1|localhost):8895$/i.test(database.settings.serverUrl||''));
}

async function v3Api(path, options={}) {
  const localAdminProxy = !options.serverUrl && v3UseLocalAdminProxy();
  const url = (options.serverUrl || database.settings.serverUrl || '').replace(/\/$/,'');
  let token = options.serverToken ?? database.settings.serverToken ?? '';
  if (!url && !localAdminProxy) throw new Error('No se configuró la URL del servidor.');
  const requestUrl = localAdminProxy ? `/api/local/server${path}` : `${url}${path}`;
  if (localAdminProxy) token='';
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), options.timeout || 120000);
  try {
    const response = await fetch(requestUrl,{
      method:options.method || 'GET',
      headers:{
        'Authorization':`Bearer ${token}`,
        'Cache-Control':'no-cache',
        'Pragma':'no-cache',
        ...(options.body !== undefined ? {'Content-Type':'application/json'} : {}),
        ...(options.headers || {})
      },
      body:options.body === undefined ? undefined : JSON.stringify(options.body),
      cache:'no-store',
      signal:controller.signal
    });
    let payload = null;
    const text = await response.text();
    if (text) {
      try { payload = JSON.parse(text); }
      catch { payload = {error:text}; }
    }
    if (!response.ok && !options.allowStatuses?.includes(response.status)) {
      const error = new Error(payload?.error || `HTTP ${response.status}`);
      error.status = response.status;
      error.payload = payload;
      throw error;
    }
    return {response,payload};
  } finally {
    clearTimeout(timer);
  }
}

async function v3FetchBootstrap(serverUrl=database.settings.serverUrl,serverToken=database.settings.serverToken) {
  const {payload} = await v3Api('/api/bootstrap',{serverUrl,serverToken,timeout:180000});
  if (!payload?.database) throw new Error('El servidor todavía no tiene una instalación inicial. El Administrador principal debe sincronizar primero.');
  return payload;
}

