async function v4SendQueuedOperation(op,user){
  const files=await v4FilesForOperation(op);
  if(op.action==='review'&&op.requirementId){
    const submission=structuredClone(v3SubmissionFor(op.ownerId,op.requirementId,op.programId||'class_grouped'));
    return v3Api('/api/reviews/submit',{
      method:'POST',allowStatuses:[409,422],timeout:180000,
      body:{
        installationId:database.installationId,actorId:user.id,actorRole:user.role,ownerId:op.ownerId||user.id,
        operationId:op.id,requirementId:op.requirementId,requirementTitle:op.requirementTitle||'',programId:op.programId||'class_grouped',
        contentHash:op.contentHash||'',submission,files
      }
    });
  }
  return v3Api('/api/sync',{
    method:'POST',allowStatuses:[202,409,422],timeout:60000,
    body:{installationId:database.installationId,proposalId:op.proposalId||null,actorId:user.id,actorRole:user.role,actorName:user.fullName,baseVersion:Math.max(Number(database.serverVersion||0),Number(database.sync?.ackServerVersion||0)),operationId:op.id,operationType:op.action,ownerId:op.ownerId||user.id,requirementId:op.requirementId||'',requirementTitle:op.requirementTitle||'',programId:op.programId||'',contentHash:op.contentHash||'',patch:v4PatchForOperation(op),files}
  });
}


function v4215OperationAcknowledged(payload,op){
  if(!payload||payload.ok===false)return false;
  if(payload.operationId&&op?.id&&payload.operationId!==op.id)return false;
  if(payload.clearLocalOperation===true)return true;
  const status=String(payload.status||'').toLowerCase();
  if(['applied','accepted','in_review','submitted','saved','ok'].includes(status))return true;
  if(payload.ackOnly===true&&payload.serverVersion!==undefined)return true;
  return false;
}
function v4215AckHistoryStatus(payload,op){
  const channel=String(payload?.channel||'');
  if(channel==='reviews'||op?.action==='review')return 'in_review';
  return String(payload?.status||'applied').toLowerCase()==='accepted'?'accepted':'applied';
}
function v4215AckHistoryNote(payload,op){
  if(payload?.deduplicated)return 'Confirmado por idempotencia del servidor';
  if(String(payload?.channel||'')==='reviews'||op?.action==='review')return 'Enviado a REVISIONES por el canal de evidencias';
  return 'Datos normales aceptados por el servidor';
}

v3ApplyServerSnapshot = async function v3ApplyServerSnapshotV4(snapshot,notification=null){
  v4EnsureReliableState();
  const result=await V4R_BASE_APPLY_SERVER_SNAPSHOT(snapshot,notification);
  if(result===false||result?.stale||result?.deferred)return result;
  const queue=database.syncQueue||[],reviewHydratedNotices=database.sync?.reviewHydratedNotices||{};
  const queued=queue.some(item=>['queued','retry','sending'].includes(item.status));
  database.sync={...(database.sync||{}),reviewHydratedNotices,state:queued?'pending':'ok',message:queued?'Hay cambios guardados pendientes de envío':'Sincronizado',needsUpload:queued,pendingProposal:null};
  await kvSet('database',database);renderTopSync();v4UpdateMessagePill();
  if(queued&&v3CanAttemptNetwork())setTimeout(()=>syncNow(),250);
  return result;
};

// Preserve ordering for related edits while independent operations can retry fairly.
function sgl559RetryDelay(op){return Math.min(30000,2000*Math.pow(2,Math.min(4,Math.max(0,Number(op.attempts||1)-1))));}
function sgl559OwnPending(queue,actorId){return (queue||[]).filter(op=>op.actorId===actorId&&['queued','retry','sending'].includes(op.status));}
function sgl559WritePaths(value,path=[],out=[]){
  if(Array.isArray(value)&&value.length&&value.every(item=>item&&typeof item==='object'&&!Array.isArray(item)&&item.id!=null)){
    for(const item of value)sgl559WritePaths(item,[...path,'id:'+String(item.id)],out);
  }else if(value&&typeof value==='object'&&!Array.isArray(value)){
    if(Object.keys(value).length===1&&value.__sglReplace!==undefined)out.push(path);
    else if(Object.keys(value).length===1&&value.__sglSetMembers){for(const id of [...(value.__sglSetMembers.add||[]),...(value.__sglSetMembers.remove||[])])out.push([...path,'id:'+String(id)]);}
    else for(const [key,item] of Object.entries(value)){
      if(key==='audit'||key==='id'||key==='updatedAt')continue;
      if(key==='__sglDeleteKeys'){for(const name of item||[])out.push([...path,String(name)]);}
      else sgl559WritePaths(item,[...path,key],out);
    }
  }else out.push(path);
  return out;
}
function sgl559RelatedOperations(a,b){
  if(a.patch&&b.patch){
    const left=sgl559WritePaths(a.patch),right=sgl559WritePaths(b.patch);
    return left.some(x=>right.some(y=>x.slice(0,Math.min(x.length,y.length)).every((part,i)=>part===y[i])));
  }
  if(a.ownerId&&b.ownerId)return a.ownerId===b.ownerId&&(a.programId||'class_grouped')===(b.programId||'class_grouped')&&(!a.requirementId||!b.requirementId||a.requirementId===b.requirementId);
  return !!a.entityId&&a.entityId===b.entityId;
}
function sgl559NextOperation(queue,actorId,action=''){
  const own=sgl559OwnPending(queue,actorId);
  return own.find((op,index)=>(!action||op.action===action)&&['queued','retry'].includes(op.status)&&!sgl546Uncommitted.has(op.id)&&!sgl546ActiveSending.has(op.id)&&Number(op.nextAttemptAt||0)<=Date.now()&&!own.slice(0,index).some(prior=>sgl559RelatedOperations(prior,op)));
}

async function v4SyncNowCore(){
  const user=currentUser();if(!user)return;
  if(user.role==='admin')return V4R_BASE_ADMIN_SYNC();
  v4EnsureReliableState();
  if(!database?.settings?.serverUrl){database.sync={...(database.sync||{}),state:'local',message:'Guardado en este dispositivo'};renderTopSync();return;}
  if(database.sync?.pendingProposal?.cancelQueued)return v4FlushQueuedCancellation();
  // Las propuestas pendientes solo pueden existir por compatibilidad con envíos
  // creados por versiones anteriores. Los envíos 4.2.13 se aplican automáticamente.
  if(database.sync?.pendingProposal?.id)return v3CheckProposalStatus(false);
  const op=sgl559NextOperation(database.syncQueue,user.id);
  if(!op){const pending=sgl559OwnPending(database.syncQueue,user.id).length>0;database.sync={...(database.sync||{}),state:pending?'pending':'ok',message:pending?'Cambios guardados · esperando reintento':'Sin cambios pendientes',needsUpload:pending};await kvSet('database',database);renderTopSync();return v3PullServerUpdates(false);}
  if(!v3CanAttemptNetwork()){database.sync={...(database.sync||{}),state:'pending',message:`${op.id} guardado · esperando conexión`,needsUpload:true};await kvSet('database',database);renderTopSync();return;}
  database.sync={...(database.sync||{}),state:'syncing',message:`Sincronizando ${op.id}…`,needsUpload:true};renderTopSync();
  try{
    op.status='sending';sgl546ActiveSending.add(op.id);
    op.attempts=Number(op.attempts||0)+1;op.updatedAt=isoNow();delete op.lastError;
    await kvSet('database',database);
    const {response,payload}=await v4SendQueuedOperation(op,user);
    if(response.status===409&&payload?.code==='OPERATION_CONFLICT'){op.status='retry';op.lastError=payload.error||'Conflicto de identificador de envío';database.sync={...(database.sync||{}),state:'pending',message:op.lastError,needsUpload:true};await kvSet('database',database);renderTopSync();return;}
    if(response.status===409){op.status='retry';database.sync={...(database.sync||{}),state:'pending',message:`${op.id} guardado · actualizando versión del servidor`,needsUpload:true};await kvSet('database',database);renderTopSync();try{await v4RebasePendingOperationsFromServer(false);}catch(rebaseError){op.lastError=String(rebaseError?.message||rebaseError);await kvSet('database',database);}return;}
    if(response.status===422){throw new Error(payload?.error||'El servidor no aceptó el cambio. Se conserva el envío para reintentar.');}
    if(response.status===200&&v4215OperationAcknowledged(payload,op)){
      op.filesReceived=payload.filesReceived===true&&payload.operationId===op.id;
      v4CompleteOperation(op.id,v4215AckHistoryStatus(payload,op),v4215AckHistoryNote(payload,op));
      if(op.action==='review')toast(op.filesReceived?'Informe y archivos recibidos por el servidor para revisión.':payload.deduplicated?'El servidor ya tiene una entrega de este requisito.':'Solicitud aceptada por el servidor anterior; la descarga de archivos se verificará en Revisiones.');
      // Un ACK pequeno confirma el cambio sin descargar toda la base por cada
      // checkbox. La cola local se limpia inmediatamente; al vaciarse se baja
      // la foto canonica del servidor para refrescar vistas y contadores.
      database.sync={...(database.sync||{}),ackServerVersion:Number(payload.serverVersion||0)};
      const more=database.syncQueue.some(item=>['queued','retry','sending'].includes(item.status));
      if(more){
        database.sync={...(database.sync||{}),state:'pending',lastSyncedAt:isoNow(),message:'Cambio confirmado · enviando los siguientes',needsUpload:true,pendingProposal:null};
        await kvSet('database',database);renderTopSync();return;
      }
      if(payload?.database) await v3ApplyServerSnapshot(payload,{type:'sync',title:'Sincronizado',message:String(payload?.channel||'')==='reviews'?'Enviado a REVISIONES.':'Datos aplicados en el servidor.',operationId:op.id});
      else {
        database.sync={...(database.sync||{}),state:'ok',lastSyncedAt:isoNow(),message:'Sincronización completa · datos guardados en servidor',needsUpload:false,pendingProposal:null};
        await kvSet('database',database);renderTopSync();
      }
      return;
    }
    // Compatibilidad: si se conecta temporalmente contra un servidor 4.2.5 o
    // anterior, conserva la solicitud existente en vez de perder el envío.
    if(response.status===202){
      op.status='sent';op.proposalId=payload.proposalId;op.updatedAt=payload.updatedAt||isoNow();
      const proposal={id:payload.proposalId,status:payload.status||'pending',submittedAt:payload.submittedAt||isoNow(),serverVersion:Number(payload.serverVersion||database.serverVersion||0),operationId:op.id,operationType:op.action,requirementId:op.requirementId,programId:op.programId};
      database.sync={state:'approval',lastSyncedAt:database.sync?.lastSyncedAt||null,message:`${op.id} · solicitud heredada pendiente`,pendingProposal:proposal,needsUpload:database.syncQueue.some(item=>item.id!==op.id&&['queued','retry','sending'].includes(item.status)),hasLocalDraft:false};
      await kvSet('database',database);renderTopSync();
      return;
    }
    throw new Error(`Respuesta de sincronización no reconocida (${response.status})`);
  }catch(error){
    if(error?.restoreHandled||error?.payload?.code==='RESTORE_REQUIRED')return;
    if(!database.syncQueue.some(item=>item.id===op.id))return;
    op.status='retry';op.lastError=String(error?.message||error);op.updatedAt=isoNow();op.nextAttemptAt=Date.now()+sgl559RetryDelay(op);
    const detail=error?.name==='AbortError'?'tiempo de espera agotado':String(error?.message||error||'error de red');
    database.sync={...(database.sync||{}),state:'pending',message:`${op.id} pendiente · ${detail}`,needsUpload:true};
    await kvSet('database',database);renderTopSync();
  }finally{sgl546ActiveSending.delete(op.id);}
};

syncNow = function syncNowV4Reliable(){
  if(v4SyncOperationPromise)return v4SyncOperationPromise;
  v4SyncOperationPromise=v4SyncNowCore().finally(()=>{v4SyncOperationPromise=null;});
  return v4SyncOperationPromise;
};

v3CheckProposalStatus = async function v3CheckProposalStatusV4(showToast=true){
  const pending=database.sync?.pendingProposal;if(!pending?.id||!database.settings.serverUrl||!v3CanAttemptNetwork())return null;
  try{
    const query=new URLSearchParams({proposalId:pending.id,installationId:database.installationId,actorId:currentUser()?.id||''});
    const {payload}=await v3Api(`/api/proposals/status?${query.toString()}`,{timeout:60000});const status=payload?.status||'pending';
    pending.status=status;pending.updatedAt=payload.updatedAt||isoNow();
    if(status==='accepted'){
      const operationId=pending.operationId||payload.operationId||'';if(operationId)v4CompleteOperation(operationId,'accepted',payload.note||'');
      database.sync.pendingProposal=null;
      await v3ApplyServerSnapshot(payload,{type:'accepted',title:'Cambios aceptados',message:payload.note||'El Administrador aceptó tu sincronización.',proposalId:pending.id});
      if(showToast)toast('El Administrador aceptó el cambio. Se descargó la versión aprobada.');return status;
    }
    if(['rejected','correction','cancelled','obsolete'].includes(status)){
      const operationId=pending.operationId||payload.operationId||'';if(operationId)v4CompleteOperation(operationId,status,payload.note||'');
      const reqId=pending.requirementId||payload.requirementId,programId=pending.programId||payload.programId||'class_grouped';
      if(reqId){const progress=v3EnsureProgramProgress(currentUser().id,programId);if(status==='correction')progress.status[reqId]='needs_changes';else if(status==='cancelled'&&progress.status[reqId]==='in_review')progress.status[reqId]='in_progress';const submission=v3SubmissionFor(currentUser().id,reqId,programId);if(status==='correction')submission.feedback=payload.note||submission.feedback||'';}
      const title=status==='rejected'?'Sincronización rechazada':status==='correction'?'Corrección solicitada':status==='obsolete'?'Solicitud antigua/no aplicable':'Envío cancelado';v3AddSyncNotification(status,title,payload.note||title,pending.id);
      database.sync={...(database.sync||{}),state:database.syncQueue.length?'pending':status,lastSyncedAt:database.sync?.lastSyncedAt||null,message:title,pendingProposal:null,needsUpload:database.syncQueue.some(item=>['queued','retry','sending'].includes(item.status))};
      await kvSet('database',database);renderTopSync();if(showToast)toast(`${title}${payload.note?`: ${payload.note}`:''}`);if(database.sync.needsUpload&&v3CanAttemptNetwork())setTimeout(()=>syncNow(),250);return status;
    }
    database.sync={...(database.sync||{}),state:'approval',message:status==='postponed'?`${pending.operationId||pending.id} · revisión pospuesta`:`${pending.operationId||pending.id} · esperando revisión`,pendingProposal:pending};
    await kvSet('database',database);renderTopSync();return status;
  }catch(error){if(showToast)toast(`No se pudo consultar la solicitud: ${error.message}`);return null;}
};

v3PollClientSync = async function v3PollClientSyncV4(showToast=false){
  const user=currentUser();if(!user||user.role==='admin'||!database.settings.serverUrl)return null;v4EnsureReliableState();
  await v4FlushMessageOutbox();
  if(database.sync?.pendingProposal?.cancelQueued)return v4FlushQueuedCancellation();
  if(database.sync?.pendingProposal?.id)return v3CheckProposalStatus(showToast);
  if(database.syncQueue.some(item=>['queued','retry'].includes(item.status)))return syncNow();
  return v3PullServerUpdates(showToast);
};

v3WakeSync = async function v3WakeSyncV4(reason='resume'){
  const now=Date.now();if(now-v3LastWakeSyncAt<800)return null;v3LastWakeSyncAt=now;const user=currentUser();if(!user||!database?.settings?.serverUrl)return null;
  if(REMOTE_WEB)remoteHeartbeat();
  // Mensajes, presencia y cualquier guardado pendiente se reintentan al volver
  // a la app. La cola es técnica/offline y no requiere aprobación administrativa.
  await v4FlushMessageOutbox();v4FetchMessages(true).catch(()=>{});
  return user.role==='admin'?v3FetchSyncRequests(false):v3PollClientSync(false);
};
window.v3WakeSync=v3WakeSync;

function v4CanCancelReview(requirementId,programId=v3ModalProgramId){const user=currentUser();if(!['aspirant','pastor_aspirant'].includes(user?.role)||user.id!==modalOwnerId)return false;return v3EnsureProgramProgress(modalOwnerId,programId).status[requirementId]==='in_review';}
async function v4CancelRequirementReview(requirementId,programId=v3ModalProgramId){
  const user=currentUser();if(!user||!['aspirant','pastor_aspirant'].includes(user.role))return;v4EnsureReliableState();
  const progress=v3EnsureProgramProgress(user.id,programId),pending=database.sync?.pendingProposal;
  if(pending?.id&&pending.requirementId===requirementId){
    if(!v3CanAttemptNetwork()){
      pending.cancelQueued=true;pending.cancelNote='Revisión cancelada por el Aspirante';progress.status[requirementId]='in_progress';database.sync.message='Cancelación guardada · se enviará al recuperar conexión';await persist(false,{action:'Cancelación de revisión guardada',entity:requirementId,detail:programId});closeModal();render();toast('Cancelación guardada. El Administrador la verá al recuperar conexión.');return;
    }
    try{await v3Api('/api/proposals/cancel',{method:'POST',body:{actorId:user.id,proposalId:pending.id,installationId:database.installationId,note:'Revisión cancelada por el Aspirante'},timeout:60000});const opId=pending.operationId;if(opId)v4CompleteOperation(opId,'cancelled','Cancelada por el usuario');database.sync.pendingProposal=null;progress.status[requirementId]='in_progress';await persist(false,{action:'Revisión cancelada',entity:requirementId,detail:programId});closeModal();render();toast('Envío cancelado. El Administrador ya verá la solicitud como cancelada.');return;}catch(error){toast(`No se pudo cancelar ahora: ${error.message}`);return;}
  }
  const queued=v4QueuedForRequirement(requirementId,programId,'review');
  if(queued&&!queued.proposalId){v4CompleteOperation(queued.id,'cancelled','Cancelada antes de enviarse');progress.status[requirementId]='in_progress';await persist(false,{action:'Revisión cancelada antes de enviar',entity:requirementId,detail:programId});closeModal();render();toast('El envío se canceló antes de llegar al Administrador.');return;}
  // Si la sincronización ya fue aceptada pero el requisito continúa En revisión,
  // la cancelación se convierte en una nueva operación explícita y codificada.
  progress.status[requirementId]='in_progress';await persist(false,{action:'Cancelación de revisión solicitada',entity:requirementId,detail:programId});await v4QueueRequirementSync('cancel_review',requirementId,programId,user.id);closeModal();render();toast('Cancelación registrada. Se sincronizará automáticamente.');
}
window.v4CancelRequirementReview=v4CancelRequirementReview;
async function v4FlushQueuedCancellation(){const pending=database.sync?.pendingProposal;if(!pending?.id||!pending.cancelQueued||!v3CanAttemptNetwork())return null;try{await v3Api('/api/proposals/cancel',{method:'POST',body:{actorId:currentUser().id,proposalId:pending.id,installationId:database.installationId,note:pending.cancelNote||'Revisión cancelada por el usuario'},timeout:60000});if(pending.operationId)v4CompleteOperation(pending.operationId,'cancelled','Cancelada por el usuario');database.sync.pendingProposal=null;database.sync.message='Envío cancelado';await kvSet('database',database);renderTopSync();return'cancelled';}catch{return null;}}

// Inserta Cancelar envío y activa asistencia de teclado sin duplicar el gran modal.
openRequirement = async function openRequirementV4Reliable(requirementId){
  if(window.innerWidth<=820&&typeof closeMobileMenu==='function')closeMobileMenu();
  await V4R_BASE_OPEN_REQUIREMENT(requirementId);
  if(v4CanCancelReview(requirementId,v3ModalProgramId)){
    const foot=document.querySelector('.modal-bg .modal-foot');if(foot&&!foot.querySelector('.cancel-review-btn'))foot.insertAdjacentHTML('beforeend',`<button class="btn red cancel-review-btn" onclick="v4CancelRequirementReview('${esc(requirementId)}','${esc(v3ModalProgramId)}')">Cancelar envío</button>`);
  }
  v4FocusAssistCurrentModal();
};

// Guardar avance y Enviar a revisión usan el mismo persist automático. El segundo
// únicamente cambia el estado del requisito a in_review para el módulo Revisiones.
const V4R_SAVE_REQUIREMENT_LOCAL = saveRequirement;
saveRequirement = async function saveRequirementV4Reliable(send=false){
  if(!v3CanEditCurrentRequirementDraft())return toast('Solo el Aspirante puede llenar y guardar su propio requisito.');
  if(send&&v4QueuedForRequirement(modalRequirementId,v3ModalProgramId,'review'))return toast('Este requisito ya tiene un envío a revisión registrado.');
  await V4R_SAVE_REQUIREMENT_LOCAL(send);
};

reviewRequirement = async function reviewRequirementV4Reliable(status){
  if(window.__MUSICA_ONLINE__&&(!database.settings?.serverUrl||navigator.onLine===false)){window.MusicaOnline?.lockConnection();return toast('Reconecta con el servidor para revisar. La decisión todavía no se ha enviado.');}
  const reviewer=currentUser(),aspirant=userById(modalOwnerId),programId=v3ModalProgramId,reqId=modalRequirementId,reviewEpoch=Number(window.__sgl555NavigationEpoch||0);
  const currentStatus=v3EnsureProgramProgress(modalOwnerId,programId).status[reqId];
  if(!v3CanReviewRequirement(reviewer,aspirant,currentStatus))return toast('No tienes permiso para revisar este requisito.');
  const displayed=window.sgl595DisplayedReview;
  if(!displayed||displayed.ownerId!==aspirant.id||displayed.programId!==programId||displayed.requirementId!==reqId)return toast('Vuelve a abrir el informe antes de revisarlo.');
  const feedback=status==='needs_changes'?prompt('Indica qué debe corregir el Aspirante:',''):'';
  if(status==='needs_changes'&&!feedback)return;
  const requirement=v3RequirementById(reqId,programId),requirementTitle=requirement?.official_text||reqId;

  // 4.2.13: la decisión se aplica directamente sobre la versión vigente del servidor.
  // No se envía la base completa del Administrador, evitando conflictos que dejaban
  // "Revisado" solo en su pantalla mientras el Aspirante seguía "En revisión".
  if(database.settings.serverUrl&&v3CanAttemptNetwork()){
    try{
      const {payload}=await v3Api('/api/reviews/decision',{method:'POST',timeout:60000,body:{
        actorId:reviewer.id,ownerId:aspirant.id,programId,requirementId:reqId,requirementTitle,
        decision:status,feedback:feedback||'',ackOnly:true,expectedUpdatedAt:displayed.updatedAt,expectedSubmittedAt:displayed.submittedAt
      }});
      // 5.18: el servidor ya confirmo la decision. Reflejar solo este requisito
      // de inmediato evita esperar una descarga completa de la base antes de cerrar.
      const reviewedAt=String(payload?.reviewedAt||isoNow());
      const submission=v3SubmissionFor(aspirant.id,reqId,programId);
      submission.feedback=feedback||'';
      submission.approval=status==='approved'?{reviewerId:reviewer.id,reviewerName:reviewer.fullName,at:reviewedAt}:null;
      submission.updatedAt=reviewedAt;
      const progress=v3EnsureProgramProgress(aspirant.id,programId);
      progress.status[reqId]=status;progress.updatedAt=reviewedAt;database.updatedAt=reviewedAt;
      if(typeof scheduleNativeSnapshot==='function')scheduleNativeSnapshot();
      if(typeof renderTopSync==='function')renderTopSync();
      if(reviewEpoch===Number(window.__sgl555NavigationEpoch||0)&&currentUser()?.id===reviewer.id&&modalOwnerId===aspirant.id&&modalRequirementId===reqId){await closeModal();if(programId==='music_ministry'){activeAspirantId=aspirant.id;go('requirements');}else go('reviews');}
      toast(status==='approved'?`Requisito revisado y sincronizado: ${requirementTitle}`:`Corrección enviada y sincronizada: ${requirementTitle}`);
      try{await kvSet('database',database);}catch{}
      if(typeof v4FetchNotifications==='function')Promise.resolve(v4FetchNotifications(false)).catch(()=>{});
      if(typeof v3PullServerUpdates==='function')setTimeout(()=>v3PullServerUpdates(false).catch(()=>{}),0);
      return;
    }catch(error){
      toast(`No se pudo guardar la decisión en el servidor: ${error.message}. La pantalla no se marcará como revisada hasta sincronizar.`);
      return;
    }
  }

  // Sin servidor configurado se conserva el comportamiento local. Un Tutor que
  // trabaja offline además deja la decisión en la cola automática para enviarla
  // apenas recupere conexión.
  const submission=v3SubmissionFor(modalOwnerId,reqId,programId);
  submission.feedback=feedback||'';
  submission.approval=status==='approved'?{reviewerId:reviewer.id,reviewerName:reviewer.fullName,at:isoNow()}:null;
  submission.updatedAt=isoNow();
  v3EnsureProgramProgress(modalOwnerId,programId).status[reqId]=status;
  await persist(false,{action:status==='approved'?'Requisito revisado':'Corrección solicitada',entity:reqId,detail:`${v3Program(programId).name} · ${aspirant?.fullName||''}`});
  if(reviewer.role==='tutor')await v4QueueRequirementSync('review_decision',reqId,programId,aspirant.id);
  else if(reviewer.role==='admin')toast('Decisión guardada solo en este equipo porque no hay servidor configurado.');
  closeModal();go('reviews');
};

v3ProposalStatusLabel = function v3ProposalStatusLabelV4(status){return({pending:'Pendiente',postponed:'Pospuesta',accepted:'Aceptada',rejected:'Rechazada',correction:'Corrección solicitada',cancelled:'Cancelada por usuario',superseded:'Duplicada consolidada',obsolete:'Solicitud antigua/no aplicable'})[status]||status;};

// Aceptación reintentable: si la versión del servidor cambió mientras se tenía
// abierto el modal, se recalcula el merge una vez contra la versión actual.
v3DecideSyncProposal = async function v3DecideSyncProposalV4(proposalId,decisión){
  const note=value('sync_decisión_note').trim();
  if(['reject','correction'].includes(decisión)&&!note)return toast('Escribe un mensaje para explicar la decisi\u00f3n.');
  try{
    const user=currentUser();
    // 4.2.13 conserva la aceptación compacta introducida en 4.2.5 para solicitudes antiguas.
    // The server resolves the canonical request and applies the same restricted
    // merge there. This is intentionally isolated from the working sync sender.
    const body={actorId:user.id,proposalId,decision:decisión,note};
    const result=await v3Api('/api/proposals/decision',{method:'POST',body,allowStatuses:[409,422],timeout:180000});
    if(result.response.status===422){closeModal();await v3FetchSyncRequests(false);if(currentPage==='sync_requests')renderSyncRequests(true);throw new Error(result.payload?.error||'Solicitud antigua/no aplicable. Fue cerrada sin modificar los datos actuales.');}
    if(result.response.status===409)throw new Error(result.payload?.error||'La solicitud ya cambi\u00f3 de estado. Actualiza la bandeja.');
    const payload=result.payload;
    closeModal();
    if(decisión==='accept'&&payload?.database){
      await v3ApplyServerSnapshot(payload,{type:'accepted',title:'Solicitud aceptada',message:'Los cambios autorizados fueron aplicados por el servidor.',proposalId:payload.proposalId||proposalId});
    }
    await v3FetchSyncRequests(false);
    if(currentPage==='sync_requests')renderSyncRequests(true);
    toast(({accept:'Cambios aceptados y aplicados.',reject:'Solicitud rechazada.',correction:'Correcci\u00f3n solicitada.',postpone:'Solicitud pospuesta.'})[decisión]||'Decisi\u00f3n guardada.');
  }catch(error){
    const detail=error?.name==='AbortError'?'El servidor no respondi\u00f3 a tiempo. Verifica la conexi\u00f3n y vuelve a intentar.':(error?.message||String(error));
    toast(`No se pudo guardar la decisi\u00f3n: ${detail}`);
  }
};

/* Mensajería ligera: NO modifica la base de sincronización ni crea solicitudes. */
function v4UpdateMessagePill(){const pill=document.getElementById('message_pill'),badge=document.getElementById('message_badge');if(!pill)return;if(badge){badge.textContent=String(v4UnreadMessages);badge.hidden=v4UnreadMessages<1;}pill.classList.toggle('has-unread',v4UnreadMessages>0);pill.title=v4UnreadMessages?`${v4UnreadMessages} mensaje(s) sin leer`:'Mensajes';}
function v4InstallMessagePill(){const top=document.querySelector('.topbar'),sync=document.getElementById('sync_pill');if(!top||!sync||document.getElementById('message_pill'))return;sync.insertAdjacentHTML('beforebegin',`<button id="message_pill" class="message-pill" onclick="v4ShowMessages()" title="Mensajes"><span>💬</span><span class="message-label">Mensajes</span><b id="message_badge" class="message-badge" hidden>0</b></button>`);v4UpdateMessagePill();}
function v4PlayMessageSound(){try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;const ctx=new Ctx(),gain=ctx.createGain(),osc=ctx.createOscillator();osc.frequency.setValueAtTime(620,ctx.currentTime);osc.frequency.setValueAtTime(820,ctx.currentTime+.10);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.12,ctx.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.28);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.3);setTimeout(()=>ctx.close().catch(()=>{}),400);}catch{}}
async function v4FetchMessages(notify=true){
  const user=currentUser();
  if(!user)return[];
  v4EnsureReliableState();
  const paint=()=>{if(v4ActiveMessagePeerId)setTimeout(()=>v4PaintOpenConversation(v4ActiveMessagePeerId,true),0);};
  if(!database.settings.serverUrl||!v3CanAttemptNetwork()){
    v4Messages=sgl529VisibleMessages(database.messageCache);
    v4UnreadMessages=v4Messages.filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt).length;
    v4UpdateMessagePill();paint();return v4Messages;
  }
  try{
    const query=new URLSearchParams({userId:user.id});
    const {payload}=await v3Api(`/api/messages?${query.toString()}`,{timeout:30000});
    if(String(currentUser()?.id)!==String(user.id))return [];
    const next=sgl529VisibleMessages(payload?.messages,user);
    const knownIds=new Set((database.messageCache||[]).map(m=>m.id));
    const incoming=next.filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt&&!knownIds.has(m.id));
    const serverClientIds=new Set(next.map(m=>m.clientMessageId).filter(Boolean));
    const pending=sgl529VisibleMessages(database.messageCache,user).filter(m=>m.pending&&m.clientMessageId&&!serverClientIds.has(m.clientMessageId)&&(database.messageOutbox||[]).some(x=>x.clientMessageId===m.clientMessageId));
    v4Messages=[...next,...pending].sort((a,b)=>String(a.sentAt||'').localeCompare(String(b.sentAt||'')));
    v4UnreadMessages=v4Messages.filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt).length;
    database.messageCache=[...(database.messageCache||[]).filter(m=>!sgl529MessageRelevant(m,user)),...v4Messages];
    await kvSet('database',database);
    v4UpdateMessagePill();
    paint();
    if(v4MessagesPrimed&&notify&&incoming.length){
      v4PlayMessageSound();
      const m=incoming.at(-1);
      toast(`${m.senderName||'Mensaje'}: ${short(m.text,90)}`);
      if(document.hidden&&'Notification'in window&&Notification.permission==='granted')try{new Notification(m.senderName||'SGL',{body:short(m.text,120),icon:appLogo()});}catch{}
    }
    v4MessagesPrimed=true;
    return v4Messages;
  }catch{
    if(String(currentUser()?.id)!==String(user.id))return [];
    v4Messages=sgl529VisibleMessages(database.messageCache);
    v4UnreadMessages=v4Messages.filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt).length;
    v4UpdateMessagePill();paint();return v4Messages;
  }
}
function v4MessagePeers(){const user=currentUser();if(!user)return[];if(user.role==='admin')return(database.users||[]).filter(u=>['tutor','aspirant','pastor_aspirant'].includes(u.role)&&(u.accountState||'active')==='active');return(database.users||[]).filter(u=>u.role==='admin'&&(u.accountState||'active')==='active');}
function v4MessageRecipients(m){return Array.isArray(m.recipientIds)&&m.recipientIds.length?m.recipientIds:[m.recipientId].filter(Boolean);}
function v4MessageHasRecipient(m,userId){return v4MessageRecipients(m).includes(userId);}
function v4MessagesWith(peerId){const user=currentUser();return sgl529VisibleMessages(v4Messages,user).filter(m=>(m.senderId===user.id&&v4MessageHasRecipient(m,peerId))||(m.senderId===peerId&&v4MessageHasRecipient(m,user.id))).sort((a,b)=>String(a.sentAt||'').localeCompare(String(b.sentAt||'')));}
async function v4MarkConversationRead(peerId){const user=currentUser(),ids=v4MessagesWith(peerId).filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt).map(m=>m.id);if(!ids.length)return;const now=isoNow();for(const m of database.messageCache||[])if(ids.includes(m.id))m.readAt=now;v4Messages=sgl529VisibleMessages(database.messageCache);v4UnreadMessages=v4Messages.filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt).length;v4UpdateMessagePill();await kvSet('database',database);if(database.settings.serverUrl&&v3CanAttemptNetwork())try{await v3Api('/api/messages/read',{method:'POST',body:{userId:user.id,messageIds:ids},timeout:30000});}catch{}}
function v4ThreadHtml(peerId){
  const user=currentUser();
  return v4MessagesWith(peerId).map(m=>`<div class="message-bubble ${m.senderId===user.id?'mine':'theirs'}"><p>${esc(m.text)}</p><small>${formatDateTime(m.sentAt)}${m.pending?' · Pendiente':''}${m.senderId===user.id&&m.readAt?' · Leído':''}</small></div>`).join('')||'<div class="empty">Inicia la conversación.</div>';
}
async function v4PaintOpenConversation(peerId,markRead=false){
  if(v4ActiveMessagePeerId!==peerId)return;
  const root=document.getElementById('message_thread');
  if(!root){v4ActiveMessagePeerId='';return;}
  const nearBottom=root.scrollHeight-root.scrollTop-root.clientHeight<90;
  if(markRead)await v4MarkConversationRead(peerId);
  root.innerHTML=v4ThreadHtml(peerId);
  if(nearBottom||markRead)root.scrollTop=root.scrollHeight;
}
function v4ShowMessages(peerId=''){
  const user=currentUser();if(!user)return;
  v4EnsureReliableState();v4Messages=sgl529VisibleMessages(database.messageCache||v4Messages);
  if(peerId)return v4RenderConversation(peerId);
  v4ActiveMessagePeerId='';
  const peers=v4MessagePeers();
  showModal(`<div class="modal message-modal"><div class="modal-head"><div><h3>Mensajes</h3><p>Conversaciones de SGL. Abre de inmediato y actualiza en segundo plano.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="message-peer-list">${peers.map(peer=>{const conv=v4MessagesWith(peer.id),last=conv.at(-1),unread=conv.filter(m=>v4MessageHasRecipient(m,user.id)&&!m.readAt).length,online=v3ConnectedUsers.some(item=>item.userId===peer.id);return`<button class="message-peer" onclick="v4RenderConversation('${peer.id}')"><span class="online-avatar">${esc(initials(peer.fullName))}${online?'<i></i>':''}</span><span><b>${esc(peer.fullName)}</b><small>${esc(ROLE_LABELS[peer.role]||peer.role)}${last?` · ${esc(short(last.text,55))}`:''}</small></span>${unread?`<b class="message-badge">${unread}</b>`:''}</button>`;}).join('')||'<div class="empty">No hay destinatarios disponibles.</div>'}</div></div><div class="modal-foot"><button class="btn ghost" onclick="v4FetchMessages(false).then(()=>v4ShowMessages())">Actualizar</button><button class="btn primary" onclick="closeModal()">Cerrar</button></div></div>`);
  v4FetchMessages(false).catch(()=>{});
}
function v4DesktopMessageKeysEnabled(){
  try{return window.innerWidth>820&&window.matchMedia('(pointer:fine)').matches;}catch{return window.innerWidth>820;}
}
function v4MessageKeyDown(event){
  if(event.key!=='Enter'||event.shiftKey||event.isComposing||!v4DesktopMessageKeysEnabled())return;
  event.preventDefault();
  const form=event.currentTarget?.closest?.('form');
  if(form?.requestSubmit)form.requestSubmit();else form?.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
}
async function v4RenderConversation(peerId){
  const user=currentUser(),peer=userById(peerId);if(!peer)return;
  v4ActiveMessagePeerId=peerId;
  const keyHint=v4DesktopMessageKeysEnabled()?'<small class="message-key-hint">Enter envía · Shift+Enter agrega una línea</small>':'';
  showModal(`<div class="modal message-modal"><div class="modal-head"><div><h3>${esc(peer.fullName)}</h3><p>${esc(ROLE_LABELS[peer.role]||peer.role)} · ${v3ConnectedUsers.some(item=>item.userId===peer.id)?'En línea':'Recibirá el mensaje al conectarse'}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body message-thread" id="message_thread">${v4ThreadHtml(peerId)}</div><form class="message-compose" onsubmit="v4SendMessage(event,'${peer.id}')"><textarea id="message_text" class="field" maxlength="2000" placeholder="Escribe un mensaje…" onkeydown="v4MessageKeyDown(event)" required></textarea><button class="btn primary">Enviar</button>${keyHint}</form><div class="notice"><b>Sin conexión:</b> el mensaje queda guardado en este dispositivo y se envía automáticamente al recuperar conexión.</div></div><div class="modal-foot"><button class="btn ghost" onclick="v4ShowMessages()">Volver</button><button class="btn primary" onclick="closeModal()">Cerrar</button></div></div>`);
  setTimeout(()=>{const root=document.getElementById('message_thread');if(root)root.scrollTop=root.scrollHeight;},20);
  v4MarkConversationRead(peerId).catch(()=>{});v4FetchMessages(false).catch(()=>{});
}
async function v4SendMessage(event,peerId){
  event.preventDefault();const user=currentUser(),text=value('message_text').trim();if(!text)return;
  v4EnsureReliableState();
  const clientMessageId=`MSG-${user.id}-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,local={id:`local_${clientMessageId}`,clientMessageId,senderId:user.id,senderName:user.fullName,senderRole:user.role,recipientId:peerId,recipientName:userById(peerId)?.fullName||'',text,sentAt:isoNow(),readAt:'',pending:true};
  database.messageCache.push(local);database.messageOutbox.push({senderId:user.id,clientMessageId,recipientId:peerId,text,createdAt:local.sentAt});
  await kvSet('database',database);v4Messages=sgl529VisibleMessages(database.messageCache);
  const input=document.getElementById('message_text');if(input)input.value='';
  await v4PaintOpenConversation(peerId,false);
  await v4FlushMessageOutbox();
  await v4PaintOpenConversation(peerId,false);
}
async function v4FlushMessageOutbox(){
  const user=currentUser();if(!user||!database?.settings?.serverUrl||!v3CanAttemptNetwork())return false;
  v4EnsureReliableState();
  for(const item of [...database.messageOutbox]){
    if(String(currentUser()?.id)!==String(user.id))return false;
    const sender=item.senderId||(database.messageCache||[]).find(m=>m.clientMessageId===item.clientMessageId)?.senderId;
    if(String(sender||'')!==String(user.id))continue;
    try{
      const {payload}=await v3Api('/api/messages/send',{method:'POST',body:{senderId:user.id,recipientId:item.recipientId,recipientIds:item.recipientIds||undefined,conversationId:item.conversationId||'',text:item.text,clientMessageId:item.clientMessageId},timeout:30000});
      if(String(currentUser()?.id)!==String(user.id))return false;
      database.messageOutbox=database.messageOutbox.filter(x=>x.clientMessageId!==item.clientMessageId);
      database.messageCache=database.messageCache.filter(x=>x.clientMessageId!==item.clientMessageId);
      if(payload?.message)database.messageCache.push(payload.message);
    }catch{return false;}
  }
  database.messageCache.sort((a,b)=>String(a.sentAt||'').localeCompare(String(b.sentAt||'')));
  await kvSet('database',database);v4Messages=sgl529VisibleMessages(database.messageCache);
  if(v4ActiveMessagePeerId)await v4PaintOpenConversation(v4ActiveMessagePeerId,false);
  return true;
}
window.v4ShowMessages=v4ShowMessages;window.v4RenderConversation=v4RenderConversation;window.v4SendMessage=v4SendMessage;window.v4MessageKeyDown=v4MessageKeyDown;
function v4220ConversationIdFor(ids){const sorted=[...new Set(ids.filter(Boolean))].sort();return `conv_${sorted.join('_')}`;}
function v4220MessagesWithGroup(participantIds){const user=currentUser(),ids=[...new Set([user?.id,...participantIds].filter(Boolean))],conv=v4220ConversationIdFor(ids);return sgl529VisibleMessages(v4Messages,user).filter(m=>m.conversationId===conv||(ids.includes(m.senderId)&&v4MessageRecipients(m).some(id=>ids.includes(id))&&ids.every(id=>id===m.senderId||v4MessageRecipients(m).includes(id)||m.senderId===id))).sort((a,b)=>String(a.sentAt||'').localeCompare(String(b.sentAt||'')));}
function v4220GroupThreadHtml(participantIds){const user=currentUser();return v4220MessagesWithGroup(participantIds).map(m=>`<div class="message-bubble ${m.senderId===user.id?'mine':'theirs'}"><p>${esc(m.text)}</p><small>${esc(m.senderName||'')} · ${formatDateTime(m.sentAt)}${m.pending?' · Pendiente':''}</small></div>`).join('')||'<div class="empty">Inicia la conversación grupal.</div>';}
function v4220RenderGroupConversation(ids){
  const user=currentUser();ids=[...new Set(ids.filter(id=>id&&id!==user.id))].slice(0,4);if(ids.length<1)return toast('Selecciona al menos un participante.');if(ids.length+1>5)return toast('El chat grupal permite máximo 5 personas.');
  const names=ids.map(id=>userById(id)?.fullName||id);const convId=v4220ConversationIdFor([user.id,...ids]);v4ActiveMessagePeerId=convId;
  showModal(`<div class="modal message-modal"><div class="modal-head"><div><h3>Chat grupal</h3><p>${esc(names.join(' · '))} · máximo 5 participantes</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body message-thread" id="message_thread">${v4220GroupThreadHtml(ids)}</div><form class="message-compose" onsubmit="v4220SendGroupMessage(event,'${ids.join(',')}')"><textarea id="message_text" class="field" maxlength="2000" placeholder="Escribe un mensaje para el grupo…" onkeydown="v4MessageKeyDown(event)" required></textarea><button class="btn primary">Enviar</button></form><div class="notice"><b>Grupo:</b> Admin o Tutor pueden sumar conectados. La conversación admite de 3 a 5 personas cuando se agregan varios participantes.</div></div><div class="modal-foot"><button class="btn ghost" onclick="v4ShowMessages()">Volver</button><button class="btn primary" onclick="closeModal()">Cerrar</button></div></div>`);
  setTimeout(()=>{const root=document.getElementById('message_thread');if(root)root.scrollTop=root.scrollHeight;},20);
}
async function v4220SendGroupMessage(event,idsCsv){event.preventDefault();const user=currentUser(),text=value('message_text').trim();if(!text)return;const ids=[...new Set(String(idsCsv).split(',').filter(Boolean))].slice(0,4),clientMessageId=`MSG-${user.id}-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,convId=v4220ConversationIdFor([user.id,...ids]),local={id:`local_${clientMessageId}`,clientMessageId,senderId:user.id,senderName:user.fullName,senderRole:user.role,recipientId:ids[0],recipientIds:ids,recipientNames:ids.map(id=>userById(id)?.fullName||id),conversationId:convId,text,sentAt:isoNow(),readAt:'',pending:true};v4EnsureReliableState();database.messageCache.push(local);database.messageOutbox.push({senderId:user.id,clientMessageId,recipientId:ids[0],recipientIds:ids,conversationId:convId,text,createdAt:local.sentAt});await kvSet('database',database);v4Messages=sgl529VisibleMessages(database.messageCache);const input=document.getElementById('message_text');if(input)input.value='';document.getElementById('message_thread').innerHTML=v4220GroupThreadHtml(ids);await v4FlushMessageOutbox();document.getElementById('message_thread').innerHTML=v4220GroupThreadHtml(ids);}
function v4220StartConnectedGroupChat(userId){const admin=(database.users||[]).find(u=>u.role==='admin'&&(u.accountState||'active')==='active');const current=currentUser();const ids=[userId];if(admin&&admin.id!==current.id&&!ids.includes(admin.id))ids.push(admin.id);return v4220RenderGroupConversation(ids);}
window.v4220RenderGroupConversation=v4220RenderGroupConversation;window.v4220SendGroupMessage=v4220SendGroupMessage;window.v4220StartConnectedGroupChat=v4220StartConnectedGroupChat;


/* Avisos del servidor: aprobaciones, correcciones y nuevos requisitos a revisar. */
function v4UpdateNotificationPill(){
  const pill=document.getElementById('notification_pill'),badge=document.getElementById('notification_badge');
  if(!pill)return;
  if(badge){badge.textContent=String(v4UnreadNotifications);badge.hidden=v4UnreadNotifications<1;}
  pill.classList.toggle('has-unread',v4UnreadNotifications>0);
  pill.title=v4UnreadNotifications?`${v4UnreadNotifications} aviso(s) sin leer`:'Avisos';
}
function v4InstallNotificationPill(){
  const sync=document.getElementById('sync_pill');
  if(!sync||document.getElementById('notification_pill'))return;
  sync.insertAdjacentHTML('beforebegin',`<button id="notification_pill" class="message-pill notification-pill" onclick="v4ShowNotifications()" title="Avisos"><span>🔔</span><span class="notification-label">Avisos</span><b id="notification_badge" class="message-badge" hidden>0</b></button>`);
  v4UpdateNotificationPill();
}
function v4MergeServerNotifications(items){
  database.syncNotifications=Array.isArray(database.syncNotifications)?database.syncNotifications:[];
  const incoming=Array.isArray(items)?items:[];
  const prior=new Map(database.syncNotifications.map(item=>[item.id,item]));
  const next=new Map();
  for(const remote of incoming){
    if(remote?.deletedAt||window.sgl512DeletedNotificationIds?.has?.(String(remote?.id||'')))continue;
    const previous=prior.get(remote.id)||{};
    next.set(remote.id,{
      ...previous,id:remote.id,userId:remote.userId||'',recipientId:remote.recipientId||'',type:remote.type||'info',title:remote.title||'Aviso',message:remote.message||'',
      requirementId:remote.requirementId||'',requirementTitle:remote.requirementTitle||'',programId:remote.programId||'',
      ownerId:remote.ownerId||previous.ownerId||'',actorId:remote.actorId||'',actorName:remote.actorName||'',
      feedback:remote.feedback??previous.feedback??'',reviewedAt:remote.reviewedAt||previous.reviewedAt||remote.createdAt||previous.createdAt||'',
      serverVersion:Number(remote.serverVersion||previous.serverVersion||0),createdAt:remote.createdAt||previous.createdAt||isoNow(),
      read:!!remote.readAt,readAt:remote.readAt||'',server:true
    });
  }
  for(const local of prior.values()){
    if(!local.server&&!next.has(local.id))next.set(local.id,local);
  }
  database.syncNotifications=[...next.values()].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,120);
}
async function v4FetchNotifications(notify=true,showLogin=false){
  const user=currentUser();if(!user)return[];
  database.syncNotifications=(Array.isArray(database.syncNotifications)?database.syncNotifications:[]).filter(item=>sgl529NoticeRelevant(item,user)&&(['aspirant','pastor_aspirant'].includes(user.role)||item.type!=='review_submitted'||window.sgl518NoticeWasHydrated?.(item)));
  if(!database.settings.serverUrl||!v3CanAttemptNetwork()){
    v4UnreadNotifications=database.syncNotifications.filter(item=>!item.read).length;
    v4UpdateNotificationPill();
    if(showLogin&&v4UnreadNotifications>0&&!v4NotificationLoginShown){
      v4NotificationLoginShown=true;
      setTimeout(()=>{if(!document.querySelector('.modal-bg'))v4ShowNotifications(true);},120);
    }
    return database.syncNotifications;
  }
  try{
    const known=new Set(database.syncNotifications.map(item=>item.id));
    const query=new URLSearchParams({userId:user.id});
    const {payload}=await v3Api(`/api/notifications?${query.toString()}`,{timeout:30000});
    if(String(currentUser()?.id)!==String(user.id))return [];
    let incoming=(Array.isArray(payload?.notifications)?payload.notifications:[]).filter(item=>sgl529NoticeRelevant(item,user));
    if(!['aspirant','pastor_aspirant'].includes(user.role)&&window.sgl538ReadyNotices)incoming=await window.sgl538ReadyNotices(user,incoming);
    if(String(currentUser()?.id)!==String(user.id))return [];
    const fresh=incoming.filter(item=>!item.readAt&&!item.deletedAt&&!known.has(item.id)&&!window.sgl512SuppressedNotificationIds?.has?.(String(item.id))&&(typeof sgl514RecognitionNoticeActive!=='function'||sgl514RecognitionNoticeActive(item)));
    v4MergeServerNotifications(incoming);
    v4UnreadNotifications=database.syncNotifications.filter(item=>!item.read).length;
    await kvSet('database',database);
    v4UpdateNotificationPill();
    if(document.querySelector('.notification-modal'))v4ShowNotifications(false);
    if(notify&&fresh.length){
      v4PlayMessageSound();
      const latest=fresh[0];
      toast(`${latest.title||'Aviso'}: ${short(latest.message||'',110)}`);
    }
    if(showLogin&&v4UnreadNotifications>0&&!v4NotificationLoginShown){
      v4NotificationLoginShown=true;
      setTimeout(()=>{if(!document.querySelector('.modal-bg'))v4ShowNotifications(true);},120);
    }
    if(fresh.length&&currentPage==='dashboard'&&!document.querySelector('.modal-bg'))renderDashboard();
    return database.syncNotifications;
  }catch{
    if(String(currentUser()?.id)!==String(user.id))return [];
    v4UnreadNotifications=database.syncNotifications.filter(item=>!item.read).length;
    v4UpdateNotificationPill();
    if(showLogin&&v4UnreadNotifications>0&&!v4NotificationLoginShown){
      v4NotificationLoginShown=true;
      setTimeout(()=>{if(!document.querySelector('.modal-bg'))v4ShowNotifications(true);},120);
    }
    return database.syncNotifications;
  }
}
async function v4MarkNotificationRead(id){
  const user=currentUser(),item=(database.syncNotifications||[]).find(entry=>entry.id===id);
  if(!item)return;
  item.read=true;item.readAt=item.readAt||isoNow();v4UnreadNotifications=(database.syncNotifications||[]).filter(entry=>!entry.read).length;
  await kvSet('database',database);v4UpdateNotificationPill();
  if(item.server&&database.settings.serverUrl&&v3CanAttemptNetwork())try{await v3Api('/api/notifications/read',{method:'POST',body:{userId:user.id,notificationIds:[id]},timeout:30000});await v4FetchNotifications(false,false);}catch{}
  if(document.querySelector('.notification-modal'))v4ShowNotifications(false);
  if(currentPage==='dashboard')renderDashboard();
}
async function v4MarkAllNotificationsRead(){
  const user=currentUser(),items=(database.syncNotifications||[]).filter(item=>!item.read);
  if(!items.length)return;
  const now=isoNow();
  for(const item of items){item.read=true;item.readAt=item.readAt||now;}
  v4UnreadNotifications=0;await kvSet('database',database);v4UpdateNotificationPill();
  if(database.settings.serverUrl&&v3CanAttemptNetwork())try{await v3Api('/api/notifications/read',{method:'POST',body:{userId:user.id,notificationIds:[]},timeout:30000});await v4FetchNotifications(false,false);}catch{}
  v4ShowNotifications(false);
}
function v4NotificationKind(item){
  if(item.type==='approved')return 'Revisado';
  if(item.type==='needs_changes')return 'Corrección';
  if(item.type==='review_submitted')return 'Revisión';
  if(item.type==='drive_reopened')return 'En desarrollo';
  return 'Aviso';
}
function v4ShowNotifications(fromLogin=false){
  const items=(database.syncNotifications||[]).slice(0,40),unread=items.filter(item=>!item.read).length;
  showModal(`<div class="modal message-modal notification-modal"><div class="modal-head"><div><h3>${fromLogin?'Tienes avisos pendientes':'Avisos'}</h3><p>${unread?`${unread} sin leer · las aprobaciones indican el requisito exacto.`:'No hay avisos pendientes.'}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="notification-list">${items.map(item=>`<article class="notification-item ${item.read?'':'unread'}"><div class="notification-icon">${item.type==='approved'?'✓':item.type==='needs_changes'?'!':item.type==='review_submitted'?'↗':'•'}</div><div><div class="chips"><span class="status ${item.type==='approved'?'approved':item.type==='needs_changes'?'needs_changes':'in_review'}">${esc(v4NotificationKind(item))}</span>${item.requirementId?`<span class="chip">${esc(item.requirementId)}</span>`:''}</div><h4>${esc(item.title||'Aviso')}</h4><p>${esc(item.message||'')}</p><small>${formatDateTime(item.createdAt)}</small></div>${item.read?'':`<button class="btn ghost small" onclick="v4MarkNotificationRead('${item.id}').then(()=>v4ShowNotifications(false))">Leído</button>`}</article>`).join('')||'<div class="empty">No hay avisos.</div>'}</div></div><div class="modal-foot">${unread?'<button class="btn ghost" onclick="v4MarkAllNotificationsRead()">Marcar todos como leídos</button>':''}<button class="btn primary" onclick="closeModal()">Cerrar</button></div></div>`);
}
markSyncNotificationRead=v4MarkNotificationRead;
window.v4FetchNotifications=v4FetchNotifications;window.v4ShowNotifications=v4ShowNotifications;window.v4MarkNotificationRead=v4MarkNotificationRead;window.v4MarkAllNotificationsRead=v4MarkAllNotificationsRead;

