v3ShowConnectedUsers = function v3ShowConnectedUsersV4(){const items=v3ConnectedUsers||[];showModal(`<div class="modal small"><div class="modal-head"><div><h3>Usuarios conectados</h3><p>Actividad remota detectada en los últimos segundos.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="list compact-list">${items.map(item=>`<div class="list-item"><div class="online-avatar">${esc(initials(item.fullName||'?'))}<i></i></div><div><h4>${esc(item.fullName||'Usuario')}</h4><p>${esc(ROLE_LABELS[item.role]||item.role)} · conectado ahora</p></div><div class="actions"><span class="status approved">En línea</span><button class="btn primary small" onclick="v4RenderConversation('${item.userId}')">Mensaje</button></div></div>`).join('')||'<div class="empty">No hay Tutores o Aspirantes conectados ahora.</div>'}</div></div><div class="modal-foot"><button class="btn ghost" onclick="v3FetchPresence(false).then(v3ShowConnectedUsers)">Actualizar</button><button class="btn primary" onclick="closeModal()">Cerrar</button></div></div>`);};

function v4FocusAssistCurrentModal(){if(window.innerWidth>900)return;const root=document.querySelector('.modal-bg');if(!root)return;root.addEventListener('focusin',event=>{const el=event.target;if(!el?.matches?.('input,textarea,[contenteditable="true"],select'))return;if(typeof closeMobileMenu==='function')closeMobileMenu();if(el.closest?.('#req_text'))return;setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'center',inline:'nearest'}),180);},{once:false});}
function v4InstallInputAssist(){if(v4InputAssistInstalled)return;v4InputAssistInstalled=true;const update=()=>{const vv=window.visualViewport;document.documentElement.style.setProperty('--sgl-visible-height',`${Math.round(vv?.height||window.innerHeight)}px`);};update();window.visualViewport?.addEventListener('resize',update);window.visualViewport?.addEventListener('scroll',update);document.addEventListener('focusin',event=>{if(window.innerWidth>900)return;const el=event.target;if(!el?.matches?.('input,textarea,[contenteditable="true"],select'))return;if(typeof closeMobileMenu==='function')closeMobileMenu();if(el.closest?.('#req_text'))return;setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'center',inline:'nearest'}),160);});}


function v4InstallFloatingSync(){
  if(document.getElementById('floating_sync'))return;
  const refresh=document.querySelector('.floating-refresh');
  const button=document.createElement('button');button.id='floating_sync';button.className='floating-sync';button.type='button';button.textContent='⇄';button.title='Sincronizar y refrescar datos de todos los dispositivos';button.setAttribute('aria-label','Sincronizar y refrescar datos de todos los dispositivos');button.onclick=()=>v4ForceSyncAll();
  (refresh?.parentNode||document.body).insertBefore(button,refresh||null);
}
async function v4BackgroundSyncTick(){
  const user=currentUser();if(!user||!database?.settings?.serverUrl||!v3CanAttemptNetwork())return;
  if(user.role==='admin'&&database.sync?.needsUpload)return syncNow();
  if(database.syncQueue?.some(item=>['queued','retry'].includes(item.status)))return syncNow();
  if(database.sync?.pendingProposal?.id)return v3CheckProposalStatus(false);
  return v3PullServerUpdates(false);
}
async function v4ForceSyncAll(){
  const button=document.getElementById('floating_sync');if(button?.classList.contains('working'))return;
  button?.classList.add('working');
  try{
    if(!currentUser())return;
    if(!database?.settings?.serverUrl)return toast('Este equipo todavía no tiene servidor configurado.');
    if(!v3CanAttemptNetwork())return toast('Sin conexión. Los cambios permanecen guardados y se enviarán al recuperar internet.');
    let rounds=0;
    if(currentUser()?.role==='admin'&&database.sync?.needsUpload)await syncNow();
    while(database.syncQueue?.some(item=>['queued','retry'].includes(item.status))&&rounds<30){rounds++;await syncNow();if(database.sync?.state==='pending'&&database.syncQueue?.some(item=>item.lastError))break;}
    await v3PullServerUpdates(false).catch(()=>{});
    toast(database.syncQueue?.some(item=>['queued','retry','sending'].includes(item.status))?'Quedan cambios pendientes. SGL seguirá reintentando automáticamente.':'Sincronización completa con el servidor.');
  }finally{button?.classList.remove('working');}
}
window.v4ForceSyncAll=v4ForceSyncAll;
renderShell = function renderShellV4Reliable(){
  V4R_BASE_RENDER_SHELL();v4EnsureReliableState();v4InstallMessagePill();v4InstallNotificationPill();v4InstallInputAssist();v4InstallFloatingSync();
  const user=currentUser();
  if(user&&v4NotificationSessionUserId!==user.id){v4NotificationSessionUserId=user.id;v4NotificationLoginShown=false;setTimeout(()=>v4FetchNotifications(false,true),650);}
  clearInterval(v4MessagePollTimer);clearInterval(v4SyncPollTimer);
  setTimeout(()=>{v4FlushMessageOutbox();v4FetchMessages(false);v4FetchNotifications(false);v4BackgroundSyncTick();},350);
  v4MessagePollTimer=setInterval(()=>{v4FetchMessages(true);v4FetchNotifications(true);},2500);
  v4SyncPollTimer=setInterval(()=>{v4BackgroundSyncTick().catch(()=>{});},3000);
};

