function v4NextLoginMessage(){
  if(window.SGL_INSPIRATION?.pick)return window.SGL_INSPIRATION.pick('login-v4');
  let lastSource='',lastIndex=-1;
  try{lastSource=localStorage.getItem('sgl_last_login_source')||'';lastIndex=Number(localStorage.getItem('sgl_last_login_message')||-1);}catch{}
  const source=lastSource==='bible'?'egw':'bible';
  let pool=V4_LOGIN_MESSAGES.filter(item=>source==='bible'?item.source.startsWith('Biblia'):item.source.startsWith('Elena G. de White'));
  if(new Date().getDay()===6){const sab=pool.filter(item=>item.sabbath);if(sab.length)pool=sab;}
  if(!pool.length)pool=V4_LOGIN_MESSAGES;
  let item=pool[Math.floor(Math.random()*pool.length)],index=V4_LOGIN_MESSAGES.indexOf(item);
  for(let n=0;n<10&&pool.length>1&&index===lastIndex;n++){item=pool[Math.floor(Math.random()*pool.length)];index=V4_LOGIN_MESSAGES.indexOf(item);}
  try{localStorage.setItem('sgl_last_login_source',source);localStorage.setItem('sgl_last_login_message',String(index));}catch{}
  return item;
}
leadershipAuthHero = function leadershipAuthHeroV4(subtitle='Sistema de Gestión de Música'){const item=v4NextLoginMessage(),books=item?.url?`<a class="sgl5065-inspiration-link" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Libros de Elena G. de White ↗</a>`:'',source=typeof sgl5066DisplaySource==='function'?sgl5066DisplaySource(item):String(item?.source||'');return`<div class="auth-hero"><div class="brand"><img src="${appLogo()}"><div><strong>Sistema de Gestión de Música</strong><small>${esc(subtitle)}</small></div></div><h1>Liderar es servir, orar y dar ejemplo.</h1><div class="leadership-verses"><p class="leadership-verse login-rotating-message">“${esc(item.text)}” <strong>${esc(source)}</strong>${books}</p></div></div>`;};

/* ──────────────────────────────────────────────────────────────────────────
   SGL 4.2.13 · cola atomica sin saltos + sincronizacion inmediata
   Cada cambio queda congelado en la cola en el instante exacto en que ocurre.
   Esto evita que tres checks rapidos terminen enviando solo el primero/ultimo.
   ────────────────────────────────────────────────────────────────────────── */
const V4212_BASE_RENDER_SHELL = renderShell;
const V4212_BASE_PULL_SERVER_UPDATES = v3PullServerUpdates;
const V4212_BASE_SAVE_REQUIREMENT = saveRequirement;
let v4212DrainPromise = null;

function v4212Clone(value){ return value == null ? value : structuredClone(value); }

function v4212IntentFromAudit(auditEvent, auditRecord){
  const actor=currentUser(), action=String(auditEvent?.action||auditRecord?.action||''), entityId=String(auditEvent?.entity||auditRecord?.entity||'');
  const explicitProgramId=String(auditEvent?.programId||auditRecord?.programId||''), explicitOwnerId=String(auditEvent?.ownerId||auditRecord?.ownerId||'');
  const programId=explicitProgramId||(typeof v3ModalProgramId==='string'&&v3ModalProgramId)||'class_grouped';
  const ownerId=explicitOwnerId||(typeof modalOwnerId==='string'&&modalOwnerId)||actor?.id||'';
  if(action==='Requisito enviado') return {action:'review',requirementId:entityId,programId,ownerId,entityId};
  if(['Informe enviado a Drive','PDF revisado enviado a Drive'].includes(action)&&entityId&&ownerId&&programId) return {action:'drive_finalize',requirementId:entityId,programId,ownerId,entityId};
  if(action==='Documento eliminado de Drive y requisito reabierto'&&entityId&&ownerId&&programId) return {action:'drive_reopen',requirementId:entityId,programId,ownerId,entityId};
  if(['Avance guardado','Archivos adjuntados','Formato de informe actualizado','Requisito configurado','Documento de requisito guardado'].includes(action)) return {action:(action==='Avance guardado'||action==='Documento de requisito guardado')?'save_progress':'auto_sync',requirementId:entityId,programId,ownerId,entityId};
  return {action:'auto_sync',requirementId:'',programId:'',ownerId:actor?.id||'',entityId};
}

function v4212PatchForIntent(intent,auditRecord){
  const actor=currentUser(), patch={};
  if(auditRecord) patch.audit=[v4212Clone(auditRecord)];
  if(intent.requirementId){
    const programId=intent.programId||'class_grouped', ownerId=intent.ownerId||actor?.id||'';
    const progress=v3EnsureProgramProgress(ownerId,programId), submission=v3SubmissionFor(ownerId,intent.requirementId,programId);
    const delta={status:{[intent.requirementId]:progress.status?.[intent.requirementId]||'pending'},submissions:{[intent.requirementId]:v4212Clone(submission)},updatedAt:progress.updatedAt||database.updatedAt||isoNow()};
    if(programId==='class_grouped') patch.progress={[ownerId]:delta};
    else patch.programProgress={[ownerId]:{[programId]:delta}};
    const configs={};
    for(const [key,value] of Object.entries(database.configs||{})){
      if((key===ownerId||key.includes(`:${ownerId}:`)||key.startsWith(`${ownerId}:`))&&(key.endsWith(`:${intent.requirementId}`)||key===`${ownerId}:${intent.requirementId}`)) configs[key]=v4212Clone(value);
    }
    if(Object.keys(configs).length) patch.configs=configs;
    const changedTasks=(database.tasks||[]).filter(item=>item.assigneeId===ownerId&&(item.programId||'class_grouped')===programId&&item.requirementId===intent.requirementId);
    if(changedTasks.length) patch.tasks=changedTasks.map(v4212Clone);
    return patch;
  }
  const entityId=String(intent.entityId||''), cls=(database.classes||[]).find(item=>item.id===entityId);
  if(cls){
    const work=classWork(cls), action=String(auditRecord?.action||''), detail=String(auditRecord?.detail||'');
    let classDelta={id:cls.id};
    if(action==='Avance de Conquistador actualizado'){
      const [memberId,reqId,state]=detail.split(':');
      classDelta.work={tracking:{[`${memberId}:${reqId}`]:state||work.tracking?.[`${memberId}:${reqId}`]||'pending'}};
    }else if(action==='Planificación de clase actualizada'){
      const cut=detail.lastIndexOf(':'), reqId=cut>=0?detail.slice(0,cut):detail, field=cut>=0?detail.slice(cut+1):'';
      const plan=work.planning?.[reqId]||{};
      classDelta.work={planning:{[reqId]:field?{[field]:v4212Clone(plan[field])}:v4212Clone(plan)}};
    }else if(action==='Asistencia registrada'){
      const rec=(work.attendance||[]).find(item=>item.date===detail);
      classDelta=rec?{id:cls.id,work:{attendance:[v4212Clone(rec)]}}:{id:cls.id,work:v4212Clone(work)};
    }else if(/Miembro de clase|Foto de Conquistador/.test(action)){
      const member=(work.members||[]).find(item=>item.fullName===detail||item.name===detail);
      classDelta=member?{id:cls.id,work:{members:[v4212Clone(member)]}}:{id:cls.id,work:v4212Clone(work)};
    }else{
      classDelta={id:cls.id,work:v4212Clone(work)};
    }
    patch.classes=[classDelta];
    return patch;
  }
  const person=(database.users||[]).find(item=>item.id===entityId);
  if(person){
    patch.users=[v4212Clone(person)];
    if(database.progress?.[entityId]) patch.progress={[entityId]:v4212Clone(database.progress[entityId])};
    if(database.programProgress?.[entityId]) patch.programProgress={[entityId]:v4212Clone(database.programProgress[entityId])};
    if(database.bibleYear?.[entityId]) patch.bibleYear={[entityId]:v4212Clone(database.bibleYear[entityId])};
    return patch;
  }
  const task=(database.tasks||[]).find(item=>item.id===entityId); if(task){patch.tasks=[v4212Clone(task)];return patch;}
  const material=(database.materials||[]).find(item=>item.id===entityId); if(material){patch.materials=[v4212Clone(material)];return patch;}
  const rule=(database.indicationRules||[]).find(item=>item.id===entityId||item.requirementId===entityId); if(rule){patch.indicationRules=[v4212Clone(rule)];return patch;}
  if(actor&&database.bibleYear?.[actor.id]&&(entityId.includes(':')||/Año bíblico|Lectura bíblica|Informe bíblico/i.test(String(auditRecord?.action||'')))) patch.bibleYear={[actor.id]:v4212Clone(database.bibleYear[actor.id])};
  if(actor&&!Object.keys(patch).some(key=>key!=='audit')) patch.users=[v4212Clone(actor)];
  return patch;
}

function v4212PrepareOperation(auditEvent,auditRecord){
  const actor=currentUser(); if(!actor||actor.role==='admin') return null;
  const intent=v4212IntentFromAudit(auditEvent,auditRecord), patch=v4212PatchForIntent(intent,auditRecord);
  const fileIds=[];
  if(intent.requirementId){
    const submission=v3SubmissionFor(intent.ownerId||actor.id,intent.requirementId,intent.programId||'class_grouped');
    fileIds.push(...(submission.attachmentIds||[]));
  }else if(intent.entityId){
    const material=(database.materials||[]).find(item=>item.id===intent.entityId); if(material?.fileId)fileIds.push(material.fileId);
  }
  if(intent.action==='drive_finalize'){const p=intent.programId||'class_grouped',sub=v3SubmissionFor(intent.ownerId||actor.id,intent.requirementId,p),d=sub.drive;if(!d||!['sent','verified'].includes(d.status)||!String(d.fileId||'').trim())throw new Error('El recibo de Drive todavía no está completo. Se conserva el informe.');}
  const frozen={actorId:actor.id,ownerId:intent.ownerId||actor.id,programId:intent.programId||'',requirementId:intent.requirementId||'',requirementTitle:intent.requirementId?(v3RequirementById(intent.requirementId,intent.programId||'class_grouped')?.official_text||intent.requirementId):'',entityId:intent.entityId||'',action:intent.action||'auto_sync',patch:v4212Clone(patch),fileIds:[...new Set(fileIds)],revision:Number(database.revision||0),updatedAt:database.updatedAt||isoNow(),auditId:auditRecord?.id||''};
  frozen.contentHash=v4HashString(v4StableStringify({action:frozen.action,ownerId:frozen.ownerId,programId:frozen.programId,requirementId:frozen.requirementId,entityId:frozen.entityId,patch:frozen.patch,fileIds:frozen.fileIds,revision:frozen.revision,auditId:frozen.auditId}));
  frozen.id=v4OperationCode(frozen.action,frozen.ownerId,frozen.requirementId,frozen.programId,frozen.contentHash);
  return frozen;
}

async function v4212EnqueuePrepared(prepared,options={}){
  if(!prepared)return null; v4EnsureReliableState();
  const existing=v4FindOperation(prepared.id); if(existing)return existing;
  sgl545ConsolidatePrepared(prepared);
  const op={...prepared,status:'queued',createdAt:isoNow(),updatedAt:isoNow(),attempts:0,proposalId:null};
  database.syncQueue.push(op);
  database.sync.needsUpload=true;database.sync.state='pending';database.sync.message=`${database.syncQueue.filter(item=>['queued','retry','sending'].includes(item.status)).length} cambio(s) pendiente(s) · enviando…`;database.sync.hasLocalDraft=false;
  if(options.deferWrite)return op;
  await kvSet('database',database);scheduleNativeSnapshot();renderTopSync();v4212UpdateFloatingSyncBadge();
  if(v3CanAttemptNetwork()&&database.settings.serverUrl){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow().catch(()=>{}),1400);}
  return op;
}

// Captura el delta ANTES del primer await. En 4.2.13, una segunda pulsacion podia
// cambiar database.audit mientras el primer guardado esperaba IndexedDB. En 4.2.11
// eso podia hacer que el primer check terminara enviando el estado de uno posterior.
persist = async function persistV4212(markPending=true,auditEvent=null){
  const actor=currentUser();
  if(!actor||actor.role==='admin')return V4R_BASE_PERSIST(markPending,auditEvent);
  v4EnsureReliableState();
  database.updatedAt=isoNow();database.revision=(database.revision||0)+1;
  if(auditEvent)addAudit(auditEvent.action,auditEvent.entity,auditEvent.detail);
  const auditRecord=auditEvent?v4212Clone(database.audit?.[0]||null):null;
  const prepared=markPending?v4212PrepareOperation(auditEvent,auditRecord):null;
  const pending=database.sync?.pendingProposal||null;
  database.sync={...(database.sync||{}),state:pending?'approval':markPending?'pending':'local',lastSyncedAt:database.sync?.lastSyncedAt||null,message:pending?'Solicitud antigua pendiente de resolución':markPending?'Cambio guardado · enviando al servidor':'Guardado en este dispositivo',pendingProposal:pending,needsUpload:!!markPending||database.syncQueue.some(item=>['queued','retry','sending'].includes(item.status))};
  let queued=null;
  const staged=prepared&&prepared.requirementId&&prepared.action==='auto_sync';
  database.requirementDrafts ||= {};
  const key=prepared?sgl546DocumentKey(prepared):'';
  if(staged){database.requirementDrafts[key]=prepared;database.sync.needsUpload=database.syncQueue.some(x=>['queued','retry','sending'].includes(x.status));}
  else if(prepared){delete database.requirementDrafts[key];queued=await v4212EnqueuePrepared(prepared,{deferWrite:true});}
  if(queued)sgl546Uncommitted.add(queued.id);
  await kvSet('database',database);
  if(queued)sgl546Uncommitted.delete(queued.id);
  scheduleNativeSnapshot();renderTopSync();v4212UpdateFloatingSyncBadge();
  if(queued&&v3CanAttemptNetwork()&&database.settings.serverUrl){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow().catch(()=>{}),1400);}
};

v4FilesForOperation = async function v4FilesForOperationV4212(op){
  const sub=op.patch?.progress?.[op.ownerId]?.submissions?.[op.requirementId]||op.patch?.programProgress?.[op.ownerId]?.[op.programId||'class_grouped']?.submissions?.[op.requirementId];
  let ids=[...(op.fileIds||[]),...(sub?.attachmentIds||[])];
  if(sub?.primaryDocumentId)ids.push(sub.primaryDocumentId);
  if(!ids.length&&op.requirementId&&!sub)ids=v3SubmissionFor(op.ownerId,op.requirementId,op.programId||'class_grouped').attachmentIds||[];
  if(!ids.length&&op.entityId){const material=(database.materials||[]).find(item=>item.id===op.entityId);if(material?.fileId)ids=[material.fileId];}
  const files=[];
  for(const id of [...new Set(ids.map(String).filter(Boolean))]){
    let file=await fileGet(id);
    if(!file?.dataUrl&&typeof window.sgl509FetchRemoteFileById==='function')file=await window.sgl509FetchRemoteFileById(id);
    if(!file?.dataUrl)throw new Error(`Archivo ${id} pendiente. El informe se conserva y aún no se confirma su recepción.`);
    files.push(sgl544FileForUpload(file));
  }
  return files;
};

// Repair legacy byte-count metadata on transport without altering the frozen report.
function sgl544FileForUpload(file){
  if(!file?.dataUrl)return file;
  const value=String(file.dataUrl),comma=value.indexOf(',');
  if(comma<0||!/^data:[^,]*;base64$/.test(value.slice(0,comma)))throw new Error(`Archivo ${file.id} inválido; se conserva el envío pendiente.`);
  let bytes;try{bytes=atob(value.slice(comma+1));}catch{throw new Error(`Archivo ${file.id} dañado; se conserva el envío pendiente.`);}
  if(!bytes.length)throw new Error(`Archivo ${file.id} vacío; se conserva el envío pendiente.`);
  return {...file,size:bytes.length};
}

v4SendQueuedOperation = async function v4SendQueuedOperationV4212(op,user){
  const files=await v4FilesForOperation(op);
  if(op.action==='review'&&op.requirementId){
    const submission=op.patch?.progress?.[op.ownerId]?.submissions?.[op.requirementId]||op.patch?.programProgress?.[op.ownerId]?.[op.programId||'class_grouped']?.submissions?.[op.requirementId]||v3SubmissionFor(op.ownerId,op.requirementId,op.programId||'class_grouped');
    return v3Api('/api/reviews/submit',{method:'POST',allowStatuses:[409,422],timeout:files.length?180000:20000,body:{installationId:database.installationId,actorId:user.id,actorRole:user.role,ownerId:op.ownerId||user.id,operationId:op.id,requirementId:op.requirementId,requirementTitle:op.requirementTitle||'',programId:op.programId||'class_grouped',contentHash:op.contentHash||'',ackOnly:true,submission:v4212Clone(submission),files}});
  }
  return v3Api('/api/sync',{method:'POST',allowStatuses:[202,409,422],timeout:files.length?60000:20000,body:{installationId:database.installationId,proposalId:op.proposalId||null,actorId:user.id,actorRole:user.role,actorName:user.fullName,baseVersion:Math.max(Number(database.serverVersion||0),Number(database.sync?.ackServerVersion||0)),operationId:op.id,operationType:op.action,ownerId:op.ownerId||user.id,requirementId:op.requirementId||'',requirementTitle:op.requirementTitle||'',programId:op.programId||'',contentHash:op.contentHash||'',ackOnly:true,patch:op.patch||v4PatchForOperation(op),files}});
};

async function v4212DrainQueue(){
  if(v4212DrainPromise)return v4212DrainPromise;
  v4212DrainPromise=(async()=>{
    const user=currentUser();if(!user)return;
    if(user.role==='admin')return V4R_BASE_ADMIN_SYNC();
    if(!database?.settings?.serverUrl)return;
    if(!v3CanAttemptNetwork()){renderTopSync();return;}
    let rounds=0,lastId='';
    while(rounds<80){
      const op=database.syncQueue?.find(item=>['queued','retry'].includes(item.status));
      if(!op)break;
      rounds++;
      const beforeId=op.id;
      await v4SyncNowCore();
      const still=database.syncQueue?.find(item=>item.id===beforeId&&['queued','retry'].includes(item.status));
      if(still&&still.lastError)break;
      if(still&&lastId===beforeId)break;
      lastId=beforeId;
    }
    if(!database.syncQueue?.some(item=>['queued','retry'].includes(item.status))){await v3PullServerUpdates(false).catch(()=>{});if(database?.sync&&Number(database.serverVersion||0)>=Number(database.sync.ackServerVersion||0))delete database.sync.ackServerVersion;}
    v4212UpdateFloatingSyncBadge();
  })().finally(()=>{v4212DrainPromise=null;});
  return v4212DrainPromise;
}

syncNow = function syncNowV4212(){
  const user=currentUser();
  if(user?.role==='admin')return V4R_BASE_ADMIN_SYNC();
  return v4212DrainQueue();
};

function v4212HasActiveUnsavedRequirement(){const state=window.sgl529ReportState?.();return !!(state?.dirty||document.querySelector('#req_text')?.closest('.modal')?.__sgl5047Dirty);}

v3PullServerUpdates = async function v3PullServerUpdatesV4212(showToast=false){
  // Un indicador hasLocalDraft antiguo no puede congelar para siempre una laptop.
  // Solo se bloquea mientras el formulario editable esta realmente abierto.
  if(database?.sync?.hasLocalDraft&&!v4212HasActiveUnsavedRequirement()){
    database.sync.hasLocalDraft=false;await kvSet('database',database);
  }
  return V4212_BASE_PULL_SERVER_UPDATES(showToast);
};

function v4212UpdateFloatingSyncBadge(){
  const button=document.getElementById('floating_sync');if(!button)return;
  const count=(database?.syncQueue||[]).filter(item=>['queued','retry','sending'].includes(item.status)).length;
  button.dataset.pending=String(count);button.textContent=count?`S${count}`:'S';button.title=count?`Sincronizar todo ahora · ${count} cambio(s) pendiente(s)`:'Sincronizar todo ahora';
}

const V4212_BASE_RENDER_TOP_SYNC=renderTopSync;
renderTopSync = function renderTopSyncV4212(){V4212_BASE_RENDER_TOP_SYNC();v4212UpdateFloatingSyncBadge();};

// Guardar avance online intenta vaciar la cola inmediatamente. Offline conserva el
// cambio y vuelve a enviarlo al recuperar conectividad.
saveRequirement = async function saveRequirementV4212(send=false){
  await V4212_BASE_SAVE_REQUIREMENT(send);
  if(currentUser()&&database?.settings?.serverUrl&&v3CanAttemptNetwork()){
    await v4212DrainQueue().catch(()=>{});
    const pending=(database.syncQueue||[]).filter(item=>['queued','retry','sending'].includes(item.status));
    if(!pending.length&&!send) toast('Guardado. Consulta el indicador de sincronización para conocer el estado del envío.');
    else toast(`Guardado en este equipo. Quedan ${pending.length} cambio(s) por sincronizar.`);
  }
};

// Conserva los IDs de evidencias en el borrador local para que una actualizacion
// remota no haga desaparecer la referencia visual al reabrir el requisito.
captureRequirementDraft = function captureRequirementDraftV4212(){
  if(!modalOwnerId||!modalRequirementId||!document.getElementById('req_date')||!v3CanEditCurrentRequirementDraft())return null;
  const editor=readRichEditor(),submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId);
  return {type:'requirement',programId:v3ModalProgramId,ownerId:modalOwnerId,requirementId:modalRequirementId,text:editor.text,richText:editor.html,completionDate:value('req_date')||localDate(),orientation:value('req_orientation')||'auto',selections:[...document.querySelectorAll('[name=req_choice]:checked')].map(input=>input.value),attachmentIds:[...(submission.attachmentIds||[])],savedAt:isoNow()};
};
saveEmergencyDraft = function saveEmergencyDraftV4212(){const draft=captureRequirementDraft();if(draft)try{localStorage.setItem('musica_emergency_draft',JSON.stringify(draft));}catch{}};

// Un solo temporizador de sincronizacion. 4.2.13 dejaba activo el poll de 4 s y
// agregaba otro de 3 s. En 5.0.75 el escritorio usa un unico tick silencioso de 12 s.
renderShell = function renderShellV4212(){
  V4212_BASE_RENDER_SHELL();
  clearInterval(v3SyncPollTimer);v3SyncPollTimer=null;
  clearInterval(v4SyncPollTimer);
  v4SyncPollTimer=setInterval(()=>{v4BackgroundSyncTick().catch(()=>{});},12000);
  clearInterval(v4MessagePollTimer);
  v4MessagePollTimer=setInterval(()=>{v4FetchMessages(true);v4FetchNotifications(true);},12000);
  setTimeout(()=>{v4212UpdateFloatingSyncBadge();v4BackgroundSyncTick().catch(()=>{});},120);
};

// El boton amarillo vacia toda la cola y luego baja la ultima version central.
v4ForceSyncAll = async function v4ForceSyncAllV4212(){
  const button=document.getElementById('floating_sync');if(button?.classList.contains('working'))return;
  button?.classList.add('working');
  try{
    if(!currentUser())return;
    if(!database?.settings?.serverUrl)return toast('Este equipo todavía no tiene servidor configurado.');
    if(!v3CanAttemptNetwork())return toast('Sin conexión. Los cambios permanecen guardados y se enviarán al recuperar internet.');
    if(currentUser()?.role==='admin')await V4R_BASE_ADMIN_SYNC();else await v4212DrainQueue();
    await v3PullServerUpdates(false).catch(()=>{});
    const count=(database.syncQueue||[]).filter(item=>['queued','retry','sending'].includes(item.status)).length;
    toast(count?`Quedan ${count} cambio(s) pendiente(s). SGL seguirá reintentando.`:'Sincronización completa con el servidor.');
  }finally{button?.classList.remove('working');v4212UpdateFloatingSyncBadge();}
};
window.v4ForceSyncAll=v4ForceSyncAll;

/* ========================================================================== 
   SGL 4.2.25 - ownership-aware synchronization
   - Normal users are the primary source of their own data.
   - Administrator corrections over user-owned data require user consent.
   - Sync means send pending changes + receive new changes; it never means
     "server wins" or "this device wins".
   ========================================================================== */

let v4214AdminBaseline = null;
let v4214AdminDrainPromise = null;
let v4214UserChanges = [];
let v4214LastUserChangeFetch = 0;
let v4214LastUserPendingCount = 0;

const V4214_BASE_PERSIST = persist;
const V4214_BASE_SYNC_NOW = syncNow;
const V4214_BASE_FORCE_SYNC_ALL = v4ForceSyncAll;
const V4214_BASE_RENDER_SHELL = renderShell;
const V4214_BASE_APPLY_SERVER_SNAPSHOT = v3ApplyServerSnapshot;
const V4214_BASE_NAV_ITEMS = navItems;
const V4214_BASE_GO = go;
const V4214_BASE_RENDER_SETTINGS = renderSettings;
const V4214_BASE_RENDER_SYNC_REQUESTS = renderSyncRequests;
const V4214_BASE_BACKGROUND_SYNC_TICK = v4BackgroundSyncTick;
const V4214_BASE_MERGE_NOTIFICATIONS = v4MergeServerNotifications;
const V4214_BASE_FETCH_NOTIFICATIONS = v4FetchNotifications;
const V4214_BASE_NOTIFICATION_KIND = v4NotificationKind;

function v4214Clone(value){
  if(value===undefined)return undefined;
  try{return structuredClone(value);}catch{return JSON.parse(JSON.stringify(value));}
}

function v4214AdminView(source=database){
  const out={};
  for(const key of ['clubs','users','classes','modules','progress','programProgress','configs','indicationRules','tasks','materials','bibleYear']){
    if(source?.[key]!==undefined)out[key]=v4214Clone(source[key]);
  }
  if(source?.settings?.clubSchedule!==undefined||source?.settings?.activityHiddenIds!==undefined){out.settings={};if(source.settings.clubSchedule!==undefined)out.settings.clubSchedule=v4214Clone(source.settings.clubSchedule);if(source.settings.activityHiddenIds!==undefined)out.settings.activityHiddenIds=v4214Clone(source.settings.activityHiddenIds);}
  return out;
}

function v4214Equal(a,b){
  try{return v4StableStringify(a)===v4StableStringify(b);}catch{return JSON.stringify(a)===JSON.stringify(b);}
}

function v4214Diff(base,current,path=''){
  if(v4214Equal(base,current))return undefined;
  if(Array.isArray(current)){
    if(['assignedUserIds','managementProgramIds','tutorProgramIds','regionalProgramIds','requirementViewPrograms','programIds','assignedProgramIds','regionalAssignedUserIds'].some(key=>path.endsWith('.'+key))&&Array.isArray(base)&&Number(database.syncCapabilities?.assignmentDeltaVersion)>=1&&[...base,...current].every(id=>typeof id==='string')){
      const before=new Set(base),after=new Set(current);
      return {__sglSetMembers:{add:[...after].filter(id=>!before.has(id)),remove:[...before].filter(id=>!after.has(id))}};
    }
    if(Array.isArray(base)){
      const currentById=current.every(item=>item&&typeof item==='object'&&!Array.isArray(item)&&item.id!=null);
      const baseById=base.every(item=>item&&typeof item==='object'&&!Array.isArray(item)&&item.id!=null);
      if(currentById&&baseById){
        const baseMap=new Map(base.map(item=>[String(item.id),item]));
        const currentIds=new Set(current.map(item=>String(item.id)));
        // Entity deletion is uncommon at database top level. For nested lists
        // (for example class members), use an explicit replacement marker.
        if(base.some(item=>!currentIds.has(String(item.id))))return {__sglReplace:v4214Clone(current)};
        const changed=[];
        for(const item of current){
          const prior=baseMap.get(String(item.id));
          if(!prior){changed.push(v4214Clone(item));continue;}
          const delta=v4214Diff(prior,item,path);
          if(delta!==undefined)changed.push({id:item.id,...(delta&&typeof delta==='object'&&!Array.isArray(delta)?delta:v4214Clone(item))});
        }
        return changed.length?changed:undefined;
      }
    }
    return v4214Clone(current);
  }
  if(current&&typeof current==='object'){
    const prior=(base&&typeof base==='object'&&!Array.isArray(base))?base:{};
    const out={};
    const deleted=[];
    for(const key of Object.keys(current)){
      const delta=v4214Diff(prior[key],current[key],path+'.'+key);
      if(delta!==undefined)out[key]=delta;
    }
    for(const key of Object.keys(prior))if(!(key in current))deleted.push(key);
    if(deleted.length)out.__sglDeleteKeys=deleted;
    return Object.keys(out).length?out:undefined;
  }
  return v4214Clone(current);
}

function v4214PatchHasContent(patch){
  if(!patch||typeof patch!=='object')return false;
  return Object.keys(patch).some(key=>key!=='audit'&&patch[key]!==undefined);
}

function v4214FallbackPatch(auditEvent){
  const entity=String(auditEvent?.entity||'');
  const patch={};
  const user=(database.users||[]).find(item=>item.id===entity);if(user)patch.users=[v4214Clone(user)];
  const club=(database.clubs||[]).find(item=>item.id===entity);if(club)patch.clubs=[v4214Clone(club)];
  const cls=(database.classes||[]).find(item=>item.id===entity);if(cls)patch.classes=[v4214Clone(cls)];
  const module=(database.modules||[]).find(item=>item.id===entity);if(module)patch.modules=[v4214Clone(module)];
  const task=(database.tasks||[]).find(item=>item.id===entity);if(task)patch.tasks=[v4214Clone(task)];
  const material=(database.materials||[]).find(item=>item.id===entity);if(material)patch.materials=[v4214Clone(material)];
  const rule=(database.indicationRules||[]).find(item=>item.id===entity||item.requirementId===entity);if(rule)patch.indicationRules=[v4214Clone(rule)];
  if(entity==='clubSchedule'&&database.settings?.clubSchedule)patch.settings={clubSchedule:v4214Clone(database.settings.clubSchedule)};
  return patch;
}

function v4214CollectFileIds(value,ids=new Set()){
  if(!value)return ids;
  if(Array.isArray(value)){for(const item of value)v4214CollectFileIds(item,ids);return ids;}
  if(typeof value!=='object')return ids;
  for(const [key,item] of Object.entries(value)){
    if((key==='fileId'||key==='photoFileId')&&typeof item==='string'&&item)ids.add(item);
    if(key==='attachmentIds'&&Array.isArray(item))for(const id of item)if(id)ids.add(String(id));
    v4214CollectFileIds(item,ids);
  }
  return ids;
}

function v4214SetAdminBaseline(){
  if(currentUser()?.role==='admin')v4214AdminBaseline=v4214AdminView(database);
}

async function v4214QueueAdminChange(patch,auditEvent,auditRecord){
  if(!v4214PatchHasContent(patch))return null;
  v4EnsureReliableState();
  if(auditRecord)patch.audit=[v4214Clone(auditRecord)];
  const summary=[String(auditEvent?.action||'Cambio del Administrador'),String(auditEvent?.detail||'')].filter(Boolean).join(' - ');
  const contentHash=v4HashString(v4StableStringify({patch,summary,revision:Number(database.revision||0)}));
  const id=`SGL-ADM-${String(currentUser()?.id||'ADMIN').replace(/[^a-z0-9]/gi,'').slice(-6).toUpperCase()}-${contentHash.slice(0,14).toUpperCase()}`;
  if(v4FindOperation(id))return v4FindOperation(id);
  const fileIds=[...v4214CollectFileIds(patch)];
  const op={id,action:'admin_change',restoreGeneration:Number(database.restoreGeneration||1),actorId:currentUser().id,ownerId:'',programId:auditEvent?.programId||v3ActiveProgramId||'class_grouped',requirementId:'',entityId:String(auditEvent?.entity||''),contentHash,patch:v4214Clone(patch),fileIds,summary,status:'queued',createdAt:isoNow(),updatedAt:isoNow(),attempts:0};
  database.syncQueue.push(op);
  database.sync={...(database.sync||{}),state:'pending',message:`${database.syncQueue.filter(item=>['queued','retry','sending'].includes(item.status)).length} cambio(s) por sincronizar`,needsUpload:true,lastSyncedAt:database.sync?.lastSyncedAt||null,pendingProposal:null};
  v4214AdminBaseline=v4214AdminView(database);
  return op;
}

persist = async function persistV4214(markPending=true,auditEvent=null){
  const actor=currentUser();
  if(!actor||actor.role!=='admin')return V4214_BASE_PERSIST(markPending,auditEvent);
  v4EnsureReliableState();
  const before=v4214AdminBaseline?v4214Clone(v4214AdminBaseline):null;
  database.updatedAt=isoNow();database.revision=(database.revision||0)+1;
  if(auditEvent)addAudit(auditEvent.action,auditEvent.entity,auditEvent.detail);
  const auditRecord=auditEvent?v4214Clone(database.audit?.[0]||null):null;
  if(markPending){
    let patch=before?v4214Diff(before,v4214AdminView(database)):undefined;
    if(!patch||!v4214PatchHasContent(patch))patch=v4214FallbackPatch(auditEvent);
    await v4214QueueAdminChange(patch||{},auditEvent,auditRecord);
  }else{
    v4214AdminBaseline=v4214AdminView(database);
  }
  await kvSet('database',database);scheduleNativeSnapshot();renderTopSync();v4212UpdateFloatingSyncBadge();
  if(markPending&&database.settings?.autoSync&&database.settings?.serverUrl&&v3CanAttemptNetwork()){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow().catch(()=>{}),1400);}
};

async function v4214FilesForAdminOperation(op){
  const files=[];for(const id of [...new Set((op?.fileIds||[]).map(String).filter(Boolean))]){const file=await fileGet(id);if(!file?.dataUrl&&!file?.verses)throw new Error(`Archivo ${id} pendiente: no se confirma un cambio administrativo sin sus archivos.`);files.push(sgl544FileForUpload(file));}
  return files;
}

async function v4214RefreshAdminCanonical(){
  if(currentUser()?.role!=='admin'||!database.settings?.serverUrl||!v3CanAttemptNetwork())return null;
  const {payload}=await v3Api('/api/bootstrap',{timeout:180000});
  if(payload?.database)await v3ApplyServerSnapshot(payload);
  return payload;
}

async function v4214DrainAdminQueue(showToast=false){
  if(v4214AdminDrainPromise)return v4214AdminDrainPromise;
  v4214AdminDrainPromise=(async()=>{
    const user=currentUser();if(!user||user.role!=='admin'||!database.settings?.serverUrl)return;
    if(!v3CanAttemptNetwork())return;
    if(database.restorePending?.recoveryRequired){database.sync={...(database.sync||{}),state:'pending',message:'Recuperación requerida por cambio de generación. Los cambios están conservados.',needsUpload:true};await kvSet('database',database);renderTopSync();if(showToast)toast(database.sync.message);return {sent:0,recoveryRequired:true};}
    let sent=0,pendingUser=0;
    while(true){
      const op=sgl559NextOperation(database.syncQueue,user.id,'admin_change');
      if(!op)break;
      op.status='sending';sgl546ActiveSending.add(op.id);op.attempts=Number(op.attempts||0)+1;op.updatedAt=isoNow();delete op.lastError;op.lastError='';
      try{
        await kvSet('database',database);renderTopSync();
        const files=await v4214FilesForAdminOperation(op);
        const {payload}=await v3Api('/api/admin/changes',{method:'POST',timeout:180000,body:{installationId:database.installationId,actorId:user.id,operationId:op.id,programId:op.programId||sgl556ItemProgram(op),entityId:op.entityId||'',restoreGeneration:Number(op.restoreGeneration||database.restoreGeneration||1),summary:op.summary||'Cambio del Administrador',patch:op.patch,files,ackOnly:true}});
        if(payload?.ok!==true||payload.operationId!==op.id||!['applied','pending_user','mixed_pending_user'].includes(payload.status))throw new Error('El servidor no confirmó este cambio administrativo. Se conserva para reintentar.');
        const status=payload.status;
        database.sync={...(database.sync||{}),ackServerVersion:Number(payload?.serverVersion||0),forceCanonicalPull528:true};
        if(status==='pending_user'||status==='mixed_pending_user')pendingUser+=Number(payload?.requestIds?.length||1);
        v4CompleteOperation(op.id,status,status==='pending_user'||status==='mixed_pending_user'?'Pendiente de aceptacion del usuario':'Aplicado por el servidor');
        sent++;
      }catch(error){
        const queued=(database.syncQueue||[]).find(item=>item.id===op.id);
        if(queued){queued.status='retry';queued.lastError=error.message||String(error);queued.updatedAt=isoNow();queued.nextAttemptAt=Date.now()+sgl559RetryDelay(queued);}
        database.sync={...(database.sync||{}),state:'pending',message:'Cambio administrativo pendiente: '+String(error.message||error),needsUpload:true};
        await kvSet('database',database);renderTopSync();break;
      }finally{sgl546ActiveSending.delete(op.id);}
    }
    database.sync.needsUpload=sgl559OwnPending(database.syncQueue,user.id).length>0;
    let canonicalDownloaded=false;
    if(sent&&!database.sync.needsUpload){
      // Always download the canonical server copy. A user-owned correction is only
      // a proposal, so it must not remain applied locally on the Administrator PC.
      canonicalDownloaded=!!(await v4214RefreshAdminCanonical().catch(()=>null));
    }else{
      await kvSet('database',database);renderTopSync();
    }
    if(showToast){
      if(database.sync.needsUpload)toast('Quedan cambios pendientes. SGL seguira reintentando.');
      else if(pendingUser)toast(`${pendingUser} cambio(s) enviados al usuario para aceptar. El resto quedo sincronizado.`);
      else toast('Sincronización completada.');
    }
    return {sent,canonicalDownloaded};
  })().finally(()=>{v4214AdminDrainPromise=null;});
  return v4214AdminDrainPromise;
}

syncNow = function syncNowV4214(){
  const user=currentUser();
  if(user?.role==='admin')return v4214DrainAdminQueue(false).then(result=>result?.canonicalDownloaded?result:v4214RefreshAdminCanonical().catch(()=>null));
  return V4214_BASE_SYNC_NOW();
};

v4ForceSyncAll = async function v4ForceSyncAllV4214(){
  if(currentUser()?.role!=='admin')return V4214_BASE_FORCE_SYNC_ALL();
  const button=document.getElementById('floating_sync');if(button?.classList.contains('working'))return;
  button?.classList.add('working');
  try{
    if(!database?.settings?.serverUrl)return toast('Este equipo todavia no tiene servidor configurado.');
    if(!v3CanAttemptNetwork())return toast('Sin conexion. Los cambios quedan guardados y se enviaran al recuperar internet.');
    await v4214DrainAdminQueue(false);await v4214RefreshAdminCanonical();
    const count=(database.syncQueue||[]).filter(item=>['queued','retry','sending'].includes(item.status)).length;
    toast(count?`Quedan ${count} cambio(s) pendiente(s).`:'Sincronización completa: cambios enviados y novedades recibidas.');
  }finally{button?.classList.remove('working');v4212UpdateFloatingSyncBadge();}
};
window.v4ForceSyncAll=v4ForceSyncAll;

v3ApplyServerSnapshot = async function v3ApplyServerSnapshotV4214(snapshot,notification=null){
  const result=await V4214_BASE_APPLY_SERVER_SNAPSHOT(snapshot,notification);
  if(result===false||result?.stale||result?.deferred)return result;
  if(currentUser()?.role==='admin')v4214SetAdminBaseline();
  return result;
};

async function v4214FetchUserChanges(force=false){
  const user=currentUser();if(!user||user.role==='admin'||!database.settings?.serverUrl)return[];
  const now=Date.now();if(!force&&now-v4214LastUserChangeFetch<4500)return v4214UserChanges;
  v4214LastUserChangeFetch=now;
  if(!v3CanAttemptNetwork())return v4214UserChanges;
  try{
    const query=new URLSearchParams({actorId:user.id,status:'pending'});
    const {payload}=await v3Api(`/api/user-changes?${query.toString()}`,{timeout:30000});
    const incoming=Array.isArray(payload?.changes)?payload.changes:[];
    const prior=v4214LastUserPendingCount;v4214UserChanges=incoming;v4214LastUserPendingCount=incoming.length;
    if(incoming.length>prior&&prior>=0){
      const newest=incoming[0];toast(`Cambio propuesto por el Administrador: ${short(newest?.summary||'Revisa el cambio pendiente.',110)}`);
    }
    renderNav();
    if(currentPage==='change_requests')renderUserChangeRequests();
    return incoming;
  }catch{return v4214UserChanges;}
}
window.v4214FetchUserChanges=v4214FetchUserChanges;

function v4214ChangePatchSummary(change){
  const patch=change?.patch||{},labels=[];
  if(Array.isArray(patch.users)){
    const fields=new Set();for(const user of patch.users)for(const key of Object.keys(user||{}))if(key!=='id')fields.add(key);
    const names={fullName:'nombre',email:'correo',phone:'telefono',birthDate:'fecha de nacimiento',photo:'foto',theme:'tema',reportFont:'formato de informe'};
    labels.push(`Datos personales: ${[...fields].map(key=>names[key]||key).join(', ')||'actualizacion'}`);
  }
  if(patch.progress||patch.programProgress)labels.push('Avances, checks o informes');
  if(patch.configs)labels.push('Configuracion de requisitos');
  if(patch.classes)labels.push('Clase / Mis Conquis');
  if(patch.bibleYear)labels.push('Ano biblico');
  if(patch.tasks)labels.push('Tareas');
  if(patch.materials)labels.push('Materiales o archivos');
  return labels.join(' - ')||'Correccion puntual sobre informacion que cargaste';
}

function renderUserChangeRequests(){
  const user=currentUser();if(!user||user.role==='admin')return go('dashboard');
  setTop('Cambios propuestos','Revision del usuario');
  const pending=v4214UserChanges.filter(item=>item.status==='pending');
  setContent(`<div class="page-head"><div><div class="eyebrow">Tus datos siguen bajo tu control</div><h1 class="page-title">${pending.length} cambio${pending.length===1?'':'s'} pendiente${pending.length===1?'':'s'}</h1><p class="subtitle">Solicitudes heredadas de versiones anteriores. Desde 4.2.25 los cambios nuevos del Administrador se aplican y solo se notifican.</p></div><div class="actions"><button class="btn ghost" onclick="v4214FetchUserChanges(true)">Actualizar</button>${pending.length>1?'<button class="btn primary" onclick="v4214DecideUserChanges([],\'accept\',true)">Aceptar todos</button>':''}</div></div><section class="sync-request-grid">${pending.map(item=>`<article class="card sync-request-card"><div class="card-head"><div><span class="status in_review">Pendiente de tu decisión</span><h3>${esc(item.summary||'Cambio propuesto')}</h3><p class="subtitle" style="margin:0">${esc(item.actorName||'Administrador')} - ${formatDateTime(item.createdAt)}</p></div><b class="sync-request-icon">\u21c4</b></div><div class="notice" style="margin:12px 0"><b>Qué se propone cambiar:</b><br>${esc(v4214ChangePatchSummary(item))}</div><div class="actions"><button class="btn red" onclick="v4214DecideUserChanges(['${esc(item.id)}'],'reject',false)">Rechazar</button><button class="btn primary" onclick="v4214DecideUserChanges(['${esc(item.id)}'],'accept',false)">Aceptar cambio</button></div></article>`).join('')||'<div class="card empty">No tienes cambios propuestos pendientes.</div>'}</section>`);
}
window.renderUserChangeRequests=renderUserChangeRequests;

async function v4214DecideUserChanges(ids,decisión,allPending=false){
  const user=currentUser();if(!user||user.role==='admin')return;
  if(!database.settings?.serverUrl||!v3CanAttemptNetwork())return toast('Necesitas conexion para confirmar la decisión.');
  try{
    const {payload}=await v3Api('/api/user-changes/decision',{method:'POST',timeout:120000,body:{actorId:user.id,requestIds:ids,decision:decisión,allPending,note:''}});
    if(payload?.database)await v3ApplyServerSnapshot(payload);
    await v4214FetchUserChanges(true);await v4FetchNotifications(false);
    toast(decisión==='accept'?(allPending?'Cambios aceptados y sincronizados.':'Cambio aceptado y sincronizado.'):'Cambio rechazado. Tus datos se conservaron.');
    if(currentPage==='change_requests')renderUserChangeRequests();
  }catch(error){toast(`No se pudo guardar tu decisión: ${error.message}`);}
}
window.v4214DecideUserChanges=v4214DecideUserChanges;

navItems = function navItemsV4214(user){
  const items=V4214_BASE_NAV_ITEMS(user);
  if(user?.role!=='admin'){
    const label=v4214UserChanges.length?`Cambios propuestos (${v4214UserChanges.length})`:'Cambios propuestos';
    const at=Math.max(0,items.findIndex(item=>item[0]==='settings'));
    items.splice(at<0?items.length:at,0,['change_requests','\u21c4',label]);
  }
  return items;
};

go = function goV4214(page){
  if(page==='change_requests'){
    if(currentUser()?.role==='admin')return V4214_BASE_GO('dashboard');
    currentPage=page;closeModal();renderNav();renderUserChangeRequests();v4214FetchUserChanges(true);return;
  }
  return V4214_BASE_GO(page);
};

renderSettings = function renderSettingsV4214(){
  V4214_BASE_RENDER_SETTINGS();
  const root=document.getElementById('content'),user=currentUser();if(!root||!user)return;
  if(user.role!=='admin')root.insertAdjacentHTML('beforeend',`<section class="card" style="margin-top:16px"><div class="card-head"><div><h3>Solicitudes heredadas del Administrador</h3><p class="subtitle" style="margin:0">Solo aplica a solicitudes antiguas; desde 4.2.25 los cambios nuevos se notifican sin aprobacion.</p></div><button class="btn ghost" onclick="go('change_requests')">Revisar${v4214UserChanges.length?` (${v4214UserChanges.length})`:''}</button></div></section>`);
};

renderSyncRequests = function renderSyncRequestsV4214(){
  V4214_BASE_RENDER_SYNC_REQUESTS();
  for(const button of document.querySelectorAll('#content button')){
    if(button.textContent.trim()==='Sincronizar datos del Administrador')button.textContent='Sincronizar';
  }
};

v4MergeServerNotifications = function v4MergeServerNotificationsV4214(items){
  V4214_BASE_MERGE_NOTIFICATIONS(items);
  const byId=new Map((items||[]).map(item=>[item.id,item]));
  for(const local of database.syncNotifications||[]){
    const remote=byId.get(local.id);if(remote?.changeRequestId)local.changeRequestId=remote.changeRequestId;
  }
};

v4NotificationKind = function v4NotificationKindV4214(item){
  if(item?.type==='admin_change_applied')return 'Cambio realizado';
  if(item?.type==='admin_change_requested')return 'Cambio propuesto';
  if(item?.type==='admin_change_accepted')return 'Cambio aceptado';
  if(item?.type==='admin_change_rejected')return 'Cambio rechazado';
  return V4214_BASE_NOTIFICATION_KIND(item);
};

v4FetchNotifications = async function v4FetchNotificationsV4214(notify=true,showLogin=false){
  const items=await V4214_BASE_FETCH_NOTIFICATIONS(notify,showLogin);
  if(currentUser()?.role!=='admin')v4214FetchUserChanges(false).catch(()=>{});
  return items;
};
window.v4FetchNotifications=v4FetchNotifications;

v4BackgroundSyncTick = async function v4BackgroundSyncTickV4214(){
  const user=currentUser();
  if(user?.role==='admin'){
    if((database.syncQueue||[]).some(item=>item.action==='admin_change'&&['queued','retry'].includes(item.status)))return v4214DrainAdminQueue(false);
    if((database.syncQueue||[]).some(item=>item.action==='admin_change'&&item.status==='sending'))return v4214AdminDrainPromise||null;
    return v3PullServerUpdates(false);
  }
  const result=await V4214_BASE_BACKGROUND_SYNC_TICK();
  v4214FetchUserChanges(false).catch(()=>{});
  return result;
};

renderShell = function renderShellV4214(){
  V4214_BASE_RENDER_SHELL();
  const user=currentUser();
  if(user?.role==='admin'&&!v4214AdminBaseline)v4214SetAdminBaseline();
  if(user?.role!=='admin')setTimeout(()=>v4214FetchUserChanges(true),500);
};

// Legacy conflict wording no longer presents one database as the winner.
renderConflicts = function renderConflictsV4214(){
  setTop('Sincronización pendiente','Administracion');
  setContent(`<div class="page-head"><div><div class="eyebrow">Protección de cambios</div><h1 class="page-title">${database.conflicts.length} incidencia${database.conflicts.length===1?'':'s'}</h1><p class="subtitle">SGL ya no da prioridad ciega al servidor ni a este equipo. Los cambios se envian como operaciones y se reciben sin reemplazar toda la base.</p></div></div><div class="card">${database.conflicts.map(item=>`<div class="conflict"><b>${esc(item.entity||'Sincronización')}</b><p>${esc(item.message||'Hay una version antigua pendiente de reparar.')}</p><div class="actions"><button class="btn warn small" onclick="v4ShowSyncDiagnostics()">Diagnóstico y reparación</button><button class="btn ghost small" onclick="v4214DismissLegacyConflict('${item.id}')">Cerrar aviso</button></div></div>`).join('')||'<div class="empty">No hay incidencias pendientes.</div>'}</div>`);
};
async function v4214DismissLegacyConflict(id){database.conflicts=(database.conflicts||[]).filter(item=>item.id!==id);await kvSet('database',database);renderConflicts();}
window.v4214DismissLegacyConflict=v4214DismissLegacyConflict;

// Keep public references aligned with the final overrides.
window.syncNow=syncNow;
window.go=go;

/* ==========================================================================
   SGL 4.2.25 - publicacion inicial de base con Funnel activo
   --------------------------------------------------------------------------
   Cuando el acceso remoto se activa sobre un servidor local limpio, el Funnel
   puede quedar publicado antes de que exista una base central. El Administrador
   debe publicar su base local completa una sola vez; despues, los cambios del
   Administrador vuelven al canal incremental /api/admin/changes.
   ========================================================================== */

const V4216_BASE_SYNC_NOW = syncNow;
let v4216InitialPublishPromise = null;

async function v4216ServerHealthForInitialPublish(){
  if(!database?.settings?.serverUrl || !v3CanAttemptNetwork()) return null;
  try{
    const {payload}=await v3Api('/api/health',{timeout:15000});
    return payload || null;
  }catch(error){
    return null;
  }
}

async function v4216PublishInitialRemoteBase(){
  if(v4216InitialPublishPromise) return v4216InitialPublishPromise;
  v4216InitialPublishPromise=(async()=>{
    const user=currentUser();
    if(!user || user.role!=='admin' || !database?.settings?.serverUrl || !v3CanAttemptNetwork()) return false;
    const priorServerVersion=Number(database.serverVersion||0);
    const priorSync=v4214Clone(database.sync||{});
    database.serverVersion=0;
    database.sync={...(database.sync||{}),state:'syncing',message:'Publicando base inicial en el servidor remoto',needsUpload:true,pendingProposal:null};
    await kvSet('database',database);renderTopSync();
    await V4R_BASE_ADMIN_SYNC();
    if(database.sync?.state==='ok'){
      database.sync={...(database.sync||{}),state:'ok',lastSyncedAt:isoNow(),message:'Base publicada en el servidor remoto',needsUpload:false,pendingProposal:null};
      v4214SetAdminBaseline();
      await kvSet('database',database);renderTopSync();
      return true;
    }
    database.serverVersion=priorServerVersion;
    database.sync={...priorSync,state:'pending',message:database.sync?.message||'Funnel activo; falta publicar la base',needsUpload:true,pendingProposal:null};
    await kvSet('database',database);renderTopSync();
    return false;
  })().finally(()=>{v4216InitialPublishPromise=null;});
  return v4216InitialPublishPromise;
}

syncNow = function syncNowV4216(){
  const user=currentUser();
  if(user?.role==='admin'){
    return (async()=>{
      const health=await v4216ServerHealthForInitialPublish();
      if(health && health.initialized===false){
        const published=await v4216PublishInitialRemoteBase();
        if(published) return true;
      }
      return V4216_BASE_SYNC_NOW();
    })();
  }
  return V4216_BASE_SYNC_NOW();
};

v4ForceSyncAll = async function v4ForceSyncAllV4216(){
  if(currentUser()?.role!=='admin') return V4214_BASE_FORCE_SYNC_ALL();
  const button=document.getElementById('floating_sync');if(button?.classList.contains('working'))return;
  button?.classList.add('working');
  try{
    if(!database?.settings?.serverUrl)return toast('Este equipo todavia no tiene servidor configurado.');
    if(!v3CanAttemptNetwork())return toast('Sin conexion. Los cambios quedan guardados y se enviaran al recuperar internet.');
    const health=await v4216ServerHealthForInitialPublish();
    if(health && health.initialized===false){
      const published=await v4216PublishInitialRemoteBase();
      return toast(published?'Base publicada. El acceso remoto ya tiene datos para los lideres.':'No se pudo publicar la base. Revisa Diagnóstico y reparación.');
    }
    await V4216_BASE_SYNC_NOW();
    const count=(database.syncQueue||[]).filter(item=>['queued','retry','sending'].includes(item.status)).length;
    toast(count?`Quedan ${count} cambio(s) pendiente(s).`:'Sincronización completa: cambios enviados y novedades recibidas.');
  }finally{button?.classList.remove('working');v4212UpdateFloatingSyncBadge();}
};

window.syncNow=syncNow;
window.v4ForceSyncAll=v4ForceSyncAll;

/* ==========================================================================
   SGL 4.2.25 - aprobacion visible de cambios propuestos del Administrador
   --------------------------------------------------------------------------
   La notificacion ya no queda como aviso de solo lectura: cuando contiene un
   cambio administrativo pendiente, el usuario puede aceptar o rechazar desde
   Avisos, o desde un aviso insertado en la pantalla de Planificacion.
   ========================================================================== */

const V4217_BASE_MERGE_NOTIFICATIONS = v4MergeServerNotifications;
const V4217_BASE_SHOW_NOTIFICATIONS = v4ShowNotifications;
const V4217_BASE_RENDER_CLASS_WORKSPACE = renderClassWorkspace;

function v4217JS(value){
  return String(value||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\r/g,'').replace(/\n/g,'\\n');
}

function v4217StatusClass(item){
  if(item?.type==='approved')return 'approved';
  if(item?.type==='needs_changes'||item?.type==='admin_change_rejected')return 'needs_changes';
  if(item?.type==='admin_change_accepted')return 'approved';
  return 'in_review';
}

function v4217NotificationIcon(item){
  if(item?.type==='approved'||item?.type==='admin_change_accepted')return '✓';
  if(item?.type==='needs_changes'||item?.type==='admin_change_rejected')return '!';
  if(item?.type==='review_submitted')return '↗';
  if(item?.type==='admin_change_applied')return '✓';
  if(item?.type==='admin_change_requested')return '⇄';
  return '•';
}

function v4217RequestIdForNotice(item){
  const direct=String(item?.changeRequestId||'').trim();
  if(direct)return direct;
  const source=String(item?.sourceOperationId||'').trim();
  const pending=Array.isArray(v4214UserChanges)?v4214UserChanges.filter(change=>change?.status==='pending'):[];
  if(source){
    const match=pending.find(change=>String(change?.operationId||'')===source);
    if(match?.id)return match.id;
  }
  const message=String(item?.message||'').trim();
  if(message){
    const match=pending.find(change=>String(change?.summary||'').trim()===message);
    if(match?.id)return match.id;
  }
  return '';
}

function v4217NotificationActions(item){
  if(item?.type==='admin_change_applied')return item?.read?'':`<button class="btn ghost small" onclick="v4MarkNotificationRead('${v4217JS(item.id)}').then(()=>v4ShowNotifications(false))">Leído</button>`;
  if(currentUser()?.role==='admin'||item?.type!=='admin_change_requested')return item?.read?'':`<button class="btn ghost small" onclick="v4MarkNotificationRead('${v4217JS(item.id)}').then(()=>v4ShowNotifications(false))">Leído</button>`;
  const requestId=v4217RequestIdForNotice(item);
  const readButton=item?.read?'':`<button class="btn ghost small" onclick="v4MarkNotificationRead('${v4217JS(item.id)}').then(()=>v4ShowNotifications(false))">Leído</button>`;
  if(!requestId){
    return `<div class="actions notification-actions"><button class="btn primary small" onclick="v4217OpenUserChangeRequests('${v4217JS(item.id)}')">Revisar cambio</button>${readButton}</div>`;
  }
  return `<div class="actions notification-actions"><button class="btn red small" onclick="v4217DecideNoticeChange('${v4217JS(item.id)}','${v4217JS(requestId)}','reject')">Rechazar</button><button class="btn primary small" onclick="v4217DecideNoticeChange('${v4217JS(item.id)}','${v4217JS(requestId)}','accept')">Aceptar</button>${readButton}</div>`;
}

v4MergeServerNotifications = function v4MergeServerNotificationsV4217(items){
  V4217_BASE_MERGE_NOTIFICATIONS(items);
  const byId=new Map((items||[]).map(item=>[item.id,item]));
  for(const local of database.syncNotifications||[]){
    const remote=byId.get(local.id);
    if(!remote)continue;
    if(remote.changeRequestId)local.changeRequestId=remote.changeRequestId;
    if(remote.sourceOperationId)local.sourceOperationId=remote.sourceOperationId;
  }
};

function v4ShowNotificationsV4217(fromLogin=false){
  const items=(database.syncNotifications||[]).slice(0,40),unread=items.filter(item=>!item.read).length;
  showModal(`<div class="modal message-modal notification-modal"><div class="modal-head"><div><h3>${fromLogin?'Tienes avisos pendientes':'Avisos'}</h3><p>${unread?`${unread} sin leer. Los cambios propuestos se aceptan o rechazan aquí.`:'No hay avisos pendientes.'}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="notification-list">${items.map(item=>`<article class="notification-item ${item.read?'':'unread'}"><div class="notification-icon">${v4217NotificationIcon(item)}</div><div><div class="chips"><span class="status ${v4217StatusClass(item)}">${esc(v4NotificationKind(item))}</span>${item.requirementId?`<span class="chip">${esc(item.requirementId)}</span>`:''}</div><h4>${esc(item.title||'Aviso')}</h4><p>${esc(item.message||'')}</p><small>${formatDateTime(item.createdAt)}</small></div>${v4217NotificationActions(item)}</article>`).join('')||'<div class="empty">No hay avisos.</div>'}</div></div><div class="modal-foot">${unread?'<button class="btn ghost" onclick="v4MarkAllNotificationsRead()">Marcar todos como leídos</button>':''}<button class="btn primary" onclick="closeModal()">Cerrar</button></div></div>`);
}

async function v4217OpenUserChangeRequests(notificationId=''){
  if(notificationId)await v4MarkNotificationRead(notificationId).catch(()=>{});
  closeModal();
  await v4214FetchUserChanges(true).catch(()=>{});
  go('change_requests');
}

async function v4217DecideNoticeChange(notificationId,requestId,decisión){
  const ids=String(requestId||'').trim()?[String(requestId).trim()]:[];
  if(!ids.length)return v4217OpenUserChangeRequests(notificationId);
  if(notificationId)await v4MarkNotificationRead(notificationId).catch(()=>{});
  closeModal();
  await v4214DecideUserChanges(ids,decisión,false);
  if(currentPage==='classes')renderClassWorkspace();
  else if(currentPage==='dashboard')renderDashboard();
}

function v4217PendingClassChangeIds(classId){
  const id=String(classId||'');
  if(!id||currentUser()?.role==='admin')return[];
  const changes=Array.isArray(v4214UserChanges)?v4214UserChanges:[];
  return changes.filter(change=>{
    if(change?.status!=='pending')return false;
    const classes=change?.patch?.classes;
    return Array.isArray(classes)&&classes.some(item=>String(item?.id||'')===id);
  }).map(change=>String(change.id||'')).filter(Boolean);
}

async function v4217DecideClassPending(classId,decisión){
  let ids=v4217PendingClassChangeIds(classId);
  if(!ids.length){
    await v4214FetchUserChanges(true).catch(()=>{});
    ids=v4217PendingClassChangeIds(classId);
  }
  if(!ids.length)return toast('No hay cambios pendientes para esta planificacion.');
  await v4214DecideUserChanges(ids,decisión,false);
  if(currentPage==='classes')renderClassWorkspace();
}

function v4217InjectClassPlanningChangeNotice(){
  if(currentUser()?.role==='admin'||activeClassSection!=='planning')return;
  const ids=v4217PendingClassChangeIds(activeClassId);
  if(!ids.length)return;
  const body=document.querySelector('.class-work-body');
  if(!body||body.querySelector('.admin-change-plan-notice'))return;
  body.insertAdjacentHTML('afterbegin',`<section class="notice warn admin-change-plan-notice" style="margin-bottom:14px"><div><b>El Administrador propuso una modificacion en esta planificacion.</b><br>La tabla puede verse como lectura, pero la decisión se toma aquí: acepta para aplicar el texto del Administrador o rechaza para conservar tu version.</div><div class="actions" style="margin-top:10px"><button class="btn red small" onclick="v4217DecideClassPending('${v4217JS(activeClassId)}','reject')">Rechazar</button><button class="btn primary small" onclick="v4217DecideClassPending('${v4217JS(activeClassId)}','accept')">Aceptar cambio</button><button class="btn ghost small" onclick="go('change_requests')">Ver detalle</button></div></section>`);
}

renderClassWorkspace = function renderClassWorkspaceV4217(){
  V4217_BASE_RENDER_CLASS_WORKSPACE();
  v4217InjectClassPlanningChangeNotice();
};

renderUserChangeRequests = function renderUserChangeRequestsV4217(){
  const user=currentUser();if(!user||user.role==='admin')return go('dashboard');
  setTop('Cambios propuestos','Decision del usuario');
  const pending=v4214UserChanges.filter(item=>item.status==='pending');
  setContent(`<div class="page-head"><div><div class="eyebrow">Tus datos siguen bajo tu control</div><h1 class="page-title">${pending.length} cambio${pending.length===1?'':'s'} pendiente${pending.length===1?'':'s'}</h1><p class="subtitle">Solicitudes heredadas de versiones anteriores. Desde 4.2.25 los cambios nuevos del Administrador se aplican y solo se notifican. No necesitas editar el campo: solo aceptar o rechazar.</p></div><div class="actions"><button class="btn ghost" onclick="v4214FetchUserChanges(true)">Actualizar</button>${pending.length>1?'<button class="btn primary" onclick="v4214DecideUserChanges([],\'accept\',true)">Aceptar todos</button>':''}</div></div><section class="sync-request-grid">${pending.map(item=>`<article class="card sync-request-card"><div class="card-head"><div><span class="status in_review">Pendiente de tu decisión</span><h3>${esc(item.summary||'Cambio propuesto')}</h3><p class="subtitle" style="margin:0">${esc(item.actorName||'Administrador')} - ${formatDateTime(item.createdAt)}</p></div><b class="sync-request-icon">⇄</b></div><div class="notice" style="margin:12px 0"><b>Qué se propone cambiar:</b><br>${esc(v4214ChangePatchSummary(item))}</div><div class="actions"><button class="btn red" onclick="v4214DecideUserChanges(['${esc(item.id)}'],'reject',false)">Rechazar</button><button class="btn primary" onclick="v4214DecideUserChanges(['${esc(item.id)}'],'accept',false)">Aceptar cambio</button></div></article>`).join('')||'<div class="card empty">No tienes cambios propuestos pendientes.</div>'}</section>`);
};

window.v4ShowNotifications=v4ShowNotifications=v4ShowNotificationsV4217;
window.v4MergeServerNotifications=v4MergeServerNotifications;
window.renderClassWorkspace=renderClassWorkspace;
window.renderUserChangeRequests=renderUserChangeRequests;
window.v4217OpenUserChangeRequests=v4217OpenUserChangeRequests;
window.v4217DecideNoticeChange=v4217DecideNoticeChange;
window.v4217DecideClassPending=v4217DecideClassPending;
const V4220_ADMIN_APPLIED_NOTICE_COPY = 'Cambio aplicado por el Administrador: se notificó al usuario sin solicitar aprobación.';

/*
   SGL 4.2.25 - guardado confirmado de planificacion y envio unico a revision
   - La planificacion de clases ya no registra cada campo al servidor.
   - Los cambios quedan como borrador de la pantalla hasta Guardar avance.
   - Al salir con cambios pendientes se pide Guardar, Salir sin guardar o Cancelar.
   - Un requisito ya En revision/Revisado no se puede enviar otra vez desde otro equipo.
*/
const V4218_CLASS_PLAN_DRAFTS = {};
const V4218_DIRTY_CLASS_IDS = new Set();
const V4218_PENDING_CONTINUATIONS = new Map();

function v4218Clone(value){ return value == null ? value : structuredClone(value); }
function v4218PlanDefaults(){ return {sessions:'',time:'',date:'',objective:'',option:'',activities:'',materials:'',evaluation:'',cost:'',progressed:false}; }
function v4218ClassById(classId){ return (database?.classes||[]).find(item=>String(item.id)===String(classId)) || null; }
function v4218DraftPlanning(classId){
  const item=v4218ClassById(classId); if(!item)return{};
  if(!V4218_CLASS_PLAN_DRAFTS[classId]) V4218_CLASS_PLAN_DRAFTS[classId]=v4218Clone(classWork(item).planning||{});
  return V4218_CLASS_PLAN_DRAFTS[classId];
}
function v4218DraftPlan(item,reqId){
  const planning=v4218DraftPlanning(item?.id||'');
  planning[reqId] = {...v4218PlanDefaults(), ...(planning[reqId]||{})};
  return planning[reqId];
}
function v4218HasClassPlanPending(classId=activeClassId){ return !!classId && V4218_DIRTY_CLASS_IDS.has(String(classId)); }
function v4218AnyClassPlanPending(){ return V4218_DIRTY_CLASS_IDS.size>0; }
function v4218UpdatePlanNotice(){
  const dirty=v4218HasClassPlanPending(activeClassId);
  const box=document.getElementById('class_plan_pending_notice');
  if(box){
    box.classList.toggle('warn',dirty);
    const text=box.querySelector('[data-role="state"]');
    if(text)text.innerHTML=dirty?'<b>Cambios pendientes.</b> Llena todos los campos que necesites. No se enviara al servidor hasta pulsar Guardar avance.':'Puedes llenar varias columnas sin salir de esta pantalla. El servidor se actualiza solo cuando pulses Guardar avance.';
  }
  const save=document.getElementById('class_plan_save_all'); if(save)save.disabled=!dirty;
  const discard=document.getElementById('class_plan_discard_all'); if(discard)discard.disabled=!dirty;
}

const V4218_BASE_CLASS_PLAN = classPlan;
classPlan = function classPlanV4218(item,reqId){
  if(item&&activeClassSection==='planning'&&V4218_CLASS_PLAN_DRAFTS[item.id])return v4218DraftPlan(item,reqId);
  return V4218_BASE_CLASS_PLAN(item,reqId);
};

const V4218_BASE_SAVE_CLASS_PLAN_FIELD = saveClassPlanField;
saveClassPlanField = async function saveClassPlanFieldV4218(id,reqId,field,val){
  const item=accessibleClasses().find(x=>String(x.id)===String(id));
  if(!item)return;
  if(activeClassSection!=='planning')return V4218_BASE_SAVE_CLASS_PLAN_FIELD(id,reqId,field,val);
  const plan=v4218DraftPlan(item,reqId);
  plan[field]=val;
  V4218_DIRTY_CLASS_IDS.add(String(id));
  v4218UpdatePlanNotice();
};

async function v4218SaveClassPlanDraft(classId=activeClassId,options={}){
  classId=String(classId||'');
  if(!v4218HasClassPlanPending(classId)){ if(!options.quiet)toast('No hay cambios pendientes para guardar.'); return false; }
  const item=accessibleClasses().find(x=>String(x.id)===classId)||v4218ClassById(classId);
  const draft=V4218_CLASS_PLAN_DRAFTS[classId];
  if(!item||!draft)return false;
  const work=classWork(item);
  work.planning=v4218Clone(draft);
  item.updatedAt=isoNow();
  delete V4218_CLASS_PLAN_DRAFTS[classId];
  V4218_DIRTY_CLASS_IDS.delete(classId);
  await persist(true,{action:'Planificacion de clase guardada',entity:item.id,detail:'bloque completo'});
  if(!options.quiet)toast('Planificacion guardada y enviada al servidor.');
  if(options.render!==false&&currentPage==='classes'&&activeClassId===classId)renderClassWorkspace();
  return true;
}
function v4218DiscardClassPlanDraft(classId=activeClassId,options={}){
  classId=String(classId||'');
  delete V4218_CLASS_PLAN_DRAFTS[classId];
  V4218_DIRTY_CLASS_IDS.delete(classId);
  if(!options.quiet)toast('Cambios descartados.');
  if(options.render!==false&&currentPage==='classes'&&activeClassId===classId)renderClassWorkspace();
}
function v4218RunContinuation(token){
  const next=V4218_PENDING_CONTINUATIONS.get(token);
  V4218_PENDING_CONTINUATIONS.delete(token);
  if(typeof next==='function')next();
}
async function v4218ResolveClassPlanLeave(token,decisión){
  const classId=String(activeClassId||'');
  if(decisión==='cancel'){ closeModal(); return; }
  if(decisión==='save'){
    const ok=await v4218SaveClassPlanDraft(classId,{quiet:true,render:false});
    if(!ok&&v4218HasClassPlanPending(classId))return toast('No se pudo guardar la planificacion. Intenta nuevamente.');
    closeModal();
    v4218RunContinuation(token);
    toast('Planificacion guardada.');
    return;
  }
  if(decisión==='discard'){
    v4218DiscardClassPlanDraft(classId,{quiet:true,render:false});
    closeModal();
    v4218RunContinuation(token);
    toast('Saliste sin guardar los cambios de planificacion.');
  }
}
function v4218ConfirmClassPlanLeave(continuation){
  if(!v4218HasClassPlanPending(activeClassId))return false;
  const token='leave_'+Date.now()+'_'+Math.random().toString(16).slice(2);
  V4218_PENDING_CONTINUATIONS.set(token,continuation);
  showModal(`<div class="modal small"><div class="modal-head"><div><h3>Guardar registro?</h3><p>Hay datos escritos en esta planificacion que todavia no fueron enviados al servidor.</p></div><button class="modal-close" onclick="v4218ResolveClassPlanLeave('${token}','cancel')">x</button></div><div class="modal-body"><div class="notice warn"><b>Antes de salir:</b> puedes guardar todo el avance junto, salir sin guardar o cancelar para seguir llenando los cuadros.</div></div><div class="modal-foot"><button class="btn ghost" onclick="v4218ResolveClassPlanLeave('${token}','cancel')">Cancelar y seguir</button><button class="btn red" onclick="v4218ResolveClassPlanLeave('${token}','discard')">Salir sin guardar</button><button class="btn primary" onclick="v4218ResolveClassPlanLeave('${token}','save')">Guardar avance y salir</button></div></div>`);
  return true;
}
function v4218MaybeConfirmPlanningExit(continuation){
  if(currentPage==='classes'&&activeClassSection==='planning'&&v4218HasClassPlanPending(activeClassId)){
    v4218ConfirmClassPlanLeave(continuation);
    return true;
  }
  return false;
}

const V4218_BASE_OPEN_CLASS_WORKSPACE = openClassWorkspace;
openClassWorkspace = function openClassWorkspaceV4218(id,section='dashboard'){
  if(v4218MaybeConfirmPlanningExit(()=>V4218_BASE_OPEN_CLASS_WORKSPACE(id,section)))return;
  return V4218_BASE_OPEN_CLASS_WORKSPACE(id,section);
};

const V4218_BASE_RENDER_CLASSES = renderClasses;
renderClasses = function renderClassesV4218(){
  if(v4218MaybeConfirmPlanningExit(()=>V4218_BASE_RENDER_CLASSES()))return;
  return V4218_BASE_RENDER_CLASSES();
};

const V4218_BASE_GO = go;
go = function goV4218(page){
  if(v4218MaybeConfirmPlanningExit(()=>V4218_BASE_GO(page)))return;
  return V4218_BASE_GO(page);
};

const V4218_BASE_RENDER_CLASS_WORKSPACE = renderClassWorkspace;
renderClassWorkspace = function renderClassWorkspaceV4218(){
  V4218_BASE_RENDER_CLASS_WORKSPACE();
  if(activeClassSection!=='planning')return;
  const body=document.querySelector('.class-work-body'); if(!body)return;
  const subtitle=body.querySelector('.page-head .subtitle');
  if(subtitle)subtitle.textContent='Llena los cuadros que necesites. Nada se registra en el servidor hasta pulsar Guardar avance.';
  const tableCard=body.querySelector('.class-table-card');
  if(tableCard&&!document.getElementById('class_plan_pending_notice')){
    tableCard.insertAdjacentHTML('beforebegin',`<section id="class_plan_pending_notice" class="notice class-plan-sticky-actions" style="margin:12px 0"><div data-role="state">Puedes llenar varias columnas sin salir de esta pantalla. El servidor se actualiza solo cuando pulses Guardar avance.</div><div class="actions" style="margin-top:10px"><button id="class_plan_save_all" class="btn primary" onclick="v4218SaveClassPlanDraft()" disabled>Guardar avance</button><button id="class_plan_discard_all" class="btn ghost" onclick="v4218DiscardClassPlanDraft()" disabled>Descartar cambios</button></div></section>`);
  }
  v4218UpdatePlanNotice();
};

const V4218_BASE_SAVE_REQUIREMENT = saveRequirement;
saveRequirement = async function saveRequirementV4218(send=false){
  if(send){
    const status=v3EnsureProgramProgress(modalOwnerId,v3ModalProgramId).status[modalRequirementId];
    if(status==='in_review')return toast('Este requisito ya fue enviado a revision. Espera la respuesta del Tutor o Administrador, o cancela el envio si necesitas corregir.');
    if(status==='approved')return toast('Este requisito ya esta revisado. No se puede enviar nuevamente.');
  }
  return V4218_BASE_SAVE_REQUIREMENT(send);
};

