const V4220_CLASS_TRACKING_DRAFTS = {};
const V4220_DIRTY_TRACKING_CLASS_IDS = new Set();

function v4220Clone(value){return value==null?value:structuredClone(value);}
function v4220TrackingDraft(classId){
  const item=v4218ClassById(classId); if(!item)return{};
  classId=String(classId||'');
  if(!V4220_CLASS_TRACKING_DRAFTS[classId])V4220_CLASS_TRACKING_DRAFTS[classId]=v4220Clone(classWork(item).tracking||{});
  return V4220_CLASS_TRACKING_DRAFTS[classId];
}
function v4220HasClassTrackingPending(classId=activeClassId){return !!classId&&V4220_DIRTY_TRACKING_CLASS_IDS.has(String(classId));}
function v4220UpdateTrackingNotice(){
  const dirty=v4220HasClassTrackingPending(activeClassId),box=document.getElementById('class_tracking_pending_notice');
  if(box){box.classList.toggle('warn',dirty);const text=box.querySelector('[data-role="state"]');if(text)text.innerHTML=dirty?'<b>Cambios pendientes.</b> Puedes marcar varios checks y guardar al final.':'Marca varios checks sin cerrar la pantalla. El servidor se actualiza al pulsar Guardar avance.';}
  const save=document.getElementById('class_tracking_save_all');if(save)save.disabled=!dirty;
  const discard=document.getElementById('class_tracking_discard_all');if(discard)discard.disabled=!dirty;
}
const V4220_BASE_CLASS_TRACK_COMPLETE = classTrackComplete;
