function v4220InstallClassTableTopScrollbar(){
  for(const wrap of document.querySelectorAll('.class-table-wrap')){
    if(wrap.previousElementSibling?.classList?.contains('class-table-top-scroll'))continue;
    const top=document.createElement('div');top.className='class-table-top-scroll';top.innerHTML='<div></div>';wrap.parentNode.insertBefore(top,wrap);
    const inner=top.firstElementChild;const sync=()=>{inner.style.width=`${wrap.scrollWidth}px`;};sync();setTimeout(sync,60);
    top.addEventListener('scroll',()=>{wrap.scrollLeft=top.scrollLeft;});wrap.addEventListener('scroll',()=>{top.scrollLeft=wrap.scrollLeft;});
  }
}
