function sgl421ClassRequirementsFromForm(){ return []; }
function sgl421EmptyClassWork(){ return {members:[],planning:{},attendance:[],tracking:{}}; }
function openClassEditor(id=''){
  if (!sgl421CanManageClassCatalog()) return toast('No tienes permiso para administrar clases.');
  const item = id ? (database.classes || []).find(entry => entry.id === id) : null;
  showModal(`<div class="modal small"><div class="modal-head"><div><h3>${item?'Editar clase':'Crear clase'}</h3><p>El rol Instructor puede crear, editar e inactivar clases. No se borran datos.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveClassEditor(event,'${esc(id)}')"><div class="modal-body"><label class="field-group">Clase regular / nombre<input id="class_edit_regular" class="field" required value="${esc(item?.regular || '')}"></label><label class="field-group">Clase avanzada / complemento<input id="class_edit_advanced" class="field" value="${esc(item?.advanced || '')}"></label><label class="field-group">Edad<input id="class_edit_age" class="field" type="number" min="0" max="99" value="${esc(item?.age || '')}"></label>${item?`<label class="choice"><input id="class_edit_active" type="checkbox" ${item.active!==false?'checked':''}> Clase activa</label>`:''}<div class="notice">Eliminar significa inactivar. La clase, miembros, asistencia y seguimiento quedan guardados.</div></div><div class="modal-foot"><button type="button" class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar clase</button></div></form></div>`);
}
async function saveClassEditor(event,id=''){
  event.preventDefault();
  if (!sgl421CanManageClassCatalog()) return;
  let item = id ? (database.classes || []).find(entry => entry.id === id) : null;
  if (!item) {
    item = {id:newId('class'),custom:true,catalogKey:null,assignedUserIds:[],requirements:sgl421ClassRequirementsFromForm(),work:sgl421EmptyClassWork(),createdAt:isoNow(),active:true};
    database.classes.push(item);
  }
  item.regular = value('class_edit_regular').trim();
  item.advanced = value('class_edit_advanced').trim();
  item.name = item.advanced ? `${item.regular} + ${item.advanced}` : item.regular;
  item.age = value('class_edit_age') || '';
  if (id) item.active = document.getElementById('class_edit_active')?.checked !== false;
  item.updatedAt = isoNow();
  classWork(item);
  await persist(true,{action:id?'Clase editada':'Clase creada',entity:item.id,detail:item.name});
  closeModal(); renderClasses(); toast('Clase guardada.');
}
async function setClassActive(classId,active){
  if (!sgl421CanManageClassCatalog()) return;
  const item = (database.classes || []).find(entry => entry.id === classId);
  if (!item) return;
  if (!active && !confirm(`¿Inactivar ${item.regular}? Los datos se conservan.`)) return;
  item.active = !!active;
  item.updatedAt = isoNow();
  await persist(true,{action:active?'Clase reactivada':'Clase inactivada',entity:item.id,detail:item.name || item.regular});
  renderClasses(); toast(active?'Clase reactivada.':'Clase inactivada.');
}

