const SGL421_BASE_DELETE_CLASS_MEMBER = deleteClassMember;
deleteClassMember = async function deleteClassMemberSGL421(memberId){
  const item = accessibleClasses().find(x => x.id === activeClassId);
  if (!item) return;
  const member = classWork(item).members.find(x => x.id === memberId);
  if (!member) return;
  const user = currentUser();
  // SGL 5.0.74: el Administrador elimina definitivamente de la clase.
  // Instructores asignados conservan la ruta segura de inactivación.
  if (user?.role === 'admin') return SGL421_BASE_DELETE_CLASS_MEMBER(memberId);
  const canSoftDelete = item.assignedUserIds?.includes(user.id);
  if (!canSoftDelete) return toast('No tienes permiso para eliminar miembros de esta clase.');
  if (!confirm(`¿Inactivar a ${member.fullName}? Sus datos y avances se conservarán.`)) return;
  member.active = false;
  member.inactivatedAt = isoNow();
  member.inactivatedBy = user.id;
  await persist(true,{action:'Miembro de clase inactivado',entity:item.id,detail:member.fullName});
  renderClassWorkspace(); toast('Miembro inactivado.');
};

