/* SGL 4.2.25 - ajuste adicional: Director/Director Asociado por club, sin edicion destructiva. */
function sgl421bIsDirector(user=currentUser()){ return ['director','director_asociado'].includes(sgl548CanonicalRole(user?.role)); }
function sgl421bSameMemberClub(user,member){ return !!user?.clubId && (member?.clubId === user.clubId || member?.createdBy === user.id); }
(function installSGL421bClassPolicy(){
  const previous = ClassPolicy;
  const normalizeClasses = classes => Array.isArray(classes) ? classes : [];
  const assignedIds = item => Array.isArray(item?.assignedUserIds) ? item.assignedUserIds : [];
  const inactiveUser = user => !user || user.active === false || ['inactive','archived'].includes(user.accountState || 'active');
  const classCatalogManager = user => !!user && ['admin','instructor'].includes(user.role);
  const classScopedViewer = user => !!user && sgl421bIsDirector(user) && !!user.clubId;
  function visibleClasses(user,classes){
    const items = normalizeClasses(classes);
    if (inactiveUser(user)) return [];
    if (classCatalogManager(user)) return items;
    if (classScopedViewer(user)) return items.filter(item => item.active !== false);
    if (!['aspirant','pastor_aspirant'].includes(user.role)) return [];
    return items.filter(item => item.active !== false && assignedIds(item).includes(user.id));
  }
  function canAccessClasses(user,classes){
    if (inactiveUser(user)) return false;
    if (classCatalogManager(user) || classScopedViewer(user)) return true;
    if (!['aspirant','pastor_aspirant'].includes(user.role)) return false;
    return visibleClasses(user,classes).length > 0;
  }
  ClassPolicy = Object.freeze({...previous,visibleClasses,canAccessClasses,classCatalogManager,classScopedViewer});
  window.ClassPolicy = ClassPolicy;
})();

/* SGL 5.0.9 Ajustes Líder v3 · informe compacto y materiales bajo demanda */
(()=>{
  let materialRefreshPromise=null;

  async function sglLeaderMaterialSource(item){
    if(!item)return null;
    const locate=async()=>{
      const file=item?.fileId?await fileGet(String(item.fileId)):null;
      const source=file?.dataUrl||item.dataUrl||'';
      return source?{file,source}:null;
    };
    let found=await locate();
    if(found||!REMOTE_WEB||!navigator.onLine)return found;
    const token=database?.settings?.serverToken||'';
    if(!token||typeof sglRefreshRemoteFilesAfterLogin!=='function')return null;
    if(!materialRefreshPromise){
      materialRefreshPromise=Promise.resolve(sglRefreshRemoteFilesAfterLogin(token)).finally(()=>{materialRefreshPromise=null;});
    }
    toast('Descargando el material del servidor…');
    await materialRefreshPromise;
    return locate();
  }
  window.sglLeaderMaterialSource=sglLeaderMaterialSource;

  const baseDownloadMaterial=typeof downloadMaterial==='function'?downloadMaterial:null;
  if(baseDownloadMaterial){
    downloadMaterial=async function downloadMaterialLeaderV3(id){
      const item=accessibleMaterials().find(material=>material.id===id);
      if(!item||item.url)return baseDownloadMaterial.call(this,id);
      const resolved=await sglLeaderMaterialSource(item);
      if(!resolved)return toast(navigator.onLine?'El servidor no tiene el archivo asociado a este material. Pide al Administrador que vuelva a adjuntarlo.':'Este material todavía no está disponible sin conexión. Conéctate una vez para descargarlo.');
      const blob=await (await fetch(resolved.source)).blob();
      const result=await saveBlobWithDialog(resolved.file?.name||item.fileName||'Material',blob,'Todos los archivos|*.*');
      if(result?.ok)toast(`Material guardado en ${result.path}.`);
    };
    window.downloadMaterial=downloadMaterial;
  }

  const basePreviewMaterial=typeof previewMaterial==='function'?previewMaterial:null;
  if(basePreviewMaterial){
    previewMaterial=async function previewMaterialLeaderV3(id){
      const item=accessibleMaterials().find(material=>material.id===id);
      if(!item||item.url)return basePreviewMaterial.call(this,id);
      const resolved=await sglLeaderMaterialSource(item);
      if(!resolved)return toast(navigator.onLine?'El material está publicado, pero el archivo no existe en el servidor. El Administrador debe volver a adjuntarlo.':'Sin conexión: abre este material una vez con Internet para conservarlo en el dispositivo.');
      return basePreviewMaterial.call(this,id);
    };
    window.previewMaterial=previewMaterial;
  }

  function sglLeaderPatchRequirementUi(){
    const modal=document.querySelector('#modal_root .modal');
    const editor=document.getElementById('req_text');
    if(!modal||!editor)return;
    modal.classList.add('sgl-leader-report-modal');
    modal.querySelector('.document-header')?.classList.add('sgl-leader-document-header');
    modal.querySelector('.requirement-official-block')?.classList.add('sgl-leader-requirement-block');
    const toolbar=modal.querySelector('.rich-toolbar');
    const dictation=toolbar?.querySelector('.sgl500-dictation-btn');
    if(dictation&&!modal.querySelector('.sgl-leader-dictation-fab')){
      dictation.classList.add('sgl-leader-dictation-fab');
      dictation.title='Iniciar o detener dictado por voz';
      dictation.setAttribute('aria-label','Dictado por voz');
      modal.appendChild(dictation);
    }
    const head=modal.querySelector('.modal-head');
    if(head&&!head.querySelector('.sgl-leader-pdf-shortcut')&&typeof modalRequirementId!=='undefined'){
      const close=head.querySelector('.modal-close');
      close?.insertAdjacentHTML('beforebegin',`<button type="button" class="btn ghost small sgl-leader-pdf-shortcut" onclick="previewRequirementPdf('${esc(modalRequirementId)}')">Vista PDF</button>`);
    }
  }

  if(typeof openRequirement==='function'){
    const baseOpenRequirement=openRequirement;
    openRequirement=async function openRequirementLeaderV3(...args){
      const result=await baseOpenRequirement.apply(this,args);
      sglLeaderPatchRequirementUi();
      return result;
    };
    window.openRequirement=openRequirement;
  }

  window.addEventListener('sgl-remote-files-ready',()=>{
    if(document.querySelector('.material-folders'))renderMaterials?.();
  });
})();

