const SGL421B_BASE_RENDER_TUTORS = renderTutors;
renderTutors = function renderTutorsSGL421B(){
  const actor = currentUser();
  if (!sgl421bIsDirector(actor)) return SGL421B_BASE_RENDER_TUTORS();
  setTop('Instructores','Club');
  const instructors = (database.users || []).filter(user => user.role === 'instructor' && user.clubId === actor.clubId && (user.accountState || 'active') === 'active');
  const rows = instructors.map(item => `<article class="card tutor-card-compact"><div class="tutor-card-head"><span class="avatar tutor-avatar">${avatarMarkup(item)}</span><div><h3>${esc(item.fullName)}</h3><p>${esc(item.email || item.username || '')}</p><span class="chip blue">Instructor del club</span></div><span class="chip">Sin edicion</span></div></article>`).join('');
  setContent(`<div class="page-head"><div><div class="eyebrow">Alcance del club</div><h1 class="page-title">Instructores</h1><p class="subtitle">Puedes crear Instructores conectados a tu Club. La edicion de cuentas existentes queda reservada al Administrador.</p></div><button class="btn primary" onclick="openDirectorInstructor()">Crear Instructor</button></div><div class="tutor-grid-compact">${rows || '<div class="card empty">Todavia no hay Instructores en tu Club.</div>'}</div>`);
};

function openDirectorInstructor(){
  const actor = currentUser();
  if (!sgl421bIsDirector(actor)) return;
  if (!actor.clubId) return toast('Este Director debe estar conectado a un Club registrado.');
  showModal(`<div class="modal small"><div class="modal-head"><div><h3>Crear Instructor</h3><p>Quedara conectado automaticamente a tu Club.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveDirectorInstructor(event)"><div class="modal-body"><label class="field-group full">Nombres y Apellidos Completos<input id="director_instructor_name" class="field" required autocomplete="off"></label><label class="field-group">Correo<input id="director_instructor_email" class="field" type="email" required></label><label class="field-group">Usuario<input id="director_instructor_username" class="field" required></label><label class="field-group">Telefono celular<input id="director_instructor_phone" class="field" type="tel"></label><label class="field-group full">Contrasena temporal<input id="director_instructor_password" type="password" minlength="8" class="field" required></label><div class="notice">Rol: <b>Instructor</b>. Club: <b>${esc(clubFor(actor)?.name || 'Club asignado')}</b>.</div><div id="director_instructor_error" class="error"></div></div><div class="modal-foot"><button type="button" class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar Instructor</button></div></form></div>`);
}
async function saveDirectorInstructor(event){
  event.preventDefault();
  const actor = currentUser();
  if (!sgl421bIsDirector(actor) || !actor.clubId) return;
  const email = normalize(value('director_instructor_email'));
  const username = normalize(value('director_instructor_username'));
  const duplicate = (database.users || []).find(item => normalize(item.email) === email || normalize(item.username) === username);
  if (duplicate) return setText('director_instructor_error','El correo o usuario ya pertenece a otra cuenta.');
  const password = value('director_instructor_password');
  const item = {id:newId('usr'),createdAt:isoNow(),photo:'',drive:null,theme:'classic_blue',fullName:value('director_instructor_name').trim(),email,username,phone:value('director_instructor_phone').trim(),role:'instructor',clubId:actor.clubId,accountState:'active',active:true,createdBy:actor.id,reportFont:database.settings.reportFont || 'Arial',password:await passwordRecord(password)};
  database.users.push(item);
  rememberAutocompleteName(item.fullName);
  await persist(true,{action:'Instructor creado por Director',entity:item.id,detail:item.fullName});
  closeModal(); renderTutors(); toast('Instructor creado.');
}

