async function makeSquareProfilePhotoSGL4222(file){
  if(!file)throw new Error('No se recibio archivo.');
  const name=String(file.name||'').toLowerCase();
  if(/\.(heic|heif)$/.test(name))throw new Error('El telefono envio HEIC/HEIF. Cambia la camara a JPG o elige una foto JPG/PNG.');
  let source=null,image=null,bitmap=null;
  try{
    if('createImageBitmap' in window){
      bitmap=await createImageBitmap(file,{imageOrientation:'from-image'}).catch(()=>null);
    }
    if(bitmap){
      const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=600;canvas.height=600;
      const scale=Math.max(600/bitmap.width,600/bitmap.height),w=bitmap.width*scale,h=bitmap.height*scale;
      ctx.fillStyle='#fff';ctx.fillRect(0,0,600,600);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(bitmap,(600-w)/2,(600-h)/2,w,h);bitmap.close?.();
      return canvas.toDataURL('image/jpeg',.9);
    }
    source=URL.createObjectURL(file);image=await loadImage(source);
    const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=600;canvas.height=600;
    const scale=Math.max(600/image.naturalWidth,600/image.naturalHeight),w=image.naturalWidth*scale,h=image.naturalHeight*scale;
    ctx.fillStyle='#fff';ctx.fillRect(0,0,600,600);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(image,(600-w)/2,(600-h)/2,w,h);
    return canvas.toDataURL('image/jpeg',.9);
  }finally{if(source)URL.revokeObjectURL(source);}
}
makeSquareProfilePhoto = makeSquareProfilePhotoSGL4222;
function sgl4222PatchPhotoInput(input){
  if(!input||input.dataset.sgl4222Photo)return;input.dataset.sgl4222Photo='1';
  input.setAttribute('accept','image/jpeg,image/png,image/webp,image/*');
  input.addEventListener('change',()=>{
    const file=input.files?.[0];if(!file)return;
    const nameTarget=document.getElementById(input.id==='user_photo'?'user_photo_name':'class_member_photo_name');
    if(nameTarget)nameTarget.textContent=file.name||'Foto seleccionada desde el celular';
    const preview=document.getElementById(input.id==='user_photo'?'user_photo_preview':'class_member_photo_preview');
    if(preview&&file.type.startsWith('image/')){const url=URL.createObjectURL(file);preview.innerHTML=`<img src="${url}" alt="Vista previa">`;preview.querySelector('img')?.addEventListener('load',()=>URL.revokeObjectURL(url),{once:true});}
  });
}
function sgl4222PrepareMobilePhotoInputs(){
  for(const input of document.querySelectorAll('input[type="file"][accept*="image"]'))sgl4222PatchPhotoInput(input);
  const userInput=document.getElementById('user_photo');
  if(userInput&&!document.getElementById('user_photo_mobile_button')){
    const host=userInput.closest('.field-group, .actions, label')||userInput.parentElement;
    host?.insertAdjacentHTML('beforeend',`<button id="user_photo_mobile_button" type="button" class="btn ghost small" onclick="document.getElementById('user_photo')?.click()">Elegir foto del celular</button><small id="user_photo_name" class="muted">JPG, PNG o WEBP.</small>`);
    const av=host?.closest('.field-group')?.querySelector('.avatar');if(av&&!av.id)av.id='user_photo_preview';
  }
  const memberInput=document.getElementById('class_member_photo');
  if(memberInput&&!document.getElementById('class_member_photo_mobile_button')){
    const host=memberInput.closest('.field-group, .actions, label')||memberInput.parentElement;
    host?.insertAdjacentHTML('beforeend',`<button id="class_member_photo_mobile_button" type="button" class="btn ghost small" onclick="document.getElementById('class_member_photo')?.click()">Elegir foto del celular</button>`);
  }
}
