  const local={id:`local_${clientMessageId}`,clientMessageId,senderId:user.id,senderName:user.fullName,senderRole:user.role,recipientId:ids[0],recipientIds:ids,recipientNames:ids.map(id=>userById(id)?.fullName||id),conversationId:SGL4222_CONNECTED_ROOM_ID,text,sentAt:isoNow(),readAt:'',pending:true};
  v4EnsureReliableState();database.messageCache.push(local);database.messageOutbox.push({senderId:user.id,clientMessageId,recipientId:ids[0],recipientIds:ids,conversationId:SGL4222_CONNECTED_ROOM_ID,text,createdAt:local.sentAt});
