function sgl426Cell(value){const text=String(value??'').replace(/^\uFEFF/,'').trim();if(/^[+-]?\d+(?:\.\d+)?(?:e[+-]?\d+)?$/i.test(text)){const n=Number(text);if(Number.isFinite(n)&&Number.isInteger(n))return String(n);if(/^\d+\.0+$/.test(text))return text.replace(/\.0+$/,'');}return text;}
function sgl426Phone(value){const text=sgl426Cell(value);return /^\d+\.0$/.test(text)?text.replace(/\.0$/,''):text;}
function sgl426ExcelSerialDate(numberValue){const n=Number(numberValue);if(!Number.isFinite(n)||n<=0)return '';const ms=Math.round((n-25569)*86400*1000);const d=new Date(ms);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10);}
function sgl426Date(value){
  const raw=sgl426Cell(value);if(!raw)return '';
  if(/^\d+(?:\.\d+)?$/.test(raw)&&Number(raw)>20000)return sgl426ExcelSerialDate(raw);
  const iso=raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);if(iso)return `${iso[1]}-${iso[2].padStart(2,'0')}-${iso[3].padStart(2,'0')}`;
  const latam=raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})$/);if(latam){let year=latam[3];if(year.length===2)year=`20${year}`;return `${year}-${latam[2].padStart(2,'0')}-${latam[1].padStart(2,'0')}`;}
  const d=new Date(raw);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10);
}
function sgl426HeaderKey(header){
  const key=sgl426Key(header);
  if(!key)return '';
  if(sgl501IsBlockedExcelHeader(key))return '';
  if((key.includes('nombres')&&key.includes('apellidos'))||key==='nombre'||key.includes('nombre completo'))return 'nombre';
  if(key.includes('correo'))return 'correo';
  if(key.includes('nombre de usuario')||key==='usuario'||(key.includes('usuario')&&key.includes('desea')))return 'usuario';
  if(key.includes('fecha')&&key.includes('nacimiento'))return 'fecha_nacimiento';
  if(key.includes('telefono')||key.includes('celular'))return 'telefono';
  if(key==='club'||key.includes('club al que pertenece'))return 'club';
  if(key.includes('distrito'))return 'distrito_misionero';
  if(key==='region'||key.includes('region'))return 'region';
  if(key.includes('iglesia')&&key.includes('asiste'))return 'iglesia';
  if(key.includes('cargo')&&key.includes('club'))return 'cargo_club';
  if(key.includes('cargo')&&key.includes('iglesia'))return 'cargo_iglesia';
  if(key==='mision'||(key.includes('mision')&&!key.includes('distrito')))return 'mision';
  if(key==='union'||key.includes('union'))return 'union';
  if(key.includes('clases')&&key.includes('ensena'))return 'clases_ensena';
  if(key.includes('tarjeta')||key.includes('modulo')||key.includes('programa'))return 'tarjeta';
  if(key.includes('tutor')&&key.includes('correo'))return 'tutor_correo';
  if(key.includes('compromiso')||key.includes('sugerencias')||key.includes('observaciones'))return 'observaciones';
  return key.replace(/\s+/g,'_');
}
function sgl426RecordFromRow(headers,cells){
  const record={};
  headers.forEach((header,index)=>{const canonical=sgl426HeaderKey(header);if(canonical&&!record[canonical])record[canonical]=sgl426Cell(cells[index]);});
  record.nombre=record.nombre||'';record.correo=normalize(record.correo||'');record.usuario=normalize(record.usuario||'');
  record.fecha_nacimiento=sgl426Date(record.fecha_nacimiento);record.telefono=sgl426Phone(record.telefono);
  return record;
}
async function sgl426RowsFromXlsx(file){
  const endpoints=REMOTE_WEB?['/api/import/xlsx']:['/api/local/import/xlsx','/api/import/xlsx'];
  let lastError=null;
  for(const endpoint of endpoints){
    try{
      const form=new FormData();form.append('file',file,file.name||'import.xlsx');
      const headers={};if(endpoint==='/api/import/xlsx'&&database?.settings?.serverToken)headers.Authorization=`Bearer ${database.settings.serverToken}`;
      const response=await fetch(endpoint,{method:'POST',headers,body:form,cache:'no-store'});
      const payload=await response.json().catch(()=>({}));
      if(!response.ok||!payload?.ok)throw new Error(payload?.error||`HTTP ${response.status}`);
      return Array.isArray(payload.rows)?payload.rows:[];
    }catch(error){lastError=error;}
  }
  throw lastError||new Error('No se pudo leer el archivo Excel.');
}
async function sgl426RowsFromFile(file){
  const lower=String(file?.name||'').toLowerCase();
  if(lower.endsWith('.xlsx')||lower.endsWith('.xls'))return sgl426RowsFromXlsx(file);
  return parseCsv(await file.text());
}
function sgl426FindOrCreateClub(record){
  const name=sgl426Cell(record.club);if(!name)return {club:null,created:false};
  let club=(database.clubs||[]).find(item=>sgl426Key(item.name)===sgl426Key(name));
  if(club)return {club,created:false};
  club={id:newId('club'),name,church:record.iglesia||'',missionaryDistrict:record.distrito_misionero||'',district:record.distrito_misionero||'',region:record.region||'',mission:record.mision||'',union:record.union||'',active:true,logo:'',mapsUrl:'',createdAt:isoNow(),createdBy:currentUser()?.id||'',source:'excel_import'};
  database.clubs ||= [];database.clubs.push(club);
  return {club,created:true};
}
function sgl426ProgramsFromRecord(record){
  const text=sgl426Key([record.tarjeta,record.modulo,record.programa].filter(Boolean).join(' '));
  const ids=[];
  if(text.includes('agrupada')||text.includes('clase agrupada'))ids.push('class_grouped');
  if(text.includes('musica')||text.includes('music'))ids.push('music_ministry');
  if(text.includes('master avanzado')||text.includes('maestro avanzado'))ids.push('guide_master_advanced');
  else if(text.includes('master')||text.includes('maestro'))ids.push('guide_master');
  else if(text.includes('guia mayor'))ids.push('guide_major');
  if(!ids.length)ids.push('class_grouped');
  return [...new Set(ids.filter(id=>v3ProgramDefinitions[id]))];
}
function sgl426AssignPrograms(user,programIds){
  user.importedProgramIds=[...new Set([...(user.importedProgramIds||[]),...programIds])];
  for(const programId of programIds){
    const module=v3ModuleRecord(programId);if(!module)continue;
    module.active=true;module.assignedUserIds=Array.isArray(module.assignedUserIds)?module.assignedUserIds:[];
    if(!module.assignedUserIds.includes(user.id))module.assignedUserIds.push(user.id);
    v3EnsureProgramProgress(user.id,programId);
  }
}
function sgl426AssignTeachingClasses(user,text){
  const source=sgl426Key(text);if(!source)return [];
  const matched=[];const currentCount=()=>database.classes.filter(item=>item.assignedUserIds?.includes(user.id)).length;
  for(const item of database.classes||[]){
    const labels=[item.id,item.name,item.regular,item.advanced,item.catalogKey].filter(Boolean).map(sgl426Key);
    if(labels.some(label=>label&&source.includes(label))){
      item.assignedUserIds=Array.isArray(item.assignedUserIds)?item.assignedUserIds:[];
      if(!item.assignedUserIds.includes(user.id)&&currentCount()<3){item.assignedUserIds.push(user.id);item.updatedAt=isoNow();matched.push(item.regular||item.name||item.id);}
    }
  }
  return matched;
}
function sgl426ProfilePanel(person,{compact=false}={}){
  if(!person)return '';
  const club=clubFor(person);
  const fields=[
    ['Correo',person.email],['Usuario',person.username],['Nacimiento',person.birthDate?String(person.birthDate).slice(5).split('-').reverse().join('/'):''],['Telefono',person.phone],['Club',club?.name],['Iglesia',person.church],['Cargo en el Club',person.clubPosition],['Cargo en la Iglesia',person.churchPosition],['Distrito Misionero',person.missionaryDistrict],['Region',person.region],['Mision',person.mission],['Union',person.union],['Tarjeta',person.excelCard||person.importedCard],['Clases que ensena',person.classTeaching],['Compromiso / sugerencias',person.commitment]
  ].filter(([,value])=>sgl426Cell(value));
  if(!fields.length)return '';
  return `<section class="card sgl426-profile-panel ${compact?'compact':''}"><div class="card-head"><div><h3>Perfil del Aspirante</h3><p class="subtitle" style="margin:0">Datos importados y visibles en los modulos asignados.</p></div><span class="chip blue">${(person.importedProgramIds||v3AssignedProgramIds(person)).map(id=>v3Program(id).menu_label||v3Program(id).name).join(' · ')||'Perfil'}</span></div><div class="sgl426-profile-grid">${fields.map(([label,value])=>`<div><small>${esc(label)}</small><b>${esc(value)}</b></div>`).join('')}</div></section>`;
}
function sgl426DuplicateUser(record){
  const email=normalize(record.correo||''),username=normalize(record.usuario||''),nameKey=sgl426Key(record.nombre||'');
  return (database.users||[]).find(item=>email&&normalize(item.email)===email||username&&normalize(item.username)===username||nameKey&&sgl426Key(item.fullName)===nameKey);
}
async function sgl426MakeUserFromRecord(record){
  const role='aspirant';
  const {club,created:clubCreated}=sgl426FindOrCreateClub(record);
  const tutor=(database.users||[]).find(item=>item.role==='tutor'&&normalize(item.email)===normalize(record.tutor_correo||''));
  const baseUser=record.usuario||record.correo?.split('@')[0]||sgl426Key(record.nombre).replace(/\s+/g,'.')||`aspirante${Date.now()}`;
  let username=normalize(baseUser),suffix=2;while((database.users||[]).some(item=>normalize(item.username)===username)){username=normalize(`${baseUser}${suffix}`);suffix+=1;}
  const password=`SGL-${Math.random().toString(36).slice(2,8)}!`;
  const accountState='active';
  const item={id:newId('usr'),fullName:sgl426Cell(record.nombre),email:normalize(record.correo),username,birthDate:record.fecha_nacimiento||'',phone:record.telefono||'',role,clubId:club?.id||null,tutorId:tutor?.id||null,accountState,active:true,church:record.iglesia||'',clubPosition:record.cargo_club||'',churchPosition:record.cargo_iglesia||'',missionaryDistrict:record.distrito_misionero||'',region:record.region||'',mission:record.mision||'',union:record.union||'',reportFont:database.settings.reportFont||'Arial',theme:'classic_blue',createdAt:isoNow(),photo:'',drive:null,source:'excel_import',excelImportedAt:isoNow(),excelCard:record.tarjeta||'',classTeaching:record.clases_ensena||'',commitment:record.observaciones||'',password:await passwordRecord(password)};
  database.users.push(item);if(['aspirant','pastor_aspirant'].includes(role))ensureProgress(item.id);
  const programIds=['aspirant','pastor_aspirant'].includes(role)?sgl426ProgramsFromRecord(record):[];sgl426AssignPrograms(item,programIds);const teaching=['aspirant','pastor_aspirant'].includes(role)?sgl426AssignTeachingClasses(item,record.clases_ensena):[];
  return {item,clubCreated,programIds,teaching};
}
const SGL426_BASE_RENDER_USERS = renderUsers;
renderUsers = function renderUsersSGL426(){
  const result=SGL426_BASE_RENDER_USERS();
  const root=document.getElementById('content');if(root){
    root.innerHTML=root.innerHTML.replace(/Importar CSV/g,'Importar Excel/CSV').replace('accept=".csv,text/csv"','accept=".xlsx,.xls,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"');
    root.innerHTML=root.innerHTML.replace(/(<button class="btn ghost small" onclick="issueTemporaryPassword\('([^']+)'\)">Clave temporal<\/button>)/g,`$1<button class="btn red small" onclick="deleteUserPermanent('$2')">Eliminar</button>`);
    const notice=root.querySelector('.notice');if(notice)notice.innerHTML='Primero puedes inactivar o archivar una cuenta. Si necesitas limpieza definitiva, el Administrador puede usar <b>Eliminar</b>; el sistema conserva el historial de auditoria.';
  }
  return result;
};
importUsers = async function importUsersSGL426(file){
  if(!file||currentUser()?.role!=='admin')return;
  let rows=[];try{rows=await sgl426RowsFromFile(file);}catch(error){toast(`No se pudo importar: ${error.message}`);return;}
  if(rows.length<2)return toast('El archivo no contiene filas para importar.');
  const headers=rows[0];let created=0,skipped=0,clubs=0,modules=0;
  for(const cells of rows.slice(1)){
    if(!cells||!cells.some(cell=>sgl426Cell(cell)))continue;
    const record=sgl426RecordFromRow(headers,cells);
    if(!record.nombre||!record.correo){skipped+=1;continue;}
    if(sgl426DuplicateUser(record)){skipped+=1;continue;}
    const result=await sgl426MakeUserFromRecord(record);created+=1;if(result.clubCreated)clubs+=1;modules+=result.programIds.length;
    rememberAutocompleteName(result.item.fullName);
  }
  await persist(true,{action:'Aspirantes importados desde Excel/CSV',entity:'users',detail:`${created} creados; ${skipped} omitidos; ${clubs} clubes nuevos; ${modules} asignaciones de modulo`});
  renderUsers();toast(`${created} aspirante(s) creados. ${skipped} fila(s) omitidas por duplicado o dato incompleto.`);
};
async function deleteUserPermanent(id){
  const actor=currentUser();if(actor?.role!=='admin')return toast('Solo el Administrador puede eliminar Usuarios.');
  if(id===actor.id)return toast('No puedes eliminar tu propia cuenta activa.');
  const user=userById(id);if(!user)return toast('Usuario no encontrado.');
  const linked=(database.users||[]).filter(item=>sgl545HasTutor(item,id)).length;
  const linkedClasses=(database.classes||[]).filter(item=>(item.assignedUserIds||[]).includes(id));
  const detail=[linked?`${linked} Aspirante(s) quedaran sin Tutor asignado.`:'',linkedClasses.length?`Se quitara como Instructor de ${linkedClasses.length} clase(s). La informacion de esas clases se conservara completa.`:''].filter(Boolean).join('\n');
  if(!confirm(`Eliminar permanentemente a ${user.fullName}?${detail?`\n\n${detail}`:''}\n\nEsta accion no reemplaza datos de otros Lideres.`))return;
  for(const item of database.users||[])if(sgl545HasTutor(item,id)){item.tutorId=null;if(item.tutorByProgram)for(const p of Object.keys(item.tutorByProgram))if(item.tutorByProgram[p]===id)item.tutorByProgram[p]=null;}
  database.users=(database.users||[]).filter(item=>item.id!==id);
  for(const module of database.modules||[])module.assignedUserIds=(module.assignedUserIds||[]).filter(userId=>userId!==id);
  // Solo se retira la asignacion del Instructor. No se modifica item.work ni ningun dato pedagogico de la clase.
  for(const item of database.classes||[])item.assignedUserIds=(item.assignedUserIds||[]).filter(userId=>userId!==id);
  if(database.progress)delete database.progress[id];if(database.programProgress)delete database.programProgress[id];if(database.bibleYear)delete database.bibleYear[id];
  database.tasks=(database.tasks||[]).filter(task=>task.assigneeId!==id&&task.createdBy!==id);
  database.materials=(database.materials||[]).filter(material=>material.userId!==id&&material.createdBy!==id);
  await persist(true,{action:'Usuario eliminado',entity:id,detail:user.fullName});renderUsers();toast(linkedClasses.length?'Usuario eliminado y retirado de sus clases. La informacion de las clases se conservo.':'Usuario eliminado.');
}
