/* SGL 4.2.25 · hotfix conexion estable 2026-09-03
   Corrige el parpadeo por reintentos constantes y obliga al acceso remoto HTTPS
   a usar siempre el mismo origen que cargó la aplicación. Esto evita que un
   líder remoto intente sincronizar contra 127.0.0.1/http local y vea
   "Failed to fetch" aunque el servidor público sí esté abierto. */
function sgl427RemoteNormalizeSettings(){
  if(!REMOTE_WEB||!database)return;
  database.settings ||= {};
  database.settings.serverUrl = REMOTE_ORIGIN;
  database.settings.remoteAccess = true;
  database.settings.autoSync = database.settings.autoSync !== false;
}
const SGL427_BASE_MIGRATE_DATABASE = migrateDatabase;
