      if(send&&minimum&&selections.length<minimum)return toast(`Selecciona al menos ${minimum} opción(es).`);
      if(send&&maximum&&selections.length>maximum)return toast(`Selecciona como máximo ${maximum} opción(es).`);
      submission.text=editor.text;
