      const hasContent=!!editor.text||submission.attachmentIds.length>0||selections.length>0;
      if(!hasContent)return toast('Escribe el informe o agrega una evidencia antes de guardar.');
      if(send&&!submission.completionDate)return toast('Completa la fecha antes de enviar.');
      const aspirant=userById(modalOwnerId);if(aspirant&&value('req_font'))aspirant.reportFont=value('req_font');
      // 5.1: el guardado explícito desde la barra móvil siempre deja el requisito
      // como En desarrollo. Otros flujos de tareas conservan su estado histórico.
      const forceDevelopment=!send&&window.__sgl5098ForceDevelopmentOnSave===true;
      const taskDraftStatus=(!send&&!forceDevelopment&&typeof window.sgl5073TaskDraftStatus==='function')?window.sgl5073TaskDraftStatus(modalOwnerId,programId,modalRequirementId):'';
      progress.status[modalRequirementId]=send?'in_review':(forceDevelopment?'in_progress':(taskDraftStatus||'in_progress'));
      progress.updatedAt=isoNow();
      if(send)for(const task of (database.tasks||[]).filter(item=>item.assigneeId===modalOwnerId&&(item.programId||'class_grouped')===programId&&item.requirementId===modalRequirementId&&!item.presentedAt)){task.presentedAt=isoNow();task.updatedAt=isoNow();}
      database.sync={...(database.sync||{}),hasLocalDraft:false};
