/* SGL 5.0.5 · dictado continuo, vista PDF móvil y hoja completa de impresión */
(function(){
  const SGL505_VERSION='5.0.5';

  function sgl505IsMobile(){
    return matchMedia('(max-width: 760px)').matches||/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent||'');
  }

  function sgl505NormalizeSpeechText(text){
    return String(text||'').replace(/\s+/g,' ').trim();
  }
  function sgl505SpeechWords(text){
    return sgl505NormalizeSpeechText(text).split(' ').filter(Boolean);
  }
  function sgl505SpeechKey(word){
    return String(word||'').toLocaleLowerCase('es').replace(/^[¿¡"'“”‘’([{]+|[?!.,;:…"'“”‘’\])}]+$/g,'');
  }
  function sgl505SameWord(a,b){return sgl505SpeechKey(a)===sgl505SpeechKey(b);}
  function sgl505StartsWithWords(words,prefix){
    return prefix.length<=words.length&&prefix.every((word,index)=>sgl505SameWord(words[index],word));
  }
  function sgl505TailOverlap(existingWords,incomingWords){
    const max=Math.min(existingWords.length,incomingWords.length,40);
    for(let size=max;size>0;size-=1){
      let same=true;
      for(let i=0;i<size;i+=1){
        if(!sgl505SameWord(existingWords[existingWords.length-size+i],incomingWords[i])){same=false;break;}
      }
      if(same)return size;
    }
    return 0;
  }
  function sgl505DictationDelta(incoming,state={},existingText=''){
    const clean=sgl505NormalizeSpeechText(incoming);
    if(!clean)return '';
    const incomingWords=sgl505SpeechWords(clean);
    const previousWords=Array.isArray(state.previousFinalWords)?state.previousFinalWords:[];
    let cut=0;

    // Chrome Android a veces convierte "Hola" -> "Hola quiero" -> "Hola quiero realizar"
    // en varios resultados finales. Solo se toma el sufijo que creció.
    if(previousWords.length&&sgl505StartsWithWords(incomingWords,previousWords)){
      cut=previousWords.length;
    }else if(previousWords.length&&sgl505StartsWithWords(previousWords,incomingWords)){
      // El motor volvió a entregar una versión más corta del mismo resultado.
      cut=incomingWords.length;
    }else{
      const existingWords=sgl505SpeechWords(existingText);
      const overlap=sgl505TailOverlap(existingWords,incomingWords);
      // Un solapamiento de dos palabras es suficientemente fuerte. Para una sola
      // palabra, solo se elimina cuando todo el resultado es exactamente esa palabra.
      if(overlap>=2||(overlap===incomingWords.length&&incomingWords.length===1))cut=overlap;
    }

    state.previousFinalWords=incomingWords;
    const delta=incomingWords.slice(cut).join(' ').trim();
    return delta;
  }
  window.sgl505DictationDelta=sgl505DictationDelta;

  let sgl505SavedReportRange=null;
  function sgl505RememberReportCaret(){
    try{
      const editor=document.getElementById('req_text'),selection=window.getSelection();
      if(!editor||!selection?.rangeCount)return;
      const range=selection.getRangeAt(0);
      if(editor.contains(range.commonAncestorContainer))sgl505SavedReportRange=range.cloneRange();
    }catch{}
  }
  document.addEventListener('selectionchange',sgl505RememberReportCaret,{passive:true});

  function sgl505RestoreReportCaret(editor){
    try{
      if(!sgl505SavedReportRange||!editor.contains(sgl505SavedReportRange.commonAncestorContainer))return false;
      const selection=window.getSelection();
      selection.removeAllRanges();selection.addRange(sgl505SavedReportRange.cloneRange());
      return true;
    }catch{return false;}
  }
  function sgl505InsertDictationText(editor,text){
    const clean=sgl505NormalizeSpeechText(text);
    if(!clean||!editor?.isConnected)return;
    try{editor.focus({preventScroll:true});}catch{editor.focus();}
    sgl505RestoreReportCaret(editor);
    const insertion=`${clean} `;
    let inserted=false;
    try{inserted=document.execCommand('insertText',false,insertion);}catch{}
    if(!inserted){
      try{
        const selection=window.getSelection();
        let range=selection?.rangeCount?selection.getRangeAt(0):null;
        if(!range||!editor.contains(range.commonAncestorContainer)){
          range=document.createRange();range.selectNodeContents(editor);range.collapse(false);
        }
        range.deleteContents();
        const node=document.createTextNode(insertion);range.insertNode(node);range.setStartAfter(node);range.collapse(true);
        selection.removeAllRanges();selection.addRange(range);inserted=true;
      }catch{}
    }
    if(inserted){
      sgl505RememberReportCaret();
      try{if(typeof saveEmergencyDraft==='function')saveEmergencyDraft();}catch{}
      try{if(typeof sgl504ScheduleReportCaretVisible==='function')sgl504ScheduleReportCaretVisible(70);}catch{}
    }
  }

  function sgl505DictationStatusNode(){
    const button=document.querySelector('.sgl500-dictation-btn');
    if(!button)return null;
    let node=document.getElementById('sgl505_dictation_status');
    if(!node){
      node=document.createElement('span');node.id='sgl505_dictation_status';node.className='sgl505-dictation-status';
      button.insertAdjacentElement('afterend',node);
    }
    return node;
  }
  function sgl505UpdateDictationUi(active,message=''){
    document.querySelectorAll('.sgl500-dictation-btn').forEach(button=>{
      button.classList.toggle('is-listening',!!active);
      button.textContent=active?'⏹ Detener dictado':'🎙 Dictar';
      button.setAttribute('aria-pressed',active?'true':'false');
    });
    const node=sgl505DictationStatusNode();
    if(node){node.textContent=message||(active?'Escuchando…':'');node.classList.toggle('active',!!active);}
  }
  function sgl505SecureSpeechContext(){
    return window.isSecureContext||location.protocol==='https:'||location.protocol==='file:'||['localhost','127.0.0.1'].includes(location.hostname);
  }
  async function sgl505MicrophoneDenied(){
    if(!navigator.permissions?.query)return false;
    try{return (await navigator.permissions.query({name:'microphone'}))?.state==='denied';}catch{return false;}
  }
  async function sgl510MicrophonePreflight(){
    if(!navigator.mediaDevices?.getUserMedia)return {ok:true,label:'',limited:true};
    let stream=null;
    try{
      stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
      const track=stream.getAudioTracks?.()[0];
      if(!track||track.readyState!=='live')return {ok:false,message:'El navegador no recibió un micrófono activo. Revisa el dispositivo de entrada de Windows y vuelve a intentar.'};
      const label=String(track.label||'Micrófono del sistema').trim();
      return {ok:true,label};
    }catch(error){
      const code=String(error?.name||error?.message||'').toLowerCase();
      if(code.includes('notallowed')||code.includes('permission'))return {ok:false,message:'El navegador tiene bloqueado el micrófono. Abre el candado de esta página, permite Micrófono y vuelve a probar.'};
      if(code.includes('notfound')||code.includes('devicesnotfound'))return {ok:false,message:'Windows/navegador no encuentra ningún micrófono disponible.'};
      if(code.includes('notreadable')||code.includes('trackstart'))return {ok:false,message:'El micrófono existe, pero otra aplicación o Windows no permite abrirlo. Cierra otras aplicaciones que estén usando el micrófono y vuelve a probar.'};
      if(code.includes('security'))return {ok:false,message:'El navegador bloqueó el micrófono por seguridad. Abre SGL mediante HTTPS o localhost.'};
      return {ok:false,message:`No se pudo abrir el micrófono: ${error?.message||error?.name||'error desconocido'}`};
    }finally{try{stream?.getTracks?.().forEach(track=>track.stop());}catch{}}
  }
  window.sgl510TestMicrophone=async function sgl510TestMicrophone(){
    if(!sgl505SecureSpeechContext())return toast('Prueba de micrófono: abre SGL mediante HTTPS o localhost.');
    const result=await sgl510MicrophonePreflight();
    if(result.ok)return toast(`Micrófono detectado${result.label?`: ${result.label}`:''}. Si el dictado no transcribe, el problema está en el servicio de reconocimiento del navegador.`);
    toast(result.message);
    return result;
  };
  function sgl505SpeechErrorMessage(code){
    const value=String(code||'').toLowerCase();
    if(['not-allowed','permission-denied','service-not-allowed'].includes(value))return 'Permiso de micrófono bloqueado. Permite Micrófono para SGL desde el navegador.';
    if(value==='audio-capture')return 'No se detectó un micrófono activo.';
    if(value==='network')return 'El servicio de dictado no respondió. Revisa Internet y vuelve a intentar.';
    return `No se pudo continuar el dictado: ${code||'error desconocido'}`;
  }

  function sgl505StopDictation(showMessage=true){
    const session=window.__sgl500DictationSession;
    if(!session)return false;
    session.active=false;session.manualStop=true;
    if(session.restartTimer)clearTimeout(session.restartTimer);
    try{session.recognition?.stop();}catch{try{session.recognition?.abort();}catch{}}
    window.__sgl500Recognition=null;
    window.__sgl500DictationSession=null;
    sgl505UpdateDictationUi(false,showMessage?'Dictado detenido.':'');
    if(showMessage)toast('Dictado detenido.');
    return true;
  }
  window.sgl505StopDictation=sgl505StopDictation;

  function sgl505StartRecognitionCycle(session){
    if(!session?.active||session.manualStop||!session.editor?.isConnected){sgl505StopDictation(false);return;}
    const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SpeechRecognition){sgl505StopDictation(false);return toast('Este navegador no permite dictado por micrófono.');}
    const recognition=new SpeechRecognition();
    session.recognition=recognition;
    session.cycle+=1;
    session.cycleResultText=new Map();
    window.__sgl500Recognition=recognition;
    recognition.lang=(navigator.language&&navigator.language.toLowerCase().startsWith('es'))?navigator.language:'es-MX';
    recognition.continuous=true;
    recognition.interimResults=true;
    recognition.maxAlternatives=1;
    recognition.onstart=()=>{
      session.restartAttempts=0;
      sgl505UpdateDictationUi(true,`Escuchando${session.micLabel?` · ${session.micLabel}`:''}… puedes hacer pausas y continuar.`);
    };
    recognition.onresult=event=>{
      if(!session.active)return;
      const start=Math.max(0,Number(event?.resultIndex||0)||0);
      let interim='';
      for(let i=start;i<(event?.results?.length||0);i+=1){
        const result=event.results[i],transcript=sgl505NormalizeSpeechText(result?.[0]?.transcript||'');
        if(!transcript)continue;
        session.noSpeechCount=0;
        if(result.isFinal){
          // Un mismo ciclo puede reenviar results anteriores cuando resultIndex vuelve a 0.
          // Se ignora el mismo texto final del mismo índice, pero se permite que ese índice
          // crezca (por ejemplo: "Hola" -> "Hola quiero").
          const priorAtIndex=session.cycleResultText?.get(i)||'';
          if(priorAtIndex===transcript)continue;
          session.cycleResultText?.set(i,transcript);
          const existing=session.editor.innerText||session.editor.textContent||'';
          const delta=sgl505DictationDelta(transcript,session.state,existing);
          if(delta)sgl505InsertDictationText(session.editor,delta);
        }else{
          interim=transcript;
        }
      }
      if(interim)sgl505UpdateDictationUi(true,`Escuchando: ${interim}`);
      else sgl505UpdateDictationUi(true,'Escuchando… puedes hacer pausas y continuar.');
    };
    recognition.onerror=event=>{
      const code=String(event?.error||'').toLowerCase();
      if(code==='no-speech'||code==='aborted'){
        if(code==='no-speech'){
          session.noSpeechCount=Number(session.noSpeechCount||0)+1;
          if(session.noSpeechCount>=3&&!session.noSpeechWarned){
            session.noSpeechWarned=true;
            toast(`El micrófono fue detectado${session.micLabel?` (${session.micLabel})`:''}, pero no está llegando voz al reconocimiento. Revisa en Windows qué micrófono está seleccionado como entrada y el nivel de volumen.`);
          }
        }
        if(session.active&&!session.manualStop)sgl505UpdateDictationUi(true,'Pausa detectada… sigo escuchando.');
        return;
      }
      if(['not-allowed','permission-denied','service-not-allowed','audio-capture','network'].includes(code)){
        session.fatalError=code;session.active=false;
        sgl505UpdateDictationUi(false,'');
        toast(sgl505SpeechErrorMessage(code));
      }
    };
    recognition.onend=()=>{
      if(window.__sgl500Recognition===recognition)window.__sgl500Recognition=null;
      if(!session.active||session.manualStop||session.fatalError||!session.editor?.isConnected){
        if(window.__sgl500DictationSession===session&&!session.active)window.__sgl500DictationSession=null;
        sgl505UpdateDictationUi(false,session.manualStop?'Dictado detenido.':'');
        return;
      }
      // Chrome Android corta una sesión tras algunos segundos de silencio. Se crea
      // una nueva sesión automáticamente para que el usuario no tenga que tocar Dictar.
      session.restartAttempts+=1;
      const delay=Math.min(1200,320+(session.restartAttempts-1)*180);
      sgl505UpdateDictationUi(true,'Pausa detectada… reanudando micrófono.');
      session.restartTimer=setTimeout(()=>sgl505StartRecognitionCycle(session),delay);
    };
    try{recognition.start();}
    catch(error){
      session.restartAttempts+=1;
      if(session.restartAttempts<=3&&session.active&&!session.manualStop){
        session.restartTimer=setTimeout(()=>sgl505StartRecognitionCycle(session),450*session.restartAttempts);
      }else{
        session.active=false;window.__sgl500DictationSession=null;window.__sgl500Recognition=null;
        sgl505UpdateDictationUi(false,'');toast(sgl505SpeechErrorMessage(error?.name||error?.message));
      }
    }
  }

  window.sgl500ToggleDictation=async function sgl500ToggleDictationSGL505(){
    if(window.__sgl500DictationSession?.active)return sgl505StopDictation(true);
    const editor=document.getElementById('req_text');
    if(!editor)return toast('Abre un informe para usar dictado.');
    const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SpeechRecognition)return toast('Este navegador no permite dictado por micrófono. Usa Chrome o Edge actualizado.');
    if(!sgl505SecureSpeechContext())return toast('Abre el enlace HTTPS para usar el micrófono.');
    if(await sgl505MicrophoneDenied())return toast('Permiso de micrófono bloqueado. Permite Micrófono para SGL desde el navegador.');
    const mic=await sgl510MicrophonePreflight();
    if(!mic.ok)return toast(mic.message);
    sgl505RememberReportCaret();
    const session={active:true,manualStop:false,fatalError:'',editor,state:{previousFinalWords:[]},recognition:null,restartTimer:null,restartAttempts:0,cycle:0,micLabel:mic.label||'',noSpeechCount:0,noSpeechWarned:false};
    window.__sgl500DictationSession=session;
    sgl505UpdateDictationUi(true,'Iniciando micrófono…');
    sgl505StartRecognitionCycle(session);
    toast('Dictado iniciado. Puedes hacer pausas; SGL intentará reanudarlo automáticamente.');
  };

  function sgl505ReportPreviewDocument(data,orientation='auto',font='Arial'){
    if(typeof window.sgl5050BuildReportPreviewDocument==='function'&&Array.isArray(data?.reportLayoutPages)&&data.reportLayoutPages.length){
      return window.sgl5050BuildReportPreviewDocument(data,orientation,font);
    }
    const selected=orientation==='landscape'?'landscape':'portrait';
    const family=font==='Times New Roman'?'Times New Roman':'Arial';
    const footer=typeof reportInstitutionFooterHtml==='function'?reportInstitutionFooterHtml(data):'';
    const paperW=selected==='landscape'?1056:816;
    const paperH=selected==='landscape'?816:1056;
    return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
      @page{size:letter ${selected};margin:0}
      *{box-sizing:border-box}html,body{margin:0;min-height:100%;padding:0}body{font-family:${family},sans-serif;color:#111;background:#d9e0e8}
      .screen-stage{min-height:100vh;display:flex;justify-content:center;align-items:flex-start;padding:18px 12px 30px;overflow:hidden}
      .paper-shell{position:relative;flex:0 0 auto}
      .paper{position:relative;width:${paperW}px;min-height:${paperH}px;background:#fff;padding:24pt 56.7pt 42.52pt 85.04pt;transform-origin:top left;box-shadow:0 14px 42px rgba(15,23,42,.20);font-size:12pt;line-height:15.5pt;overflow:hidden}
      header{position:relative;display:grid;grid-template-columns:43pt 1fr 43pt;gap:10pt;align-items:center;height:56pt;border:0;text-align:center;padding:0 0 6pt;margin:0 0 10pt}header:after{content:'';position:absolute;left:53pt;right:53pt;bottom:0;border-bottom:1.8pt solid #1f739e;pointer-events:none}header img{width:43pt;height:43pt;object-fit:contain}header h1{font-size:13.5pt;color:#1f739e;margin:0}header p{font-size:10.5pt;margin:2pt 0}.area-title{font-size:10.5pt;line-height:14pt;color:#1f739e;text-transform:uppercase;margin:0 0 5pt}.requirement-title{font-size:11.5pt;line-height:16pt;margin:0 0 5pt}.requirement-fill-date{font-size:10.5pt;line-height:14pt;font-weight:700;color:#1f739e;margin:0 0 10pt;text-align:right;text-transform:none}.chosen{font-weight:bold;line-height:18pt;margin:0 0 8pt}article{margin-top:0}article p,article div{margin:0 0 7pt;line-height:15.5pt;text-align:left;text-align-last:auto}.report-photos{display:grid;grid-template-columns:1fr 1fr;gap:12pt}.report-photos figure{margin:0 0 12pt;text-align:center}.report-photos img{width:calc(var(--photo-scale,70)*1%);max-width:100%;max-height:230pt;object-fit:contain}footer.report-institution-footer{position:absolute;left:85.04pt;right:56.7pt;bottom:18pt;font-size:8.5pt;color:#111;display:grid;grid-template-columns:1fr 1fr 1fr;gap:10pt;text-transform:uppercase}footer.report-institution-footer span:nth-child(2){text-align:center}footer.report-institution-footer span:nth-child(3){text-align:right}
      @media print{html,body{background:#fff}.screen-stage{display:block;min-height:0;padding:0;overflow:visible}.paper-shell{width:auto!important;height:auto!important}.paper{width:100%;min-height:100vh;padding:24pt 56.7pt 42.52pt 85.04pt;transform:none!important;box-shadow:none;overflow:visible}footer.report-institution-footer{position:fixed}button{display:none!important}}
    </style></head><body><div class="screen-stage"><div id="paper_shell" class="paper-shell"><div id="paper" class="paper">${data.html}${footer}</div></div></div><script>
      (function(){var rawW=${paperW},rawH=${paperH},paper=document.getElementById('paper'),shell=document.getElementById('paper_shell');function fit(){if(!paper||!shell)return;var available=Math.max(220,document.documentElement.clientWidth-24);var scale=Math.min(1,available/rawW);paper.style.transform='scale('+scale+')';shell.style.width=(rawW*scale)+'px';shell.style.height=(Math.max(rawH,paper.scrollHeight)*scale)+'px';}window.addEventListener('load',fit);window.addEventListener('resize',fit);setTimeout(fit,20);setTimeout(fit,180);if(window.ResizeObserver)new ResizeObserver(fit).observe(paper);})();
    <\/script></body></html>`;
  }
  window.sgl505ReportPreviewDocument=sgl505ReportPreviewDocument;

  function sgl505ShowReportPdf(requirementId,data,blob,filename){
    window.sgl5052CapturePreviewReturnState?.(requirementId);
    window.__SGL_LAST_REPORT_PREVIEW__={blob,filename,requirementId,createdAt:isoNow(),data};
    if(materialPreviewUrl)URL.revokeObjectURL(materialPreviewUrl);
    materialPreviewUrl=URL.createObjectURL(blob);
    const mobile=sgl505IsMobile();
    const viewer=mobile?'<iframe id="sgl505_pdf_html_frame" class="preview-frame sgl505-html-report-frame" title="Vista del informe"></iframe>':`<iframe class="preview-frame" title="Vista PDF" src="${materialPreviewUrl}#zoom=page-width" loading="eager"></iframe>`;
    const head=mobile?'':`<div class="modal-head"><div><h3>Vista PDF del informe</h3><p>${esc(data?.requirement?.areaTitle||'Informe')} · ${esc(data?.requirement?.official_text||'Vista PDF')}</p></div><button class="modal-close" onclick="closeModal()">×</button></div>`;
    showModal(`<div class="modal material-preview sgl426-pdf-preview sgl430-pdf-preview sgl505-pdf-preview sgl513-clean-pdf-preview">${head}<div class="modal-body">${viewer}</div><div class="modal-foot"><button class="btn ghost" onclick="sgl5052ReturnToReport('${requirementId}')">Volver al informe</button><button class="btn ghost" onclick="sgl430OpenCurrentPdf()">Abrir PDF</button><button class="btn ghost" onclick="printRequirement('${requirementId}')">Imprimir</button><button class="btn primary" onclick="saveCurrentReportPreviewPdf()">Guardar PDF</button></div></div>`);
    if(mobile){
      const frame=document.getElementById('sgl505_pdf_html_frame');
      if(frame){
        const orientation=value('req_orientation')||data.submission?.orientation||'auto';
        const font=value('req_font')||data.aspirant?.reportFont||'Arial';
        frame.srcdoc=sgl505ReportPreviewDocument(data,orientation,font);
      }
    }
  }
  window.sgl505ShowReportPdf=sgl505ShowReportPdf;

  previewRequirementPdf=async function previewRequirementPdfSGL505(requirementId){
    try{
      toast('Preparando vista PDF...');
      const data=await printableRequirement(requirementId);
      const blob=await makeReportPdf(requirementId,data);
      sgl505ShowReportPdf(requirementId,data,blob,reportFileName(data));
    }catch(error){toast(`No se pudo mostrar el PDF: ${error.message}`);}
  };
  window.previewRequirementPdf=previewRequirementPdf;

  openReportPrintDialog=async function openReportPrintDialogSGL505(requirementId){
    try{
      const data=await printableRequirement(requirementId);
      const orientation=value('req_orientation')||data.submission.orientation||'auto';
      const font=value('req_font')||data.aspirant.reportFont||'Arial';
      const html=sgl505ReportPreviewDocument(data,orientation,font);
      showModal(`<div class="modal material-preview report-print-modal sgl505-print-modal"><div class="modal-head"><div><h3>Vista de impresión</h3><p>La hoja completa se ajusta a la pantalla con los dos costados y márgenes visibles.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><iframe id="report_print_frame" class="preview-frame sgl505-print-frame" title="Vista de impresión"></iframe></div><div class="modal-foot"><button class="btn ghost" onclick="closeModal()">Cerrar</button><button class="btn ghost" onclick="exportPdf('${requirementId}')">Guardar PDF</button><button class="btn primary" onclick="printReportFrame()">Abrir cuadro de impresión</button></div></div>`);
      const frame=document.getElementById('report_print_frame');if(frame)frame.srcdoc=html;
    }catch(error){
      try{await logClientError('Impresión',error);}catch{}
      toast(`No se pudo preparar la impresión: ${error.message}`);
    }
  };
  window.openReportPrintDialog=openReportPrintDialog;

  // Marca la base de datos como versión siguiente, sin llamar a esta entrega "hotfix".
  if(typeof migrateDatabase==='function'){
    const SGL505_BASE_MIGRATE=migrateDatabase;
    migrateDatabase=function migrateDatabaseSGL505(){SGL505_BASE_MIGRATE();if(database)database.version=SGL505_VERSION;};
    window.migrateDatabase=migrateDatabase;
  }
})();


/* SGL 5.0.6 - expediente buttons and real task counters */
function sgl506TaskIsRealForActor(task,user=currentUser(),programId=''){
  try{
    if(!task||task.active===false||task.deletedAt)return false;
    const actor=user||currentUser(),assignee=userById(task.assigneeId);
    if(!actor||!assignee||!['aspirant','pastor_aspirant'].includes(assignee.role))return false;
    if(assignee.active===false||['inactive','archived'].includes(String(assignee.accountState||'active')))return false;
    const allowedIds=new Set(['aspirant','pastor_aspirant'].includes(actor.role)?[actor.id]:accessibleAspirants(actor).map(item=>item.id));
    if(!allowedIds.has(assignee.id))return false;
    const pid=String(task.programId||'class_grouped');
    if(programId&&pid!==String(programId))return false;
    const module=v3ModuleRecord(pid);
    if(!module||module.active===false)return false;
    if(!Array.isArray(module.assignedUserIds)||!module.assignedUserIds.includes(assignee.id))return false;
    if(!v3RequirementById(task.requirementId,pid))return false;
    return true;
  }catch{return false;}
}
window.sgl506TaskIsRealForActor=sgl506TaskIsRealForActor;

(function installSGL506ExpedienteAndTasks(){
  const SGL506_VERSION='5.0.6';

  function sgl506PendingTasks(user=currentUser()){
    return window.sgl547PendingTasks?window.sgl547PendingTasks(user):(database.tasks||[]).filter(task=>sgl506TaskIsRealForActor(task,user)&&taskState(task)!=='presented');
  }
  window.sgl506PendingTasks=sgl506PendingTasks;

  const SGL506_BASE_GO=go;
  go=function goSGL506(page,...rest){
    if(page==='tasks'){
      try{
        const pending=sgl506PendingTasks(currentUser());
        const currentHasPending=pending.some(task=>String(task.programId||'class_grouped')===String(v3ActiveProgramId||'class_grouped'));
        if(pending.length&&!currentHasPending)v3ActiveProgramId=String(pending[0].programId||'class_grouped');
      }catch{}
    }
    return SGL506_BASE_GO.call(this,page,...rest);
  };
  window.go=go;

  openAspirant=function openAspirantSGL506(id){
    const actor=currentUser(),aspirant=userById(id);
    if(!actor||!aspirant||!['aspirant','pastor_aspirant'].includes(aspirant.role))return toast('No se encontro el expediente seleccionado.');
    const allowed=accessibleAspirants(actor);
    if(!allowed.some(item=>item.id===aspirant.id))return toast('No tienes acceso a este expediente.');
    activeAspirantId=aspirant.id;
    let programs=[];
    try{programs=v3AssignedProgramIds(aspirant).filter(programId=>v3UserHasProgram(actor,programId)||actor.role==='admin');}catch{}
    if(programs.length)v3ActiveProgramId=programs[0];
    else{
      const fallback=(database.modules||[]).find(module=>module.active!==false&&(actor.role==='admin'||v3UserHasProgram(actor,module.id)));
      if(fallback)v3ActiveProgramId=fallback.id;
    }
    try{return go('requirements');}
    catch(error){
      console.error('SGL 5.0.6 expediente',error);
      try{
        currentPage='requirements';closeModal(true);renderNav();return renderRequirements();
      }catch(second){console.error('SGL 5.0.6 expediente fallback',second);return toast('No se pudo abrir el expediente. Recarga SGL e intenta nuevamente.');}
    }
  };
  window.openAspirant=openAspirant;

  if(typeof migrateDatabase==='function'){
    const SGL506_BASE_MIGRATE=migrateDatabase;
    migrateDatabase=function migrateDatabaseSGL506(){SGL506_BASE_MIGRATE();if(database)database.version=SGL506_VERSION;};
    window.migrateDatabase=migrateDatabase;
  }
})();


/* SGL 5.0.7 - hora visible de felicitacion y login remoto optimizado */
(function installSGL507RankingAndLoginPerformance(){
  if(window.__sgl507RankingAndLoginPerformance)return;
  window.__sgl507RankingAndLoginPerformance=true;
  const SGL507_VERSION='5.0.7';
  let sgl507LoginQuietUntil=0;
  let sgl507LoginInProgress=false;

  function sgl507RecognitionHour(){
    try{return sgl504RecognitionHour(database?.settings||{});}catch{}
    const n=Number(database?.settings?.dailyRecognitionHour??18);
    return Number.isFinite(n)&&n>=0&&n<=23?Math.trunc(n):18;
  }
  function sgl507RecognitionScheduleHtml(){
    const user=currentUser();
    if(!user)return '';
    if(user.role!=='admin') return '';
    const hour=sgl507RecognitionHour();
    const hh=String(hour).padStart(2,'0')+':00';
    const options=Array.from({length:24},(_,h)=>`<option value="${h}" ${h===hour?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('');
    return `<section id="sgl507_recognition_schedule" class="card sgl507-recognition-schedule"><div class="card-head"><div><div class="eyebrow">Configuración de felicitación diaria</div><h3>Hora programada: ${hh}</h3><p class="subtitle">Solo administración. Define la hora exacta en que puede generarse una sola vez la felicitación diaria.</p></div><div class="sgl430-hour"><label>Felicitar a las<select id="sgl430_daily_hour" class="field">${options}</select></label><button class="btn primary small" onclick="sgl430SaveDailyHour()">Guardar horario</button></div></div></section>`;
  }
  function sgl507InjectRecognitionSchedule(){
    const root=document.getElementById('content');
    if(!root||document.getElementById('sgl507_recognition_schedule'))return;
    const html=sgl507RecognitionScheduleHtml();
    if(!html)return;
    const firstCard=root.querySelector('.sgl501-ranking-filter,.grid4,.sgl504-encouragement,.sgl504-ranking-filter');
    if(firstCard)firstCard.insertAdjacentHTML('beforebegin',html);
    else root.insertAdjacentHTML('afterbegin',html);
  }
  if(typeof renderDailyActivity==='function'){
    const SGL507_BASE_RENDER_DAILY=renderDailyActivity;
    renderDailyActivity=function renderDailyActivitySGL507(...args){
      const result=SGL507_BASE_RENDER_DAILY.apply(this,args);
      if(result&&typeof result.then==='function')return result.finally(()=>sgl507InjectRecognitionSchedule());
      sgl507InjectRecognitionSchedule();
      return result;
    };
    window.renderDailyActivity=renderDailyActivity;
  }

  function sgl507InLoginQuietWindow(){return REMOTE_WEB&&(sgl507LoginInProgress||Date.now()<sgl507LoginQuietUntil);}
  function sgl507QuietDelay(extra=0){return Math.max(0,sgl507LoginQuietUntil-Date.now()+extra);}
  async function sgl507WaitForPostLogin(extra=0){
    while(REMOTE_WEB&&sgl507LoginInProgress)await new Promise(resolve=>setTimeout(resolve,40));
    const delay=sgl507QuietDelay(extra);
    if(delay>0)await new Promise(resolve=>setTimeout(resolve,delay));
  }

  // The remote login already completed authentication. Give the first screen a
  // short quiet window before old inherited polling hooks start competing for CPU/network.
  if(typeof remoteLogin==='function'){
    const SGL507_BASE_REMOTE_LOGIN=remoteLogin;
    remoteLogin=async function remoteLoginSGL507(event){
      if(REMOTE_WEB){sgl507LoginInProgress=true;sgl507LoginQuietUntil=0;}
      let result;
      try{result=await SGL507_BASE_REMOTE_LOGIN.call(this,event);}
      finally{
        if(REMOTE_WEB){
          sgl507LoginInProgress=false;
          sgl507LoginQuietUntil=currentUser?.()?Date.now()+3000:0;
        }
      }
      if(REMOTE_WEB&&currentUser?.()){
        setTimeout(()=>{try{remoteHeartbeat?.();}catch{}},sgl507QuietDelay(150));
        setTimeout(()=>{try{v4FetchNotifications?.(false,false);}catch{}},sgl507QuietDelay(450));
        setTimeout(()=>{try{v3FetchPresence?.(false);}catch{}},sgl507QuietDelay(750));
        setTimeout(()=>{try{v4BackgroundSyncTick?.();}catch{}},sgl507QuietDelay(1050));
      }
      return result;
    };
    window.remoteLogin=remoteLogin;
  }

  if(typeof v4FlushMessageOutbox==='function'){const base=v4FlushMessageOutbox;v4FlushMessageOutbox=async function(...args){if(sgl507InLoginQuietWindow())return false;return base.apply(this,args);};window.v4FlushMessageOutbox=v4FlushMessageOutbox;}
  if(typeof v4214FetchUserChanges==='function'){const base=v4214FetchUserChanges;v4214FetchUserChanges=async function(...args){if(sgl507InLoginQuietWindow())return [];return base.apply(this,args);};window.v4214FetchUserChanges=v4214FetchUserChanges;}
  if(typeof sglPrepareOfflineShell==='function'){const base=sglPrepareOfflineShell;sglPrepareOfflineShell=async function(...args){if(REMOTE_WEB&&sgl507InLoginQuietWindow())await sgl507WaitForPostLogin(500);return base.apply(this,args);};window.sglPrepareOfflineShell=sglPrepareOfflineShell;}
  if(typeof v4BackgroundSyncTick==='function'){const base=v4BackgroundSyncTick;v4BackgroundSyncTick=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.v4BackgroundSyncTick=v4BackgroundSyncTick;}
  if(typeof v3PullServerUpdates==='function'){const base=v3PullServerUpdates;v3PullServerUpdates=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.v3PullServerUpdates=v3PullServerUpdates;}
  if(typeof v3FetchSyncRequests==='function'){const base=v3FetchSyncRequests;v3FetchSyncRequests=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.v3FetchSyncRequests=v3FetchSyncRequests;}
  if(typeof v4FetchMessages==='function'){const base=v4FetchMessages;v4FetchMessages=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.v4FetchMessages=v4FetchMessages;}
  if(typeof v4FetchNotifications==='function'){const base=v4FetchNotifications;v4FetchNotifications=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.v4FetchNotifications=v4FetchNotifications;}
  if(typeof v3FetchPresence==='function'){const base=v3FetchPresence;v3FetchPresence=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.v3FetchPresence=v3FetchPresence;}
  if(typeof remoteHeartbeat==='function'){const base=remoteHeartbeat;remoteHeartbeat=async function(...args){if(sgl507InLoginQuietWindow())return null;return base.apply(this,args);};window.remoteHeartbeat=remoteHeartbeat;}

  if(typeof sglRefreshRemoteFilesAfterLogin==='function'){
    const SGL507_BASE_REFRESH_FILES=sglRefreshRemoteFilesAfterLogin;
    sglRefreshRemoteFilesAfterLogin=async function sglRefreshRemoteFilesAfterLoginSGL507(token){
      if(REMOTE_WEB){
        await sgl507WaitForPostLogin(900);
        if(typeof requestIdleCallback==='function')await new Promise(resolve=>requestIdleCallback(()=>resolve(),{timeout:1800}));
        else await new Promise(resolve=>setTimeout(resolve,120));
      }
      return SGL507_BASE_REFRESH_FILES.call(this,token);
    };
    window.sglRefreshRemoteFilesAfterLogin=sglRefreshRemoteFilesAfterLogin;
  }

  if(typeof migrateDatabase==='function'){
    const SGL507_BASE_MIGRATE=migrateDatabase;
    migrateDatabase=function migrateDatabaseSGL507(){SGL507_BASE_MIGRATE();if(database)database.version=SGL507_VERSION;};
    window.migrateDatabase=migrateDatabase;
  }
})();

