    const active=modal.classList.toggle('sgl513r3-focus-mode'),button=modal.querySelector('.sgl513r3-focus-toggle');
    if(button)button.textContent=active?'← Volver a vista normal':'✎ Modo escritura';
    if(active){editor.focus({preventScroll:true});setTimeout(()=>editor.scrollIntoView({block:'center',behavior:'smooth'}),20);}
