      if(select&&!sgl513R3EditingTask&&select.options.length>=1&&!select.querySelector(`option[value="${SGL_R3_ALL}"]`))select.insertAdjacentHTML('afterbegin',`<option value="${SGL_R3_ALL}">Todos los aspirantes elegibles (${select.options.length})</option>`);
      return result;
