      if(id||value('task_assignee')!==SGL_R3_ALL)return R3_BASE_SAVE_TASK.call(this,event,id);
      event?.preventDefault?.();const actor=currentUser();if(!['admin','tutor'].includes(actor?.role))return;
      const programId=value('task_program')||v3ActiveProgramId,requirementId=value('task_requirement'),module=v3ModuleRecord(programId),dueDate=value('task_due'),instructions=value('task_instructions').trim();
      if(!v3RequirementById(requirementId,programId))return toast('Selecciona un requisito válido.');
