  /* ---------- Estado en vivo: borrar el último contenido vuelve a PENDIENTE ---------- */
  async function sgl5031RefreshLiveDraftStatus({force=false}={}){
    const editor=document.getElementById('req_text');
    if(!editor||!modalOwnerId||!modalRequirementId||!v3ModalProgramId)return false;
    const progress=v3EnsureProgramProgress(modalOwnerId,v3ModalProgramId),submission=v3SubmissionFor(modalOwnerId,modalRequirementId,v3ModalProgramId);
    const status=String(progress.status?.[modalRequirementId]||'pending');
    if(!['pending','in_progress'].includes(status))return false;
    const live=readRichEditor?.()||{text:editor.textContent||'',html:editor.innerHTML||''};
    const hasText=!!sgl5031PlainText(live.text||live.html);
    const hasInline=editor.querySelectorAll('figure[data-sgl-photo-id]').length>0;
    const hasAttachment=(submission.attachmentIds||[]).filter(Boolean).length>0;
    const hasContent=hasText||hasInline||hasAttachment;
    const next=hasContent?'in_progress':'pending';
    let changed=status!==next;
    if(!hasContent){
      if(submission.text||submission.richText||submission.completionDate){changed=true;}
      submission.text='';submission.richText='';submission.completionDate='';submission.approval=null;submission.updatedAt=isoNow();
    }
    if(!changed&&!force)return false;
    progress.status[modalRequirementId]=next;progress.updatedAt=isoNow();database.version=SGL5031_VERSION;
    await persistDraftLocal();
    const head=document.querySelector('#modal_root .sgl512-report-modal .modal-head p');
    if(head){const program=v3Program(v3ModalProgramId);head.textContent=`${modalRequirementId} · ${STATUS_LABELS[next]||next} · ${program?.name||v3ModalProgramId}`;}
    return true;
  }
