  function configuredReading(programId,requirementId){if(musicDevotionFixed(programId,requirementId))return false;if(!READING_PROGRAMS.has(String(programId||'')))return false;const value=modeMap()[modeKey(programId,requirementId)];return value==='reading_report'||value?.mode==='reading_report';}
