  function configuredReadingForAdmin(programId,requirementId){const draft=readingDrafts[String(programId||'class_grouped')];return draft?!!draft[String(requirementId)]:configuredReading(programId,requirementId);}
  function submissionFor5078(ownerId,programId,requirementId){try{return v3SubmissionFor(ownerId,requirementId,programId||'class_grouped');}catch{return null;}}
