    const submission=owner?submissionFor5078(owner,programId,requirementId):null;
    if(submission?.primaryDocumentId||String(submission?.submissionMode||submission?.deliveryMode||'').toLowerCase()==='document')return true;
    if(String(submission?.text||'').trim()||String(submission?.richText||'').replace(/<[^>]*>/g,'').trim())return false;
