  function adminLogo(){return currentUser()?.role==='admin'?(database?.settings?.musicAdminLogo||'admin-logo.png'):appLogo();}
  function patchAdminLogo(){if(currentUser()?.role!=='admin')return;const src=adminLogo();document.querySelectorAll('.side-brand img,.top-logo').forEach(img=>{img.src=src;img.classList.add('sgl-admin-role-logo');img.style.setProperty('width','38px','important');img.style.setProperty('height','38px','important');img.style.setProperty('max-width','38px','important');img.style.setProperty('max-height','38px','important');img.style.setProperty('object-fit','contain','important');img.style.setProperty('flex','0 0 38px','important');});}
