  function refreshReportConfigSaveState(programId){programId=String(programId||v3ActiveProgramId||'class_grouped');const dirty=reportConfigDirty(programId),save=document.getElementById('sgl5078_save_report_config'),discard=document.getElementById('sgl5078_discard_report_config');if(save)save.disabled=!dirty;if(discard)discard.disabled=!dirty;const box=document.getElementById('sgl5078_report_config_state');if(box){box.classList.toggle('warn',dirty);const copy=box.querySelector('[data-sgl5078-save-copy]');if(copy)copy.innerHTML=dirty?'<b>Cambios pendientes.</b> Las indicaciones y asignaciones de esta clase se guardarán juntas al final.':'<b>Configuración guardada.</b> Las indicaciones y asignaciones mostradas corresponden al último guardado.';}}
