  function markIndicationDirty(programId,requirementId,nextValue){programId=String(programId||'class_grouped');requirementId=String(requirementId||'');const draft=ensureIndicationDraft(programId),original=indicationOriginals[programId]||{};draft[requirementId]=String(nextValue??'');const changed=v3ProgramRequirements(programId).some(req=>String(draft[String(req.id)]??'')!==String(original[String(req.id)]??''));if(changed)dirtyIndicationPrograms.add(programId);else dirtyIndicationPrograms.delete(programId);refreshReportConfigSaveState(programId);const counter=document.getElementById('sgl5088_indication_changes');if(counter)counter.textContent=String(changedIndicationCount(programId));}
  function indicationInputId(requirementId){return `sgl5088_indication_${String(requirementId||'').replace(/[^A-Za-z0-9_-]/g,'_')}`;}
  window.sgl5088DraftIndication=function sgl5088DraftIndication(input,programId,requirementId){if(currentUser()?.role!=='admin')return;markIndicationDirty(programId,requirementId,input?.value||'');};
  window.sgl5088ResetIndication=function sgl5088ResetIndication(programId,requirementId){if(currentUser()?.role!=='admin')return;programId=String(programId||'class_grouped');requirementId=String(requirementId||'');const req=v3ProgramRequirements(programId).find(item=>String(item.id)===requirementId);if(!req)return;const next=defaultIndicationText(req),input=document.getElementById(indicationInputId(requirementId));if(input)input.value=next;markIndicationDirty(programId,requirementId,next);};
