  function renderConfigRows(programId){return v3ProgramRequirements(programId).map(req=>{const rule=primaryIndication(programId,req.id),draftText=ensureIndicationDraft(programId)[String(req.id)],doc=configuredDocumentForAdmin(programId,req.id),reading=configuredReadingForAdmin(programId,req.id),existing=existingDeliveryCount(programId,req.id),modeLabel=musicDevotionFixed(programId,req.id)?(req.id==='LM-NUT-1'?'Elección del líder: Reavivados / Bible Plan / Certificado PDF':'Diario de 40 madrugadas'):reading?'Informe de lectura':doc?'PDF / fotografías':'Informe escrito';return `<div class="list-item sgl5078-config-row"><div class="req-code">${esc(req.id)}</div><div class="sgl5078-config-main"><h4>${esc(req.official_text||req.id)}</h4><div class="chips"><span class="chip blue">${esc(req.areaTitle||'Área')}</span><span class="chip">${rule?'Indicación personalizada':'Indicación general'}</span>${existing?`<span class="chip">${existing} entrega${existing===1?'':'s'}</span>`:''}</div><p class="muted">${esc(short(draftText||defaultIndicationText(req)||'Sin indicación personalizada.',180))}</p></div><div class="actions"><span class="chip ${reading?'blue':doc?'gold':''}">${esc(modeLabel)}</span><button class="btn primary small" type="button" title="Editar indicación" aria-label="Editar indicación de ${esc(req.id)}" onclick='sgl5078EditIndication(${jsAttr(programId)},${jsAttr(req.id)})'><span aria-hidden="true">✎</span></button></div></div>`;}).join('')||'<div class="card empty">No hay requisitos en este módulo.</div>';}
