  function documentAssignmentButton(programId){const count=v3ProgramRequirements(programId).filter(req=>configuredDocumentForAdmin(programId,req.id)).length;return `<button class="btn warn sgl5079-assign-top" type="button" onclick='sgl5079OpenDocumentAssignment(${jsAttr(programId)})'>Asignar PDF o fotos${count?` · ${count}`:''}</button>`;}
  function readingAssignmentButton(programId){const count=v3ProgramRequirements(programId).filter(req=>configuredReadingForAdmin(programId,req.id)).length;return `<button class="btn dark sgl5079-assign-top" type="button" onclick='sgl5078OpenReadingAssignment(${jsAttr(programId)})'>Asignar informe de lectura${count?` · ${count}`:''}</button>`;}
  function documentAssignmentRows(programId){return v3ProgramRequirements(programId).filter(req=>!musicDevotionFixed(programId,req.id)).map(req=>{const checked=configuredDocumentForAdmin(programId,req.id),reading=configuredReadingForAdmin(programId,req.id);return `<label class="sgl5078-reading-choice ${checked?'selected':''}"><input type="checkbox" ${checked?'checked':''} onchange='sgl5078ToggleDocumentMode(this,${jsAttr(programId)},${jsAttr(req.id)})'><span><b>${esc(req.id)}</b> ${esc(req.official_text||req.id)}</span>${checked?'<small>PDF/fotografías activo para este requisito.</small>':reading?'<small>Está asignado como Informe de lectura. Al activar PDF/fotos se quitará Informe de lectura.</small>':'<small>Al activarlo, el Aspirante podrá subir un PDF o fotografías.</small>'}</label>`;}).join('');}
  function readingAssignmentRows(programId){return v3ProgramRequirements(programId).filter(req=>!musicDevotionFixed(programId,req.id)).map(req=>{const checked=configuredReadingForAdmin(programId,req.id),doc=configuredDocumentForAdmin(programId,req.id);return `<label class="sgl5078-reading-choice ${checked?'selected':''}"><input type="checkbox" ${checked?'checked':''} onchange='sgl5078ToggleReadingMode(this,${jsAttr(programId)},${jsAttr(req.id)})'><span><b>${esc(req.id)}</b> ${esc(req.official_text||req.id)}</span>${checked?'<small>Informe de lectura activo para este requisito.</small>':doc?'<small>Está asignado como PDF/fotos. Al activar Informe de lectura se quitará PDF/fotos.</small>':'<small>Al activarlo, el Aspirante completará únicamente el formulario de Informe de lectura.</small>'}</label>`;}).join('');}
  window.sgl5079OpenDocumentAssignment=function sgl5079OpenDocumentAssignment(programId){if(currentUser()?.role!=='admin')return;programId=String(programId||v3ActiveProgramId||'class_grouped');v3ActiveProgramId=programId;modeDraft(programId);readingDraft(programId);const count=v3ProgramRequirements(programId).filter(req=>configuredDocumentForAdmin(programId,req.id)).length;showModal(`<div class="modal sgl5078-reading-assign-modal"><div class="modal-head"><div><h3>Asignar PDF o fotos a…</h3><p>${esc(v3Program(programId)?.menu_label||v3Program(programId)?.name||programId)} · ${count} requisito${count===1?'':'s'} asignado${count===1?'':'s'}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="notice"><b>Asignación especial.</b> El Aspirante no verá este botón. Al activar PDF/fotos en un requisito se quitará Informe de lectura, si estaba asignado. Las fotografías se preparan como un único documento PDF. Los cambios solo se hacen efectivos al pulsar <b>Guardar configuración</b>.</div><div class="sgl5078-reading-choice-list">${documentAssignmentRows(programId)}</div></div><div class="modal-foot"><button class="btn ghost" type="button" onclick="closeModal()">Cerrar</button><button class="btn primary" type="button" onclick='sgl5078CloseReadingAndGoSave(${jsAttr(programId)})'>Ir a Guardar configuración</button></div></div>`);};
  window.sgl5078OpenReadingAssignment=function sgl5078OpenReadingAssignment(programId){if(currentUser()?.role!=='admin')return;programId=String(programId||v3ActiveProgramId||'class_grouped');v3ActiveProgramId=programId;modeDraft(programId);readingDraft(programId);const count=v3ProgramRequirements(programId).filter(req=>configuredReadingForAdmin(programId,req.id)).length;showModal(`<div class="modal sgl5078-reading-assign-modal"><div class="modal-head"><div><h3>Asignar informe de lectura a…</h3><p>${esc(v3Program(programId)?.menu_label||v3Program(programId)?.name||programId)} · ${count} requisito${count===1?'':'s'} asignado${count===1?'':'s'}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="notice"><b>Asignación especial.</b> El Aspirante no verá este botón. Al activar Informe de lectura se quitará PDF/fotos, si estaba asignado. El Aspirante llenará el formulario y, después de guardar, verá el informe terminado sin edición directa. Los cambios solo se hacen efectivos al pulsar <b>Guardar configuración</b>.</div><div class="sgl5078-reading-choice-list">${readingAssignmentRows(programId)}</div></div><div class="modal-foot"><button class="btn ghost" type="button" onclick="closeModal()">Cerrar</button><button class="btn primary" type="button" onclick='sgl5078CloseReadingAndGoSave(${jsAttr(programId)})'>Ir a Guardar configuración</button></div></div>`);};
  window.sgl5078CloseReadingAndGoSave=function sgl5078CloseReadingAndGoSave(programId){programId=String(programId||v3ActiveProgramId||'class_grouped');closeModal();renderIndications();setTimeout(()=>document.getElementById('sgl5078_report_config_state')?.scrollIntoView({behavior:'smooth',block:'center'}),0);};
  function renderReportConfigurationSave(programId){const dirty=reportConfigDirty(String(programId)),changes=changedIndicationCount(programId);return `<section id="sgl5078_report_config_state" class="notice ${dirty?'warn':''} sgl5078-config-save"><div data-sgl5078-save-copy><b>${dirty?'Cambios pendientes.':'Configuración guardada.'}</b> ${dirty?'Las indicaciones y asignaciones de esta clase se guardarán juntas al final.':'Las indicaciones y asignaciones mostradas corresponden al último guardado.'}</div><div class="actions"><span class="chip">Indicaciones modificadas: <b id="sgl5088_indication_changes">${changes}</b></span><button id="sgl5078_save_report_config" class="btn primary" type="button" onclick='sgl5078SaveReportConfiguration(${jsAttr(programId)})' ${dirty?'':'disabled'}>Guardar cambios</button><button id="sgl5078_discard_report_config" class="btn ghost" type="button" onclick='sgl5078DiscardReportConfiguration(${jsAttr(programId)})' ${dirty?'':'disabled'}>Descartar cambios</button></div></section>`;}
  if(typeof renderIndications==='function'){
    renderIndications=function renderIndicationsSGL5078(){if(currentUser()?.role!=='admin')return go('dashboard');const allowed=['music_ministry'];if(!allowed.includes(v3ActiveProgramId))v3ActiveProgramId=allowed[0];const programId=v3ActiveProgramId,program=v3Program(programId),requirements=v3ProgramRequirements(programId);modeDraft(programId);readingDraft(programId);ensureIndicationDraft(programId);const documents=requirements.filter(req=>configuredDocumentForAdmin(programId,req.id)).length,reading=requirements.filter(req=>configuredReadingForAdmin(programId,req.id)).length,written=requirements.length-documents-reading,indicationChanges=changedIndicationCount(programId),only=reportConfigOnlyIndications;setTop('Configuración de informes',program.menu_label||program.name);const programSelect=`<select class="field" onchange="v3ActiveProgramId=this.value;renderIndications()">${allowed.map(id=>`<option value="${id}" ${id===programId?'selected':''}>${esc(v3Program(id).menu_label||v3Program(id).name||id)}</option>`).join('')}</select>`;const actions=only?`${programSelect}<button class="btn ghost" type="button" onclick="sgl5088SetIndicationView(false)">Configuración completa</button>`:`${programSelect}<button class="btn ghost" type="button" onclick="sgl5088SetIndicationView(true)">Solo indicaciones</button>${documentAssignmentButton(programId)}${readingAssignmentButton(programId)}<button class="btn primary" type="button" onclick="openIndicationRule('',{programId:v3ActiveProgramId})">Nueva regla avanzada</button>`;setContent(`<div class="page-head sgl5078-config-head"><div><div class="eyebrow">${only?'Edición masiva':'Configuración por requisito'}</div><h1 class="page-title">Configuración de informes</h1><p class="subtitle">${only?'Edita las indicaciones de todos los requisitos sin salir de esta pantalla. Nada se guarda hasta pulsar Guardar cambios.':'Configura indicaciones y modalidad de entrega para cada requisito.'}</p></div><div class="actions sgl5078-config-head-actions">${actions}</div></div><section class="card sgl5078-config-summary"><div><b>${requirements.length}</b><span>requisitos</span></div><div><b>${documents}</b><span>PDF / fotografías</span></div><div><b>${reading}</b><span>informes de lectura</span></div><div><b>${only?indicationChanges:Math.max(0,written)}</b><span>${only?'indicaciones modificadas':'informes escritos'}</span></div></section>${only?'<div class="notice"><b>Solo indicaciones.</b> Puedes modificar varias seguidas. El guardado es en grupo y permaneces en Configuración de informes. Las reglas específicas por Club, rol o persona no se eliminan.</div>':'<div class="notice"><b>Administración solamente.</b> Los Aspirantes no ven los botones de asignación. PDF/fotos e Informe de lectura nunca pueden estar activos a la vez.</div>'}<div class="${only?'sgl5088-indication-list':'list sgl5078-config-list'}">${only?renderIndicationRows(programId):renderConfigRows(programId)}</div>${renderReportConfigurationSave(programId)}`);};window.renderIndications=renderIndications;
  }
  window.sgl5078ToggleDocumentMode=function sgl5078ToggleDocumentMode(input,programId,requirementId){if(currentUser()?.role!=='admin'){input.checked=!input.checked;return;}programId=String(programId||'class_grouped');requirementId=String(requirementId||'');const next=!!input.checked,count=existingDeliveryCount(programId,requirementId);if(count&&next!==configuredDocument(programId,requirementId)&&!confirm(`Este requisito ya tiene ${count} entrega${count===1?'':'s'} guardada${count===1?'':'s'}.\n\nCambiar la asignación no eliminará entregas anteriores. ¿Deseas continuar?`)){input.checked=!next;return;}modeDraft(programId)[requirementId]=next;if(next)readingDraft(programId)[requirementId]=false;markReportConfigDirty(programId);renderIndications();setTimeout(()=>sgl5079OpenDocumentAssignment(programId),0);};
  window.sgl5078ToggleReadingMode=function sgl5078ToggleReadingMode(input,programId,requirementId){if(currentUser()?.role!=='admin'){input.checked=!input.checked;return;}programId=String(programId||'class_grouped');requirementId=String(requirementId||'');const next=!!input.checked,count=existingDeliveryCount(programId,requirementId);if(count&&next!==configuredReading(programId,requirementId)&&!confirm(`Este requisito ya tiene ${count} entrega${count===1?'':'s'} guardada${count===1?'':'s'}.\n\nCambiar la asignación no eliminará entregas anteriores. ¿Deseas continuar?`)){input.checked=!next;return;}readingDraft(programId)[requirementId]=next;if(next)modeDraft(programId)[requirementId]=false;markReportConfigDirty(programId);renderIndications();setTimeout(()=>sgl5078OpenReadingAssignment(programId),0);};
  window.sgl5078SaveReportConfiguration=async function sgl5078SaveReportConfiguration(programId){if(currentUser()?.role!=='admin')return;programId=String(programId||v3ActiveProgramId||'class_grouped');const saveModes=dirtyModePrograms.has(programId),saveIndications=dirtyIndicationPrograms.has(programId);if(!saveModes&&!saveIndications)return toast('No hay cambios pendientes para guardar.');const requirements=v3ProgramRequirements(programId),docs=modeDraft(programId),reads=readingDraft(programId),map=modeMap(),now=isoNow(),actor=String(currentUser()?.id||''),draft=ensureIndicationDraft(programId),original=indicationOriginals[programId]||{};if(saveModes){for(const req of requirements){const key=modeKey(programId,req.id),rid=String(req.id);if(reads[rid])map[key]={mode:'reading_report',updatedAt:now,updatedBy:actor};else if(docs[rid])map[key]={mode:'document',updatedAt:now,updatedBy:actor};else delete map[key];}mirrorModeMap();}let indicationChanges=0;if(saveIndications){database.indicationRules=Array.isArray(database.indicationRules)?database.indicationRules:[];for(const req of requirements){const rid=String(req.id),next=String(draft[rid]??''),before=String(original[rid]??'');if(next===before)continue;let rule=generalIndication(programId,rid);const official=defaultIndicationText(req);if(rule&&next===official){const extras=Object.entries(rule.config||{}).some(([key,value])=>key!=='instructions'&&String(value??'').trim());if(!extras){rule.active=false;rule.updatedAt=now;rule.updatedBy=actor;indicationChanges++;continue;}}if(!rule){rule={id:newId('rule'),createdAt:now,createdBy:actor,active:true,programId,requirementId:rid,scope:'all',scopeId:'',config:{}};database.indicationRules.push(rule);}rule.active=true;rule.programId=programId;rule.requirementId=rid;rule.scope='all';rule.scopeId='';rule.config={...(rule.config||{}),instructions:next};rule.updatedAt=now;rule.updatedBy=actor;indicationChanges++;}}const docCount=requirements.filter(req=>docs[String(req.id)]).length,readCount=requirements.filter(req=>reads[String(req.id)]).length;try{await persist(true,{action:'Configuración de informes guardada',entity:'reportRequirementModes',detail:`${v3Program(programId)?.name||programId} · ${docCount} PDF/fotografías · ${readCount} informe${readCount===1?'':'s'} de lectura · ${indicationChanges} indicación${indicationChanges===1?'':'es'}`});delete modeDrafts[programId];delete readingDrafts[programId];delete indicationDrafts[programId];delete indicationOriginals[programId];dirtyModePrograms.delete(programId);dirtyIndicationPrograms.delete(programId);if(database.settings?.serverUrl&&typeof v3CanAttemptNetwork==='function'&&v3CanAttemptNetwork())await syncNow().catch(()=>{});renderIndications();toast(`Configuración guardada${indicationChanges?` · ${indicationChanges} indicación${indicationChanges===1?'':'es'}`:''}.`);}catch(error){toast(`No se pudo guardar la configuración: ${error.message||error}`);}};
  window.sgl5078DiscardReportConfiguration=function sgl5078DiscardReportConfiguration(programId){programId=String(programId||v3ActiveProgramId||'class_grouped');delete modeDrafts[programId];delete readingDrafts[programId];delete indicationDrafts[programId];delete indicationOriginals[programId];dirtyModePrograms.delete(programId);dirtyIndicationPrograms.delete(programId);renderIndications();toast('Cambios de configuración descartados.');};

  /* Flujo documental. */
  let draft=null,previewUrl='';
  function clearPreview(){if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl='';}}
  function activeTask(ownerId,programId,requirementId){return (database.tasks||[]).find(task=>task&&task.active!==false&&!task.deletedAt&&!task.developmentAcceptedAt&&String(task.assigneeId||'')===String(ownerId||'')&&String(task.programId||'class_grouped')===String(programId||'class_grouped')&&String(task.requirementId||'')===String(requirementId||''))||null;}
  function canManageTask(task,actor=currentUser()){if(!task||!actor)return false;if(actor.role==='admin')return true;return actor.role==='tutor'&&accessibleAspirants(actor).some(person=>String(person.id)===String(task.assigneeId));}
  function documentEditable(ownerId,programId,requirementId){const actor=currentUser(),progress=v3EnsureProgramProgress(ownerId,programId),status=String(progress.status?.[requirementId]||'pending');return ['aspirant','pastor_aspirant'].includes(actor?.role)&&String(actor.id)===String(ownerId)&&!['in_review','approved'].includes(status);}
  async function blobDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
  async function sha256(blob){try{const digest=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer());return [...new Uint8Array(digest)].map(value=>value.toString(16).padStart(2,'0')).join('');}catch{return '';}}
  async function savedDocument(ownerId,programId,requirementId){const submission=submissionFor5078(ownerId,programId,requirementId),id=String(submission?.primaryDocumentId||'');if(!id)return null;let file=null;try{file=await fileGet(id);}catch{}if(!file?.dataUrl&&typeof window.sgl5047GetFileFast==='function')try{file=await window.sgl5047GetFileFast(id,{allowRemote:true});}catch{}if(file?.dataUrl)return {submission,file,blob:dataUrlToBlob(file.dataUrl)};return null;}
  function docName(requirementId){const ownerId=modalOwnerId||targetAspirant()?.id,programId=v3ModalProgramId||v3ActiveProgramId;return reportFileName({requirement:v3RequirementById(requirementId,programId)||{id:requirementId},aspirant:userById(ownerId)},'pdf');}
  async function photoPdf(photos){const pages=[];for(const photo of photos){const resource=await MusicMedia612.pdfPhotoResource(photo.dataUrl),page={w:612,h:792,commands:[],images:[]},margin=24,scale=Math.min((page.w-margin*2)/resource.w,(page.h-margin*2)/resource.h),w=resource.w*scale,h=resource.h*scale;pdfImage(page,resource,(page.w-w)/2,(page.h-h)/2,w,h);pages.push(page);}return buildVectorPdf(pages);}
