    if(!clean(data.impactPhrase))return {ok:false,message:'Completa la Frase de impacto.'};
    if(!clean(data.impactPage))return {ok:false,message:'Indica la página de la Frase de impacto.'};
    if(!clean(data.personal))return {ok:false,message:'Completa la aplicación en Vida personal.'};
    if(!clean(data.professional))return {ok:false,message:'Completa la aplicación en Vida profesional.'};
