    try{await persist(true,{action:'Informe de lectura guardado',entity:readingState.requirementId,detail:`${v3Program(readingState.programId)?.name||readingState.programId} · ${userById(readingState.ownerId)?.fullName||''}`});if(readingState===savingState){readingState.data=data;readingState.dirty=JSON.stringify(normalizedReading(collectReadingForm()))!==JSON.stringify(data);if(!options.quiet){filterRequirements?.();toast(hasContent?'Informe de lectura guardado.':'El formulario quedó vacío y el requisito volvió a PENDIENTE.');}if(!options.stay)await openReadingModal(readingState.requirementId);}return true;}catch(error){Object.keys(submission).forEach(key=>delete submission[key]);Object.assign(submission,old);progress.status[readingState.requirementId]=oldStatus;progress.updatedAt=oldProgressUpdated;toast(`No se pudo guardar el informe de lectura: ${error.message||error}`);return false;}
