    function block(text,{size=10,font='AR',color='0 0 0',indent=3,lineHeight=13,after=5,prefix=''}={}){
      const lines=wrapReadingText(text,CONTENT-2*indent-(prefix?16:0),size,font);
      lines.forEach((line,index)=>{ensure(lineHeight);if(prefix&&index===0)pdfText(page,prefix,L+indent,y,size,'AB',false,color);pdfText(page,line,L+indent+(prefix?16:0),y,size,font,false,color);y+=lineHeight;});y+=after;
    }
