        pdfText(page,'Vida',L+8,y+8,8,'AB',false,DARK);pdfText(page,label,L+8,y+19,8,'AB',false,DARK);if(offset)pdfText(page,'(continúa)',L+8,y+30,6.5,'AR',false,DARK);
