/* SGL 5.0.93 - Google OAuth Client ID persistente y sincronizado entre dispositivos. */
(()=>{
  'use strict';
  if(window.__sgl5091DriveOAuthSync)return;window.__sgl5091DriveOAuthSync=true;

  // La configuracion administrativa canonica debe incluir el Client ID publico de OAuth.
  // No es un secreto: identifica la aplicacion de escritorio ante Google.
  if(typeof v4214AdminView==='function'){
    const BASE_ADMIN_VIEW_5091=v4214AdminView;
    v4214AdminView=function v4214AdminViewSGL5091(source=database){
      const out=BASE_ADMIN_VIEW_5091(source)||{};
      if(source?.settings?.googleClientId!==undefined){
        out.settings=out.settings||{};
        out.settings.googleClientId=String(source.settings.googleClientId||'').trim();
      }
      return out;
    };
  }

  // Guardar Configuracion debe generar un parche aun cuando el unico cambio sea Google OAuth.
  if(typeof v4214FallbackPatch==='function'){
    const BASE_ADMIN_FALLBACK_5091=v4214FallbackPatch;
    v4214FallbackPatch=function v4214FallbackPatchSGL5091(auditEvent){
      const patch=BASE_ADMIN_FALLBACK_5091(auditEvent)||{};
      const entity=String(auditEvent?.entity||''),action=String(auditEvent?.action||'');
      if(entity==='settings'||action==='Configuración actualizada'){
        patch.settings={...(patch.settings||{}),googleClientId:String(database?.settings?.googleClientId||'').trim()};
      }
      return patch;
    };
  }

  // Una descarga canonica antigua no debe borrar el Client ID que ya estaba guardado localmente.
  if(typeof v3ApplyServerSnapshot==='function'){
    const BASE_APPLY_SNAPSHOT_5091=v3ApplyServerSnapshot;
    v3ApplyServerSnapshot=async function v3ApplyServerSnapshotSGL5091(snapshot,notification=null){
      const localClientId=String(database?.settings?.googleClientId||'').trim();
      const result=await BASE_APPLY_SNAPSHOT_5091.call(this,snapshot,notification);
      database.settings=database.settings||{};
      if(!String(database.settings.googleClientId||'').trim()&&localClientId){
        database.settings.googleClientId=localClientId;
        await kvSet('database',database).catch(()=>{});
      }
      return result;
    };
  }
})();

