    const active=document.activeElement;if(!(active===editor||editor.contains(active)))return;
    const scroller=editor.closest('.sgl5037-paper-viewport')||editor.closest('.sgl5039-paper-viewport');if(!scroller)return;
    const rect=(typeof sgl504ReportCaretRect==='function'?sgl504ReportCaretRect(editor):null),view=scroller.getBoundingClientRect(),toolbar=modal.querySelector('.sgl5093-mobile-toolbar')?.getBoundingClientRect(),vv=window.visualViewport;
    if(!rect||!Number.isFinite(rect.top)||!Number.isFinite(rect.bottom))return;
    const visualTop=Math.round(vv?.offsetTop||0),visualBottom=Math.round((vv?.offsetTop||0)+(vv?.height||window.innerHeight));
    const topLimit=Math.max(view.top+12,visualTop+8),bottomLimit=Math.min(view.bottom-12,(toolbar?.top||visualBottom)-8,visualBottom-8);
    if(bottomLimit<=topLimit+70)return;

    // 5.5: además de mantener visible el cursor, reservamos contexto equivalente
    // a unas cinco líneas por encima. En Android evita que el teclado deje solo
    // una o dos líneas visibles y parezca que el texto nuevo desapareció.
