      row.querySelectorAll('.sgl5088-delete-progress').forEach(node=>node.remove());
      const requirementId=String(row.getAttribute('data-sgl5059-requirement')||row.getAttribute('data-sgl5058-requirement')||'');if(!requirementId)return;
      if(!finalDriveStateR2(owner.id,programId,requirementId))return;
      row.classList.add('sgl56r2-finalized-requirement');
      row.classList.remove('sgl5058-requirement-approved');
      row.querySelectorAll('.sgl5089-view-document,.sgl5090-drive-icon,.sgl5088-delete-progress,.sgl5087-cancel-review').forEach(node=>node.remove());
      const host=row.querySelector('.req-actions')||row.querySelector('.actions');
