      const button=document.createElement('button');button.type='button';button.className='btn ghost small sgl54-report-action sgl54-icon-only sgl56r2-delete-progress-report';button.title='Eliminar avance';button.setAttribute('aria-label','Eliminar avance');button.innerHTML=resetIconR2();
      button.addEventListener('click',event=>{event.stopPropagation();if(typeof window.sgl5088DeleteRequirementProgress==='function')window.sgl5088DeleteRequirementProgress(programId,ownerId,requirementId);});
      actions.appendChild(button);
