    const tiles=(req.reading_plan||[]).map((plan,index)=>{const entry=sgl519NormalizeEntry(readings[plan.id]||{}),complete=entry.completed;return `<article class="sgl519-plan-tile ${complete?'done':'pending'}"><div class="sgl519-plan-number">${String(index+1).padStart(2,'0')}</div><div class="sgl519-plan-copy"><b>${esc(plan.passage)}</b><small>${complete?`${formatDate(entry.date||'')} · ${esc(entry.favoriteVerses||'Registrada')}`:'Lectura pendiente'}</small></div><button type="button" class="btn ${complete?'ghost':'primary'} small" onclick="openReading('${plan.id}')">${complete?(editable?'Editar':'Ver'):(editable?'Registrar':'Pendiente')}</button></article>`;}).join('');
