    const cards=requirements.map(req=>{const readings=sgl519ReadingMap(aspirant.id,req),done=sgl519Completed(req,readings),total=req.reading_plan?.length||0,percent=total?Math.round(done*100/total):0,nextPlan=(req.reading_plan||[]).find(item=>!readings[item.id]?.completed);return `<article class="card sgl519-requirement-card"><div class="card-head"><div><span class="chip blue">${esc(req.id)}</span><h3>${esc(req.official_text)}</h3></div><strong>${done}/${total}</strong></div><div class="sgl519-card-progress"><i style="width:${percent}%"></i></div><div class="sgl519-card-actions">${nextPlan&&sgl519CanEdit(aspirant.id,req)?`<button class="btn primary" onclick="sgl519OpenReadingQuick('${req.id}','${nextPlan.id}')">Continuar: ${esc(nextPlan.passage)}</button>`:''}<button class="btn ghost" onclick="openBibleRequirement('${req.id}')">${done?'Ver plan':'Abrir plan'}</button>${done?`<button class="btn ghost" onclick="sgl519OpenReadingSummary('${req.id}')">Ver avances</button>`:''}</div></article>`;}).join('');
