      const corrections=buttons.filter(button=>{const text=String(button.textContent||'').trim().toLowerCase(),onclick=String(button.getAttribute('onclick')||'');return onclick.includes("reviewRequirement('needs_changes')")||text==='recomendar modificacion'||text==='recomendar modificaci\u00f3n'||text==='solicitar correccion'||text==='solicitar correcci\u00f3n';});
