    showModal(`<div class="modal sgl520-reader-modal"><div class="sgl520-reader-head"><button type="button" class="btn ghost sgl520-reader-back" onclick="sgl520ReturnFromReader()">Volver</button><div><small>Mi conexi\u00f3n con Dios</small><h3>${esc(sgl520DisplayPassage(plan.passage))}</h3><span id="sgl520_reader_version">Preparando lectura...</span></div><div class="sgl520-font-controls"><button type="button" aria-label="Reducir texto" onclick="sgl520AdjustReaderFont(-1)">A-</button><button type="button" aria-label="Aumentar texto" onclick="sgl520AdjustReaderFont(1)">A+</button></div></div><div id="sgl520_reader_body" class="sgl520-reader-body"><div class="sgl520-reader-loading">Preparando el pasaje...</div></div><div class="sgl520-reader-foot"><span id="sgl520_reader_count">${selected.size} seleccionado${selected.size===1?'':'s'}</span><button type="button" class="btn primary" onclick="sgl520ApplyReaderSelection()">Usar selecci\u00f3n y volver</button></div></div>`);
