  window.sgl520RetryPassageReader=function(){const reader=window.__SGL520_READER__;if(!reader)return;const body=document.getElementById('sgl520_reader_body');if(body)body.innerHTML='<div class="sgl520-reader-loading">Actualizando biblioteca...</div>';sgl520LoadReaderContent(reader);};
  window.sgl520ToggleReaderVerse=function(button){const reader=window.__SGL520_READER__,reference=String(button?.dataset?.reference||'');if(!reader||!reference)return;if(reader.selected.has(reference))reader.selected.delete(reference);else reader.selected.add(reference);button.classList.toggle('selected',reader.selected.has(reference));button.setAttribute('aria-pressed',reader.selected.has(reference)?'true':'false');const check=button.querySelector('.sgl520-reader-check');if(check)check.textContent=reader.selected.has(reference)?'\u2713':'';sgl520UpdateReaderCount();};
  function sgl520UpdateReaderCount(){const reader=window.__SGL520_READER__,root=document.getElementById('sgl520_reader_count');if(root&&reader)root.textContent=`${reader.selected.size} seleccionado${reader.selected.size===1?'':'s'}`;}
  window.sgl520AdjustReaderFont=function(delta){const reader=window.__SGL520_READER__;if(!reader)return;reader.font=Math.max(.86,Math.min(1.32,reader.font+(Number(delta)||0)*.08));const sheet=document.querySelector('.sgl520-reader-sheet');if(sheet)sheet.style.setProperty('--sgl520-reader-scale',String(reader.font));};
  window.sgl520ApplyReaderSelection=function(){const reader=window.__SGL520_READER__;if(!reader)return;const key=sgl520DraftKey(reader.requirementId,reader.readingId),draft=window.__SGL520_READING_DRAFT__?.key===key?window.__SGL520_READING_DRAFT__:{key,requirementId:reader.requirementId,readingId:reader.readingId};draft.favoriteVerses=[...reader.selected].join('; ');window.__SGL520_READING_DRAFT__=draft;window.__SGL520_READER__=null;modalRequirementId=reader.requirementId;openReading(reader.readingId);};
  window.sgl520ReturnFromReader=function(){const reader=window.__SGL520_READER__;if(!reader)return;window.__SGL520_READER__=null;modalRequirementId=reader.requirementId;openReading(reader.readingId);};

  async function sgl520SelectPreference(value){
    const actor=currentUser?.();if(!actor)return;const versions=sgl520VersionList();
    if(value==='__club__'){actor.bibleVersionPreference='club';actor.bibleVersionId=null;}else if(versions.some(item=>String(item.id)===String(value))){actor.bibleVersionPreference='custom';actor.bibleVersionId=String(value);}else return;
    await persist(true,{action:'Preferencia biblica actualizada',entity:actor.id,detail:value==='__club__'?'Version del Club':(sgl520EffectiveVersion(actor)?.name||value)});await sgl520ResolveBibleFile(sgl520EffectiveVersion(actor));renderSettings();toast('Preferencia de lectura actualizada.');
  }
  window.sgl520SelectBiblePreference=sgl520SelectPreference;

  async function sgl520ImportBibleVersion(file){
    if(!file||currentUser()?.role!=='admin')return;
    try{
      const text=await file.text(),lower=file.name.toLowerCase();let suggested=file.name.replace(/\.(json|txt|vpl)$/i,''),licenseNote='Copia autorizada cargada por el Administrador',verses={};
      const add=(book,chapter,verse,verseText)=>{const code=bibleBookCode(book);if(!sgl520Canon(code)||typeof verseText!=='string'||!verseText.trim())return;verses[`${code}|${Number(chapter)}|${Number(verse)}`]=verseText.trim();};
      if(lower.endsWith('.json')){
        const parsed=JSON.parse(text);suggested=String(parsed.name||parsed.title||suggested);licenseNote=String(parsed.license||parsed.licence||licenseNote);const source=parsed.verses||parsed.text||parsed;
        let flatHits=0;
        for(const [reference,verseText] of Object.entries(source||{})){
          if(typeof verseText!=='string')continue;const internal=reference.match(/^([1-3A-Z]{3})\|(\d+)\|(\d+)$/i);if(internal){const code=internal[1].toUpperCase();if(sgl520Canon(code)){verses[`${code}|${Number(internal[2])}|${Number(internal[3])}`]=verseText.trim();flatHits++;}continue;}const match=reference.match(/^((?:[123]\s*)?[^\d]+?)\s+(\d+):(\d+)$/);if(match){add(match[1],match[2],match[3],verseText);flatHits++;}
        }
        if(flatHits<10){
          for(const [bookName,chapters] of Object.entries(source||{})){if(!chapters||typeof chapters!=='object'||Array.isArray(chapters))continue;for(const [chapter,chapterData] of Object.entries(chapters)){if(!/^\d+$/.test(String(chapter))||!chapterData||typeof chapterData!=='object'||Array.isArray(chapterData))continue;for(const [verse,verseText] of Object.entries(chapterData)){if(/^\d+$/.test(String(verse))&&typeof verseText==='string')add(bookName,chapter,verse,verseText);}}}
        }
      }else{
        for(const line of text.split(/\r?\n/)){const match=line.trim().match(/^((?:[123]\s*)?[A-Za-z\u00c1\u00c9\u00cd\u00d3\u00da\u00dc\u00d1\u00e1\u00e9\u00ed\u00f3\u00fa\u00fc\u00f1. ]+?)\s+(\d+):(\d+)\s+(.+)$/);if(match)add(match[1],match[2],match[3],match[4]);}
      }
      const count=Object.keys(verses).length;if(count<10)throw new Error('No se reconocieron suficientes vers\u00edculos.');const chosen=prompt('Nombre que aparecer\u00e1 para esta versi\u00f3n:',suggested);if(!chosen)return;
      const now=isoNow(),fileId=newId('file'),existing=sgl520VersionList().find(item=>sgl520BookKey(item.name)===sgl520BookKey(chosen)),id=existing?.id||newId('bible');
      await filePut({id:fileId,ownerId:currentUser().id,kind:'bible_version',name:chosen,type:'application/json',size:new Blob([JSON.stringify(verses)]).size,verses,createdAt:now,updatedAt:now,bibleFormat:'SGL-BIBLE-2'});
      if(existing){Object.assign(existing,{name:chosen,fileId,license:licenseNote,verseCount:count,updatedAt:now,revision:Number(existing.revision||1)+1});}else database.bibleVersions.push({id,name:chosen,fileId,license:licenseNote,verseCount:count,installedAt:now,updatedAt:now,installedBy:currentUser().id,revision:1});
      database.settings.defaultBibleVersionId=id;currentUser().bibleVersionPreference='club';currentUser().bibleVersionId=null;
      await persist(true,{action:existing?'Version biblica actualizada':'Version biblica cargada',entity:id,detail:`${chosen} · ${count} versiculos`});renderSettings();toast(`${chosen}: ${count} vers\u00edculos disponibles.`);if(database.settings?.serverUrl&&navigator.onLine&&typeof syncNow==='function')syncNow().catch(()=>{});
    }catch(error){toast(`No se pudo cargar la versi\u00f3n: ${error.message}`);}
  }
  window.sgl520ImportBibleVersion=sgl520ImportBibleVersion;

  function sgl520PolishAdminLibrary(){
    const section=document.getElementById('sgl519_bible_settings');if(!section)return;const h=section.querySelector('h3');if(h)h.textContent='Biblioteca de versiones b\u00edblicas';const eyebrow=section.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent='Lectura B\u00edblica';const subtitle=section.querySelector('.subtitle');if(subtitle)subtitle.textContent='Carga una copia que tu organizaci\u00f3n tenga autorizaci\u00f3n para utilizar. SGL no incluye ni descarga textos b\u00edblicos de terceros.';const input=section.querySelector('input[type="file"]');if(input)input.setAttribute('onchange',"sgl520ImportBibleVersion(this.files[0]);this.value=''");const label=input?.closest('label');if(label?.childNodes?.[0])label.childNodes[0].nodeValue='Cargar versi\u00f3n';for(const small of section.querySelectorAll('.sgl519-version-row small'))small.textContent=small.textContent.replace(/versiculos/gi,'vers\u00edculos');
  }
  function sgl520AppendUserSettings(){
    const actor=currentUser?.(),root=document.getElementById('content');if(!actor||!root||document.getElementById('sgl520_bible_preference'))return;const versions=sgl520VersionList(),effective=sgl520EffectiveVersion(actor),pref=sgl520PreferenceValue(actor),clubDefault=versions.find(item=>String(item.id)===String(database.settings.defaultBibleVersionId||''))||versions[0]||null;
    root.insertAdjacentHTML('beforeend',`<section id="sgl520_bible_preference" class="card sgl520-bible-preference"><div class="card-head"><div><div class="eyebrow">Lectura B\u00edblica</div><h3>Versi\u00f3n preferida</h3><p class="subtitle" style="margin:0">Puedes seguir la versi\u00f3n predeterminada del Club o elegir otra de las versiones disponibles.</p></div></div>${versions.length?`<div class="sgl520-preference-row"><label class="field-group">Versi\u00f3n para mis lecturas<select class="field" onchange="sgl520SelectBiblePreference(this.value)"><option value="__club__" ${pref==='__club__'?'selected':''}>Usar versi\u00f3n del Club${clubDefault?` · ${esc(clubDefault.name)}`:''}</option>${versions.map(version=>`<option value="${version.id}" ${pref===String(version.id)?'selected':''}>${esc(version.name)}</option>`).join('')}</select></label><div class="notice"><b>En uso:</b> ${esc(effective?.name||'Sin versi\u00f3n')}. ${pref==='__club__'?'Se actualizar\u00e1 autom\u00e1ticamente cuando el Administrador cambie la versi\u00f3n del Club.':'Mantendr\u00e1s esta versi\u00f3n mientras siga disponible.'}</div></div>`:'<div class="notice warn">Todav\u00eda no hay versiones b\u00edblicas disponibles en el servidor.</div>'}</section>`);
  }
  function sgl520AfterSettings(){setTimeout(()=>{sgl520PolishAdminLibrary();sgl520AppendUserSettings();},20);}
  if(SGL520_BASE_RENDER_SETTINGS){renderSettings=function renderSettingsSGL520(...args){const result=SGL520_BASE_RENDER_SETTINGS.apply(this,args);sgl520AfterSettings();return result;};window.renderSettings=renderSettings;}

  function sgl520PolishBiblePage(){
    const root=document.getElementById('content');if(!root)return;const hero=root.querySelector('.sgl519-bible-hero');if(hero){const h=hero.querySelector('h1');if(h)h.textContent='Mi conexi\u00f3n con Dios';const p=hero.querySelector('p');if(p)p.textContent='Lee, marca tus vers\u00edculos favoritos y registra lo que Dios te ense\u00f1a en cada lectura.';const spans=[...hero.querySelectorAll('.sgl519-overall span')];if(spans[2])spans[2].textContent='versi\u00f3n b\u00edblica';}const next=root.querySelector('.sgl519-next-reading .eyebrow');if(next)next.textContent='Tu pr\u00f3xima lectura';const canon=root.querySelector('.sgl519-canon summary b');if(canon)canon.textContent='Biblia en orden can\u00f3nico';const canonSpan=root.querySelector('.sgl519-canon summary span');if(canonSpan)canonSpan.textContent='66 libros · consulta r\u00e1pida';setTop('Lectura b\u00edblica','Mi conexi\u00f3n con Dios');
  }
  if(SGL520_BASE_RENDER_BIBLE){renderBible=function renderBibleSGL520(...args){const result=SGL520_BASE_RENDER_BIBLE.apply(this,args);setTimeout(sgl520PolishBiblePage,0);return result;};window.renderBible=renderBible;}

  function sgl520LibraryFingerprint(){const v=sgl520EffectiveVersion();return v?`${v.id}|${v.fileId||''}|${v.revision||''}|${database.settings?.defaultBibleVersionId||''}|${sgl520PreferenceValue()}`:'none';}
  async function sgl520EnsureEffectiveFile(){const version=sgl520EffectiveVersion();if(!version)return null;return sgl520ResolveBibleFile(version);}
  if(SGL520_BASE_SYNC){
    syncNow=async function syncNowSGL520(...args){const before=sgl520LibraryFingerprint();const result=await SGL520_BASE_SYNC.apply(this,args);const after=sgl520LibraryFingerprint();if(before!==after)await sgl520EnsureEffectiveFile();if(before!==after&&currentPage==='bible')renderBible();return result;};window.syncNow=syncNow;
  }
  if(SGL520_BASE_PULL){
    v3PullServerUpdates=async function v3PullServerUpdatesSGL520(...args){const before=sgl520LibraryFingerprint();const result=await SGL520_BASE_PULL.apply(this,args);const after=sgl520LibraryFingerprint();if(before!==after)await sgl520EnsureEffectiveFile();if(before!==after&&currentPage==='bible')renderBible();return result;};window.v3PullServerUpdates=v3PullServerUpdates;
  }
  const sgl520Wake=()=>sgl520EnsureEffectiveFile().catch(()=>{});window.addEventListener('online',sgl520Wake,{passive:true});window.addEventListener('focus',sgl520Wake,{passive:true});document.addEventListener('visibilitychange',()=>{if(!document.hidden)sgl520Wake();});

  window.sgl520DisplayPassage=sgl520DisplayPassage;
