function sgl529NoticeRelevant(item,user=currentUser()){
  if(!item||!user?.id)return false;
  const uid=String(user.id),recipient=String(item.userId||item.recipientId||''),owner=String(item.ownerId||'');
  if(recipient&&recipient!==uid)return false;
  if(owner&&owner!==uid&&['aspirant','pastor_aspirant'].includes(user.role))return false;
  if(item.type==='admin_change_applied'){
    if(owner)return owner===uid;
    const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
    const message=normalize(item.message),name=normalize(user.fullName);
    const uniqueName=name&&(database.users||[]).filter(person=>normalize(person.fullName)===name).length===1;
    if(uniqueName&&/^(informe editado por administrador|usuario actualizado|usuario creado|instructor quitado de clase) - /.test(message))return message.split(/\s+[·-]\s+/).slice(1).some(part=>part===name);
    if(user.role==='instructor'&&message.startsWith('clase actualizada - '))return (database.classes||[]).some(cls=>(cls.assignedUserIds||[]).map(String).includes(uid)&&[cls.name,[cls.regular,cls.advanced].filter(Boolean).join(' + '),cls.regular].filter(Boolean).some(label=>message.slice('clase actualizada - '.length)===normalize(label)));
    return false;
  }
  if(recipient)return true;
  if(owner===uid)return true;
  if(owner&&item.type==='review_submitted'&&!['aspirant','pastor_aspirant'].includes(user.role))return accessibleAspirants(user).some(person=>String(person.id)===owner);
  return false;
}

