 v4212UpdateFloatingSyncBadge=function(){baseBadge();const b=document.getElementById('floating_sync');if(!b)return;const active=(database.syncQueue||[]).filter(x=>['queued','retry','sending'].includes(x.status)),keys=new Set(active.map(op=>op.requirementId?sgl546DocumentKey(op):op.id));b.dataset.pending=String(keys.size);b.textContent=keys.size?'S'+keys.size:'S';b.title=keys.size+' documento(s) o cambio(s) pendiente(s)';};
